schemas.schema-01-systematic.prisma:
/// Discussion Board Channels - This implements the requirement for multi-channel/forum environments from the original business requirements (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.3, 2.4). 
///
/// Channel represents a top-level grouping for boards/forums for both scalability and community segmentation. Maintains 3NF normalization by separating channel metadata from board or topic-specific data. For example, a platform with 'Politics', 'Economics', and 'International Relations' channels allows targeted thread organization and user permissions per channel.
///
/// Key relationships: referenced by boards in other domains (not directly here). 
/// Special behaviors: Disabling a channel hides all associated boards and content without deletion.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique channel identifier.
  id String @id @db.Uuid

  /// Channel code - Implements unique channel identifier for internal reference. Example: 'POLI', 'ECON'. Ensures normalization by providing atomic lookup field without duplication. Usage: for routing and analytics.
  code String

  /// Human-readable channel name - Implements user interface representation. Example: 'Politics', 'Economics'. Keeps display values separate from codes for flexibility.
  name String

  /// Extended channel description - For longer UI help text or onboarding popups. Atomic, nullable for optional UX.
  description String?

  /// Channel enabled status - Indicates whether this channel is active and visible to users. Fulfills configurability requirement without hard deletion.
  enabled Boolean

  /// Creation timestamp - When the channel was first created. Supports auditability, required for 3NF and not derived.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp - When channel metadata was last changed. Supports audit trails and user interface freshness.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Implements business rule: channels never hard-deleted, are flagged for removal. If null, not deleted; if set, should not be shown to users.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_categories discussionboard_categories[]

  @@unique([code])
  @@index([created_at])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Categories - This supports hierarchical topic grouping within channels, directly mapping to the business requirement for organized board structuring from 03_DiscussionBoard_User_Journeys_and_Workflows.md and 04_Requirements_and_Business_Rules.md (section 2.3, 2.4). 
///
/// Category allows grouping boards for navigational clarity and thematic relevance. Maintains 3NF normalization by atomically storing categories separate from boards or topics. Example: categories like 'International', 'Domestic', 'Elections', under a 'Politics' channel.
///
/// Key relationships: often referenced by boards (in other files); can support parent-child via 'parent_id' field if hierarchy is desired.
/// Special behaviors: Disabling a category hides its boards/topics from users but retains data.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique category identifier.
  id String @id @db.Uuid

  /// Belonged channel's {@link discussionboard_channels.id} - Associates the category with its parent channel, ensuring each category is correctly placed in the forum hierarchy. Enforces normalization by separating channel from category business logic.
  discussionboard_channel_id String @db.Uuid

  /// Optional parent category's {@link discussionboard_categories.id} - Enables category nesting for themes/subcategories. Null when top-level; fulfills 3NF by storing hierarchy atomically.
  parent_id String? @db.Uuid

  /// Category code - Atomic, unambiguous handle for programmatic reference. E.g., 'ELECTIONS'. Maintains normalization and allows unique lookups.
  code String

  /// Category name - Display string for UI, supports search and multilingual use. Atomic, not derived.
  name String

  /// Long category description - For help popups, onboarding, or detailed UI. Nullable, kept atomic for 3NF.
  description String?

  /// Category enabled state - Fulfills admin business rule for soft-hiding categories without data loss.
  enabled Boolean

  /// Creation timestamp - For audit/logging, non-derived.
  created_at DateTime @db.Timestamptz

  /// Update timestamp - Last metadata modification. Maintains full normalization and is not derived.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Category is hidden, not deleted. 3NF compliant, nullable for full retention/audit support.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_categories_channel_id discussionboard_channels @relation(fields: [discussionboard_channel_id], references: [id], onDelete: Cascade)
  fk_discussionboard_categories_parent_id discussionboard_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussionboard_categories[] @relation("recursive")
  discussionboard_boards discussionboard_boards[]

  @@index([parent_id])

  @@unique([discussionboard_channel_id, code])
  @@index([discussionboard_channel_id])
  @@index([enabled])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Global Settings - Implements central configuration management as required in business rules (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.6 and 3). 
///
/// Allows admin and system-wide settings to be referenced from code and API. All settings are atomic key-value pairs, fully normalized (no pre-calculated aggregates). For example: spam filter thresholds, maintenance modes, global flags. This model is NOT used for user-specific settings (those are in other components).
///
/// Key relationships: None (standalone configuration repository).
/// Special behaviors: Only admin users can modify; changes are logged in the audit records.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique configuration setting row.
  id String @id @db.Uuid

  /// Setting key - Atomic string, namespaced for collision avoidance. E.g., 'maintenance_mode', 'email:smtp_host'. Fulfills 3NF by logically separating individual settings.
  key String

  /// Setting value - Actual config data, stored as string for flexibility (booleans stored as 'true'/'false', numbers as strings, etc.). Remains atomic and is not calculated/derived.
  value String

  /// Description of this setting - Used for admin UI and inline documentation. Nullable for flexibility. Maintains 3NF by separating metadata.
  description String?

  /// Timestamp when setting was first added. Fulfills audit/history requirement.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last modification for tracking. Business use: rollback or troubleshooting.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([created_at])
}

/// Discussion Board System Audit Trail - Implements mandatory audit logging (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.5, 4, 6). 
///
/// Captures all system-critical and admin/moderator actions for legal compliance, accountability, and troubleshooting. Maintains 3NF by separating each log entry as an atomic event record. Usage example: records when an admin changes a setting, a moderator deletes content, or a user is suspended. Read-only unless system/admin privilege.
///
/// Key relationships: References acting user in other actor components (not handled here).
/// Special behaviors: Entries are immutable and must not be modified/deleted except by hard data retention policies.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit log entry.
  id String @id @db.Uuid

  /// Audit action description - Atomic, non-derived string classifying the action (e.g., 'SETTING_UPDATE', 'ACCOUNT_SUSPEND'). Fully normalized: each event is one row. Examples: 'BOARD_CREATE', 'POST_DELETE', 'WARNING_ISSUED'.
  action String

  /// ID of user performing the action - Cross-references actors (members, moderators, admins) in other domains. Fulfills audit traceability requirement by unambiguously linking log to user. This is NOT a foreign key to allow for actor deletion scenarios.
  actor_id String @db.Uuid

  /// Target table/entity affected - Describes what system entity was changed (e.g., 'discussionboard_boards', 'discussionboard_threads'). Key for traceability and reporting.
  target_table String?

  /// ID of affected entity - When applicable, stores the row/entity affected by the event. Separate from 'actor_id'. Nullable for actions like login, where there may be no entity affected.
  target_id String? @db.Uuid

  /// Additional details - JSON string or extended data for complex actions (e.g., before/after snapshot). Fully atomic as business rule prohibits redundancy.
  details String?

  /// Audit entry creation timestamp - Required, non-derived, for every action (full audit compliance).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([actor_id])
  @@index([action])
  @@index([created_at])
}

schemas.schema-02-actors.prisma:
/// Member entity for board platform - Implements actor/user identity core from the Actors domain and requirement sections (esp. Role & Registration).  
///
/// This models the base member user that can register, post, comment, and interact. Maintains full 3NF normalization—member preferences, authentications, roles, and profile are handled in related tables. Used when linking posts, comments, reports, notifications to a unique user identity.
///
/// Example usage: Track who authored a thread, likes a post, or receives a notification.
///
/// Key relationships: Links to profiles, authentications, suspensions, moderator/admin entities. 
/// Special behaviors: Member can only have one unique identity, unique email enforced at authentication level.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each member in the system.
  id String @id @db.Uuid

  /// Member join date/time - Implements audit/tracking requirement. Indicates when the member registered. Ensures normalization by placing date in member (not profile) for clear audit. E.g. "2025-07-22T11:00:00+09:00".
  joined_at DateTime @db.Timestamptz

  /// Current member status - Implements business rules on activation/suspension. Values like 'active', 'pending', or 'suspended'. For example, initial status is 'active'; if suspended, some privileges are blocked; status field reflects business logic, not derived from suspension table.
  status String

  //----
  // RELATIONS
  //----
  discussionboard_moderators discussionboard_moderators?
  discussionboard_admins discussionboard_admins?
  discussionboard_member_profiles discussionboard_member_profiles?
  discussionboard_member_authentications discussionboard_member_authentications[]
  discussionboard_member_suspensions discussionboard_member_suspensions[]
  discussionboard_threads discussionboard_threads[]
  discussionboard_posts discussionboard_posts[]
  discussionboard_comments discussionboard_comments[]
  discussionboard_post_likes discussionboard_post_likes[]
  discussionboard_post_dislikes discussionboard_post_dislikes[]
  discussionboard_comment_likes discussionboard_comment_likes[]
  discussionboard_comment_dislikes discussionboard_comment_dislikes[]
  discussionboard_post_reports discussionboard_post_reports[]
  discussionboard_comment_reports discussionboard_comment_reports[]
  discussionboard_tag_proposals discussionboard_tag_proposals[]
  discussionboard_reports discussionboard_reports[]
  discussionboard_suspension_records discussionboard_suspension_records[]
  discussionboard_warning_records discussionboard_warning_records[]
  discussionboard_content_flags discussionboard_content_flags[]
  discussionboard_notifications discussionboard_notifications[]
  discussionboard_member_notification_settings discussionboard_member_notification_settings?

  @@index([joined_at])
}

/// Moderator entity - Implements moderator elevation from requirements (Role & Permission, Moderation Workflows). 
///
/// Stores references to member IDs elevated as moderators. Maintains 3NF as separate table. E.g., a member can have a record here when promoted to moderator; demotion is soft by setting an end timestamp.
///
/// Key usage: Map member to moderator privileges, history, and actions.
/// Key relationships: Links to member, logs actions in discussionboard_moderator_actions.
/// Special behaviors: Only admins can add records; member cannot be moderator twice at the same time.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Link to the promoted member's {@link discussionboard_members.id}. Establishes which user is the moderator.
  discussionboard_member_id String @db.Uuid

  /// Datetime member became moderator. Implements audit and escalation requirement for privilege history.
  promoted_at DateTime @db.Timestamptz

  /// Datetime moderator stopped being moderator. Null if currently holds role. Maintains audit trail; 3NF (not in member base table).
  demoted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member_moderator_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_member_suspensions discussionboard_member_suspensions[]
  discussionboard_moderator_actions discussionboard_moderator_actions[]
  discussionboard_reports discussionboard_reports[]
  discussionboard_moderation_logs discussionboard_moderation_logs[]
  discussionboard_suspension_records discussionboard_suspension_records[]
  discussionboard_warning_records discussionboard_warning_records[]
  discussionboard_content_flags discussionboard_content_flags[]

  @@unique([discussionboard_member_id])
  @@index([promoted_at])
}

/// Admin entity - Implements admin user architecture per requirements. 
///
/// Records which members are elevated to admin status (system superuser). Keeps normalized; not merged with member or moderator. Usage: assign admin API permissions, log system config changes, etc.
///
/// Key relationships: FK to member. 
/// Special: Only unique for each member; admin may also be moderator.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Link to member who is admin. References {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Datetime admin privilege granted; implements privilege audit. For example, assigned by platform owner.
  elevated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member_admin_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_member_suspensions discussionboard_member_suspensions[]
  discussionboard_board_announcements discussionboard_board_announcements[]

  @@unique([discussionboard_member_id])
  @@index([elevated_at])
}

/// Member profile details - Implements requirements for profile management (user journeys, self-editable info, privacy compliance). 
///
/// Stores optional extended member info: display name, bio, links, avatar, etc. Strictly 3NF: profile data not mixed with authentication, roles, or business states.
///
/// Usage example: Display profile page; allow user edits; fulfill download-my-data requests.
///
/// Key relationships: Exists 0 or 1 per member, not required for minimal registration.
/// Special: All fields optional (nullable = true where privacy applies).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to the owner member. References {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Optional user-chosen display name. Implements flexible identity requirement, separate from authentication username, upholds normalization. E.g. "Jane D."
  display_name String?

  /// Short biography field. Implements requirements for expressive/optional profile data; null if user left blank. 3NF; not mixed with system identity.
  bio String?

  /// Avatar image URI - Implements profile customization; URI to profile image if present. Upholds normalization: actual file stored in separate attachment table.
  avatar_uri String? @db.VarChar(80000)

  /// Personal website URI. Optional extra info; good for professional profiles. Nulls preserved for privacy. 3NF compliance (not in auth).
  website String? @db.VarChar(80000)

  /// Optional location for user. Provides for geography-based statistics or voluntary self-disclosure; optional for privacy. 3NF (won’t be used for enforcement or regional rules).
  location String?

  //----
  // RELATIONS
  //----
  profile_member_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Member authentication methods - Implements secure credentials, multi-method login, and audit requirements. 
///
/// Stores hashed passwords, external ID references, last login timestamp, and auth tokens where needed. 3NF: authentication split into own table with FK to member. 
///
/// Usage: Support classic email/password, future-proof for SSO/OAuth extensions.
///
/// Relationships: Each member can have multiple credentials (for multi-provider login/fallback).
/// Security: No cleartext passwords; only hashed tokens or references. Unique per (provider, username/email).
///
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_authentications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to member identity this credential belongs to. References {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Authentication provider e.g. 'local', 'google', 'kakao'. Implements requirement for flexible login. Used in uniqueness check.
  provider String

  /// Provider-unique identity (e.g. email for local, user ID for external). Implements multi-method login and support for identification challenges.
  provider_identifier String

  /// Hash of password or auth token (never cleartext). Null for OAuth-type logins (where external token not stored after exchange). Enforces security by avoiding password in main member table. 3NF compliance.
  password_hash String?

  /// Last successful login datetime for credential. Implements auditing per security NFR.
  last_login_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  auth_member_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([provider, provider_identifier])
  @@index([discussionboard_member_id])
  @@index([last_login_at])
}

/// Records member suspensions for rules enforcement (Moderation/Business Rules).
///
/// Represents suspending/blocking users temporarily or permanently. Tracks when, why, and by whom suspension was issued or revoked. 3NF—suspension details not mixed with member core or moderator/action logs.
///
/// Usage: Determine posting eligibility, fulfill 2-year audit retention (business rule). Suspension info drives API/feature gating.
///
/// Relationships: FK to member. Optionally records moderator/admin who issued/ended action.
///
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_suspensions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to affected member. Indicates who is/was suspended. References {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// FK to moderator who issued suspension (if from moderator). References {@link discussionboard_moderators.id}. Null if action was admin only.
  issued_by_moderator_id String? @db.Uuid

  /// FK to admin who issued suspension (if admin). References {@link discussionboard_admins.id}. Null if not admin action.
  issued_by_admin_id String? @db.Uuid

  /// Suspension reason/notes. Implements business rule for tracking justification and fulfills audit requirement. E.g. 'Repeated off-topic posts'.
  reason String

  /// Suspension start date/time. Implements gating logic (when member loses privileges). Upholds normalization (event data outside status field).
  starts_at DateTime @db.Timestamptz

  /// Suspension end date/time (null if permanent/active). 3NF (not derived, always recorded as explicit field).
  ends_at DateTime? @db.Timestamptz

  /// When (if ever) suspension was revoked/cancelled before scheduled end. Null if not revoked or full term served.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  suspension_member_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  suspension_issued_by_moderator_fk discussionboard_moderators? @relation(fields: [issued_by_moderator_id], references: [id], onDelete: Cascade)
  suspension_issued_by_admin_fk discussionboard_admins? @relation(fields: [issued_by_admin_id], references: [id], onDelete: Cascade)

  @@index([issued_by_moderator_id])
  @@index([issued_by_admin_id])

  @@index([discussionboard_member_id])
  @@index([starts_at])
}

/// Moderator action logs for audit and transparency (Moderation & Business Rules). 
///
/// Stores immutable records of moderator intervention: edit, delete, warning, suspension, tag approval, etc. Implements requirements for transparency, reporting, and appeal/audit workflows. 
///
/// Strictly 3NF - action log is separated, not mixed with member core. Includes full details for future analytics and review.
///
/// Key relationships: FK to moderator who acted, affects other entities by reference. Used directly in admin dashboard, and for providing appeal evidence.
///
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderator_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to moderator who performed the action (must exist in moderator table). References {@link discussionboard_moderators.id}.
  discussionboard_moderator_id String @db.Uuid

  /// Type of action performed (e.g. 'edit_post', 'delete_comment', 'issue_warning', 'suspend_member', 'approve_tag'). Implements business rule for clear log granularity and enables filtered reports. No calculation—just event type storage.
  action_type String

  /// Type of entity affected (e.g. 'post', 'comment', 'member', 'tag'). Needed for correct log analysis and future extensibility.
  target_type String

  /// ID of target entity—may reference various tables depending on action_type/target_type. Implements need to audit what exact record was affected by an action. (No FK since polymorphic.)
  target_id String @db.Uuid

  /// Full description of action details, justification, or notes. Helps implement transparency & fulfill legal/audit/compliance requirements.
  details String

  /// Timestamp of when the action was taken. For reporting and workflow tracking.
  action_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  action_moderator_fk discussionboard_moderators @relation(fields: [discussionboard_moderator_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_moderator_id])
  @@index([action_at])
  @@index([action_type])
}

schemas.schema-03-boards.prisma:
/// Board definition entity - Implements section 2.3 Content Operations and 4. Business Rules, supporting organization of discussions by topic (e.g., 'Politics', 'Economics'). 
///
/// Business explanation: This table holds the definitions of all boards visible in the system, each representing a broad topical area. Fully normalized: each board is atomic with no denormalized or pre-calculated data. Example: 'Global Politics', 'Macroeconomics'.
///
/// Key relationships: May be referenced by board topics; may reference categories (from other components) for further organization. 
/// Special behaviors: Board codes must be unique.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_boards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the board entity.
  id String @id @db.Uuid

  /// Parent category's {@link discussionboard_categories.id}. Organizes boards under broader discussion categories (category is managed by another domain).
  discussionboard_category_id String @db.Uuid

  /// Board code - Implements unique identification for boards for routing and business logic. Example: 'POLITICS', 'ECONOMICS'. Ensures normalization; not derived from name. Usage: programmatic API references.
  code String

  /// Board name - Implements display and search requirements. Used for UI listing. Normalized atomic field.
  name String

  /// Board description - Implements business rule for onboarding and help text. Provides context to users. Example: 'Discuss current events and policy in global politics.'
  description String?

  /// Whether the board is currently active and visible to users. Supports moderation/administrative workflows. Implements part of business rule for board visibility.
  is_active Boolean

  /// Timestamp of board creation. Required for audit and governance. Used in onboarding and reporting. Not pre-calculated. Always present.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the board. Enables tracking of administrative changes. Part of audit trail compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  BoardCategory discussionboard_categories @relation(fields: [discussionboard_category_id], references: [id], onDelete: Cascade)

  discussionboard_board_topics discussionboard_board_topics[]
  discussionboard_board_announcements discussionboard_board_announcements[]
  discussionboard_threads discussionboard_threads[]

  @@unique([code])
  @@index([discussionboard_category_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Topics within each board - Implements section 2.3 Content Operations (thread creation) and logical separation of user-created conversations under boards.
///
/// Business explanation: Each topic is a user-defined thread for discussion within a specific board, such as 'Presidential Elections 2025'. Topics refer to boards and have atomic fields for normalization. Fully normalized; per-topic data only, no denormalized aggregates.
///
/// Key relationships: References discussionboard_boards as parent; referenced by threads (in another schema); references topic tags for categorization.
/// Special behaviors: Topic codes are unique per board; topics are never global.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_topics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the board topic entity.
  id String @id @db.Uuid

  /// Parent board's {@link discussionboard_boards.id}. Organizes this topic within a board. Required association for business logic and enforcement of domain boundaries.
  discussionboard_board_id String @db.Uuid

  /// Topic code, unique per board - Implements unique identification for user-facing links or moderation. Example: 'ELECTIONS', 'Q4_OUTLOOK'.
  code String

  /// Topic title - Implements user requirement for conversation subjects. Example: '2025 Presidential Elections Discussion'. Normalized atomic field.
  title String

  /// Descriptive summary of the topic for onboarding/search. Example: 'A space to debate strategies, candidates, and international impact.'
  description String?

  /// Creator's {@link discussionboard_members.id}. Reference to the member who created the topic. Implements functional requirement for traceability and audit.
  created_by_member_id String @db.Uuid

  /// Creation timestamp. Used for ordering and audit trails, required by audit and reporting requirements.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the topic, for audit trail and modification control.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  TopicBoard discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_board_id, code])
  @@index([discussionboard_board_id])
  @@index([created_by_member_id])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Topic tag definitions - Implements requirement for curated, moderated topical tagging of discussions (see business rules section 4 and functional requirement 2.4).
///
/// Business explanation: Stores curated list of tags that can be assigned to topics, supporting search and categorization. Fully normalized - tags are atomic and not denormalized. Proposed tags managed elsewhere; this table is only for approved/curated tags.
///
/// Key relationships: Referenced by board topics or threads for categorization. 
/// Special behaviors: Uniqueness constraint on tag name; tags are not auto-accepted and require moderator/admin approval via separate processes.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_topic_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the topic tag entity.
  id String @id @db.Uuid

  /// Tag name (unique) - Implements business rule for curated tags. Example: 'Elections', 'Policy', 'Economics'. Searchable and atomic for normalization.
  name String

  /// Whether tag is enabled for assignment to topics or threads. Implements moderation requirement for hidden/disabled tags.
  is_active Boolean

  /// Timestamp of tag creation - supports audit and governance. Always present.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp, supporting change tracking for moderation/audit.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
  @@index([is_active])
}

/// Moderator/admin announcement entity - Implements requirement 2.6 (Notifications & Communication), enabling information dissemination within boards.
///
/// Business explanation: Contains announcements or system messages linked to specific boards (e.g., rule updates, special events). Announcements are always linked to a board, have a title/body, and track who published them. Fully normalized, no denormalized aggregates. 
///
/// Key relationships: References discussionboard_boards, admin/moderator (publisher) via foreign keys. Referenced by notification logic in other components for in-app/email alerts.
/// Special behaviors: Soft deletion supported via deleted_at. Announcements must be orderable by creation timestamp.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_board_announcements {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the announcement.
  id String @id @db.Uuid

  /// Target board's {@link discussionboard_boards.id}. All announcements are scoped to a specific board. Implements section 2.6 Notification flows.
  discussionboard_board_id String @db.Uuid

  /// Admin/moderator's {@link discussionboard_admins.id} who published the announcement. Used for audit and permission control.
  published_by_admin_id String @db.Uuid

  /// Announcement title - Implements requirement for concise notification. Example: 'Rule Change: Civility Policy Updated'.
  title String

  /// Full message body - Implements detailed notification requirement. Markdown supported. Example: 'The board's civility policy has changed...'.
  body String

  /// If true, announcement is 'sticky' on board; implements business rule for highlighting key messages. Only one active pin per board at a time (enforced in API logic).
  is_pinned Boolean

  /// Creation timestamp; enables ordering and audit trace.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp for tracking changes and audit.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp; if not null, announcement is hidden but not physically deleted (supports audit/legal retention).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  AnnouncementBoard discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)
  AnnouncementPublisher discussionboard_admins @relation(fields: [published_by_admin_id], references: [id], onDelete: Cascade)

  @@index([published_by_admin_id])

  @@index([discussionboard_board_id])
  @@index([is_pinned])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-threads.prisma:
/// Discussion Thread entity - This implements the foundational requirement for organizing topic-based discussions (see 04_DiscussionBoard_Requirements_and_Business_Rules.md, 2.3, 2.4). 
///
/// Represents a top-level topic or conversation within a board, containing metadata about the origin, categorization, and lifecycle of the thread. Maintains 3NF compliance by separating threads from posts/comments and referencing users and boards via foreign keys only. For example, a thread initiates a new discussion about a political or economic topic, to which users may contribute posts and comments.
///
/// Key relationships: Relates to boards (discussionboard_boards) and users (discussionboard_members) via foreign keys, and is referenced by posts. 
/// Special behaviors: Only thread creators or moderators/admins may edit/delete; status may be updated by system or moderation actions.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each thread.
  id String @id @db.Uuid

  /// Belonged board's {@link discussionboard_boards.id}. Thread is attached to a specific board or category.
  discussionboard_board_id String @db.Uuid

  /// Creator's {@link discussionboard_members.id}. Indicates which member started this thread.
  discussionboard_member_id String @db.Uuid

  /// Thread title - Implements requirement for descriptive, searchable topics. Must be unique within the board to prevent confusion. E.g., "Political Reform 2025: National Dialogue". Ensures normalization by storing only atomic string data.
  title String

  /// Thread description/body - Implements the need for detailed context. Business meaning: Introductory explanation; markdown supported. Ensures normalization by having one plain text field per thread.
  description String?

  /// Thread status - Implements business process control (e.g., 'open', 'closed', 'locked'). Used by moderators/admins to control discussion activity.
  status String

  /// Thread creation timestamp. Required for audit and ordering. 3NF compliance by storing time info only in this field.
  created_at DateTime @db.Timestamptz

  /// Thread update timestamp, maintained on edits. 3NF compliant.
  updated_at DateTime @db.Timestamptz

  /// Thread deletion/soft-delete timestamp. Nullable - only set if thread is deleted, keeps the data for retention/audit trail.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_threads_board discussionboard_boards @relation(fields: [discussionboard_board_id], references: [id], onDelete: Cascade)
  fk_threads_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_posts discussionboard_posts[]

  @@index([discussionboard_member_id])

  @@unique([discussionboard_board_id, title])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Post entity - Implements the core requirement for contributions within threads (see 04_DiscussionBoard_Requirements_and_Business_Rules.md, 2.3). Business purpose: Individual user posts, representing the main argument/content, within a given thread.
///
/// Each post is linked to a parent thread and the creating member, without duplicating thread or user information, thus maintaining strict normalization. E.g., a user expresses their view or arguments on a thread topic via a post.
///
/// Key relationships: Links to discussionboard_threads (the topic context) and discussionboard_members (the writer). Referenced by discussionboard_comments. 
/// Special behaviors: Can be edited/deleted by author or moderation subject to business rules.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each post.
  id String @id @db.Uuid

  /// Parent thread's {@link discussionboard_threads.id}. Defines which thread the post belongs to.
  discussionboard_thread_id String @db.Uuid

  /// Author member's {@link discussionboard_members.id}. Who wrote this post.
  discussionboard_member_id String @db.Uuid

  /// Main post content/body. Supports markdown for formatting. 3NF: Only pure text; no embedded member or thread info.
  body String

  /// Post creation time, for ordering and audit trail.
  created_at DateTime @db.Timestamptz

  /// Last update time, maintained on edits.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp. If null, post is visible; if set, post is deleted but retained for audit/legal purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_posts_thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_posts_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_comments discussionboard_comments[]
  discussionboard_post_attachments discussionboard_post_attachments[]
  discussionboard_post_likes discussionboard_post_likes[]
  discussionboard_post_dislikes discussionboard_post_dislikes[]
  discussionboard_post_reports discussionboard_post_reports[]
  discussionboard_content_flags discussionboard_content_flags[]

  @@index([discussionboard_member_id])

  @@index([discussionboard_thread_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Comment entity - Implements the requirement for threaded discussion under posts (see 04_DiscussionBoard_Requirements_and_Business_Rules.md, 2.3, 2.4). Business purpose: Enables replies to posts to enable in-depth discourse. 
///
/// Each comment references its parent post and (optionally) a parent comment (for nested replies). Maintains 3NF by referencing posts/members and storing only one level of content per field. For example, a user responds to a post or another user's argument.
///
/// Key relationships: Belongs to a post, created by a member. May link to a parent comment via foreign key (used for threading).
/// Special behaviors: Deletion is by setting deleted_at; edits update updated_at.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment.
  id String @id @db.Uuid

  /// Parent post's {@link discussionboard_posts.id}. Indicates which post the comment belongs to.
  discussionboard_post_id String @db.Uuid

  /// Comment author's {@link discussionboard_members.id}. Who wrote the comment.
  discussionboard_member_id String @db.Uuid

  /// Parent comment's {@link discussionboard_comments.id}. Enables threaded/nested replies. Nullable: only set for replies, not top-level comments.
  parent_id String? @db.Uuid

  /// Comment text/content. Business meaning: User's reply or discussion contribution. Normalized by storing only the text.
  body String

  /// Comment creation time. Used for ordering, audit, and display.
  created_at DateTime @db.Timestamptz

  /// Comment last update timestamp. Updated on edits for audit trail.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp. Preserves audit trail on deletion. Null if comment is still live.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comments_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_comments_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_comments_parent discussionboard_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussionboard_comments[] @relation("recursive")
  discussionboard_comment_replies_of_comment_id discussionboard_comment_replies[] @relation("discussionboard_comment_replies_of_comment_id")
  discussionboard_comment_replies_of_reply_id discussionboard_comment_replies? @relation("discussionboard_comment_replies_of_reply_id")
  discussionboard_comment_likes discussionboard_comment_likes[]
  discussionboard_comment_dislikes discussionboard_comment_dislikes[]
  discussionboard_comment_reports discussionboard_comment_reports[]
  discussionboard_content_flags discussionboard_content_flags[]

  @@index([discussionboard_member_id])
  @@index([parent_id])

  @@index([discussionboard_post_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Comment Reply entity (shallow reply index) - Implements explicit requirement for efficiently tracking direct comment replies (see 04_DiscussionBoard_Requirements_and_Business_Rules.md, discussion flows and threaded conversations).
///
/// This table maintains a normalized, junction-like mapping between comments and their direct replies. Useful for fast queries and enforcing reply relationships without embedding reply structure in-line. For example, every reply to a comment generates a row here, which can be traversed for building reply trees.
///
/// Key relationships: Both fields are foreign keys to discussionboard_comments. No duplication of content, ensuring 3NF.
/// Special behaviors: Deletion is handled via the referenced comment's own deletion marker.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_replies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment-reply relationship.
  id String @id @db.Uuid

  /// The parent comment {@link discussionboard_comments.id}.
  comment_id String @db.Uuid

  /// The direct reply comment {@link discussionboard_comments.id}.
  reply_id String @db.Uuid

  /// Reply relationship creation time. For audit trail and fast reply tree building.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comment_replies_comment discussionboard_comments @relation("discussionboard_comment_replies_of_comment_id", fields: [comment_id], references: [id], onDelete: Cascade)
  fk_comment_replies_reply discussionboard_comments @relation("discussionboard_comment_replies_of_reply_id", fields: [reply_id], references: [id], onDelete: Cascade)

  @@unique([reply_id])
  @@index([comment_id])
}

/// Discussion Post Attachment entity - Implements the need for posts to include attached files (04_DiscussionBoard_Requirements_and_Business_Rules.md, 2.3). Maintains normalized separation between a post and its files.
///
/// For example, a PDF, image, or spreadsheet attached to a discussion post. This keeps document/file metadata atomic and notifies the upload pipeline.
///
/// Key relationships: Linked to a discussionboard_post, and references file storage/URI.
/// Special behaviors: Deletions remove only the attachment, not the post.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each attachment.
  id String @id @db.Uuid

  /// Parent post's {@link discussionboard_posts.id}. The post this attachment belongs to.
  discussionboard_post_id String @db.Uuid

  /// Attachment file URI/location. Stores where the file is retrievable (S3, static hosting, etc.). Ensures normalization by keeping only the pointer, not embedded file.
  file_uri String @db.VarChar(80000)

  /// Display name of the attachment file. For user readability and identification; atomic text field per file.
  file_name String

  /// Attachment file MIME type (e.g., 'image/png', 'application/pdf'). Used to display/hide/preview accordingly. Business meaning: file type constraints and display logic.
  file_type String

  /// Timestamp when the attachment was uploaded. Enables audit/control flow.
  uploaded_at DateTime @db.Timestamptz

  /// Uploader's {@link discussionboard_members.id}. Member that uploaded the file. Not a foreign key but value is a UUID.
  uploaded_by String @db.Uuid

  //----
  // RELATIONS
  //----
  fk_post_attachments_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_post_id])
}

schemas.schema-05-interactions.prisma:
/// Stores each instance of a member liking a post. Implements Interaction requirement 2.1, which enables users to upvote/like posts for engagement and reputation calculations. Ensures full normalization (3NF) as this table only contains atomic data about the actor and the action, with all relationships explicit and no calculations or denormalization. Used whenever a member clicks 'like' on a post; supports trending features and user feedback mechanisms. Key relationships: references posts and members (already existing); unique on (post, member) to prevent duplicate likes; deletion cascades if the post or member is removed. Special: soft deletion not required, as unliking deletes the row.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_likes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each like entry.
  id String @id @db.Uuid

  /// Target post's {@link discussionboard_posts.id}. Links the like to a specific post.
  discussionboard_post_id String @db.Uuid

  /// Liking member's {@link discussionboard_members.id}. Identifies who liked the post.
  discussionboard_member_id String @db.Uuid

  /// Timestamp when the like was recorded. For audit logging and activity timelines. Implements reporting/audit requirements.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_post_like_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_post_like_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_post_id, discussionboard_member_id])
  @@index([created_at])
}

/// Stores each instance of a member disliking a post. Implements Interaction requirement 2.1 and 2.4, supporting user expression and automating moderation signals. Fully normalized (3NF) – atomic event of a dislike, with member and post identity, no calculations. Used when a member clicks 'dislike' on a post; feeds into moderation workflows. Key relationships: references to posts and members (already existing). Unique on (post, member) – one dislike per member per post. Special: row deleted if member cancels dislike.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_dislikes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each dislike entry.
  id String @id @db.Uuid

  /// Target post's {@link discussionboard_posts.id}. Connects dislike to post.
  discussionboard_post_id String @db.Uuid

  /// Disliking member's {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Timestamp when the dislike was made. Supports activity logs and reporting. Requirement: audit trail.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_post_dislike_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_post_dislike_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_post_id, discussionboard_member_id])
  @@index([created_at])
}

/// Tracks member likes for each comment. Implements Engagement requirements (2.1) for feedback on comment quality and interaction patterns. 3NF enforced: only references comment and actor, with no non-key dependencies. Example: Used to highlight 'popular' comments or calculate feedback scores. Key relationships: references comments and members. Each member may like a comment once (unique composite key). Deleting a comment/member removes likes. No denormalization.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_likes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment like.
  id String @id @db.Uuid

  /// Target comment's {@link discussionboard_comments.id}. Connects like to comment.
  discussionboard_comment_id String @db.Uuid

  /// Member's {@link discussionboard_members.id} who liked this comment.
  discussionboard_member_id String @db.Uuid

  /// Timestamp when this comment like was added. Required for activity logs and analysis.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comment_like_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_comment_like_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_comment_id, discussionboard_member_id])
  @@index([created_at])
}

/// Tracks member dislikes for each comment. Implements Engagement and Community Health requirements, enabling members to indicate problematic comments and feeding into moderation if thresholds surpassed. 3NF assured: each record is atomic and relates solely to a discrete user action and its object. Example: Used in triggering auto-flagging of comments. Uniqueness constraint prevents multiple dislikes by same member per comment. Connected to comments and members; row deleted if action undone.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_dislikes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment dislike.
  id String @id @db.Uuid

  /// Target comment's {@link discussionboard_comments.id}. Connects dislike to comment.
  discussionboard_comment_id String @db.Uuid

  /// Disliking member's {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Timestamp of comment dislike event. Supports moderation and audit logs.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comment_dislike_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_comment_dislike_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_comment_id, discussionboard_member_id])
  @@index([created_at])
}

/// Tracks when a member reports a post as inappropriate/spam. Implements functional and business rules (see sections 2.5, 4 in requirements), providing critical audit, moderation, and abuse detection. Fully normalized structure; all aggregates handled in reporting. Used to initiate moderation against a post, with links to member, post, and reason. Example: member flags a post for hate speech. Uniqueness constraint: one report per member per post. Key relationships: posts and members. Soft/hard deletes as per moderation outcome.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each report instance.
  id String @id @db.Uuid

  /// Flagged post's {@link discussionboard_posts.id}.
  discussionboard_post_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Human-readable reason for report (profanity, spam, etc.). Ensures normalization (atomic string data), no categorization here (handled elsewhere).
  reason String

  /// Timestamp when the report is made. Required for reporting flow and moderation traceability.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_post_report_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  fk_post_report_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_post_id, discussionboard_member_id])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks each time a member reports a comment as abusive/inappropriate. Implements moderation trigger requirements (sections 2.5, 4), audit logging, and rate-limiting enforcement. Strictly normalized (3NF), atomic event reference. Key relationships: attached to comment and member, no non-key attributes. One report per member per comment (unique composite key). Used for rate-limiting and moderation response automation. Example: 'report' on an offensive comment.
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment report.
  id String @id @db.Uuid

  /// Reported comment's {@link discussionboard_comments.id}.
  discussionboard_comment_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Reason for reporting the comment. Worksheets atomic requirement (normalized text, not categorical/aggregated).
  reason String

  /// Timestamp of report event; required for traceability (enterprise and legal purposes).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_comment_report_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)
  fk_comment_report_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id])

  @@unique([discussionboard_comment_id, discussionboard_member_id])
  @@index([created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks proposals for new topic tags, per business rule 4. Members propose tags awaiting moderator/admin review; supports platform curation, anti-abuse, and community-driven structure. Complies with 3NF: atomic proposal event, linked to actor (member), no state duplication. Example: member submits new tag 'economic-inequality'. Moderator resolves outside this table. One unique proposal per member/content/tag combo enforced. Relationships: member (who proposed), tag (proposed string), created_at. Special behaviors: tag field is plain string (proposed, not yet accepted).
///
/// @namespace Interactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_tag_proposals {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each tag proposal.
  id String @id @db.Uuid

  /// Member's {@link discussionboard_members.id} who proposed new tag.
  discussionboard_member_id String @db.Uuid

  /// Proposed topic tag string. Enforces normalization (atomic text), not categorized (categorization is result of moderation).
  proposed_tag String

  /// Timestamp of tag proposal. Used for workflow, audit, and process automation.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_tag_proposal_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, proposed_tag])
  @@index([created_at])
  @@index([proposed_tag(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-06-moderation.prisma:
/// Report entity - Implements the 'Moderation Reporting' requirement in the requirements analysis. This table tracks all member-initiated reports against posts/comments, ensuring normalized audit trails. For example, it records when a member reports a comment for abuse. Key relationships: reported_by_member_id and resolved_by_moderator_id both reference actors in the system. Special behaviors: maintains clear normalization, no denormalized status/actions.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each report.
  id String @id @db.Uuid

  /// Member's {@link discussionboard_members.id} who reported the content.
  reported_by_member_id String @db.Uuid

  /// Moderator's {@link discussionboard_moderators.id} who resolved this report (nullable if not resolved or auto-resolved).
  resolved_by_moderator_id String? @db.Uuid

  /// ID of reported post; only set if reporting a post. For normalization: one of post or comment must be filled, never both.
  target_post_id String? @db.Uuid

  /// ID of reported comment; only set if reporting a comment. For normalization: at least one of post or comment must be filled, never both.
  target_comment_id String? @db.Uuid

  /// Reason or message explaining the report. Atomic value to ensure normalization. For example, 'Spam' or 'Offensive language'.
  reason String

  /// Workflow status (e.g. 'pending', 'reviewed', 'actioned', 'dismissed'), enabling state-based moderator/automation tracking. Atomic string for normalization.
  status String

  /// When the report was created. Required for audit.
  created_at DateTime @db.Timestamptz

  /// When the report was resolved. Null if unresolved.
  resolved_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  reports_reported_by_member discussionboard_members @relation(fields: [reported_by_member_id], references: [id], onDelete: Cascade)
  reports_resolved_by_moderator discussionboard_moderators? @relation(fields: [resolved_by_moderator_id], references: [id], onDelete: Cascade)

  @@index([resolved_by_moderator_id])

  @@index([reported_by_member_id, created_at])
  @@index([status])
  @@index([target_post_id])
  @@index([target_comment_id])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation audit log - Implements the audit trail logging requirement, recording every moderator/admin action. Maintains normalized references to users, posts, comments, and detailed action descriptions. For example, logs when a moderator deletes a post. Key relationships: references moderator and affected entity (post/member/comment). Immutable records for compliance and user trust.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies a moderation log event.
  id String @id @db.Uuid

  /// Moderator's {@link discussionboard_moderators.id} who performed the logged moderation action.
  moderator_id String @db.Uuid

  /// ID of affected member, if action was user-targeted. Nullable for content-only actions.
  target_member_id String? @db.Uuid

  /// ID of affected post, if any. Null otherwise. Follows 3NF.
  target_post_id String? @db.Uuid

  /// ID of affected comment, if any. Null otherwise. Follows 3NF.
  target_comment_id String? @db.Uuid

  /// Normalized code describing the moderation action (e.g. 'deleted_post', 'suspended_user'). Required for consistent audit analysis.
  action_type String

  /// Freeform message for context/explanation of action. Maintains normalization by storing details, not computed fields.
  action_details String?

  /// When the moderation action took place. Required for time-based audits.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderation_logs_moderator discussionboard_moderators @relation(fields: [moderator_id], references: [id], onDelete: Cascade)

  @@index([moderator_id, created_at])
  @@index([action_type])
  @@index([action_details(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Suspension record - Implements the 'User Suspension' business rule, recording member suspensions (who, when, duration, revoked, etc) for audit and policy enforcement. Each record ties to the member, issuing moderator, and optionally, the revocation event. Clear normalization and referential integrity is enforced. Used by backend to enforce site restrictions on suspended users.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_suspension_records {
  //----
  // COLUMNS
  //----
  /// Primary Key. Identifies each suspension event.
  id String @id @db.Uuid

  /// Member's {@link discussionboard_members.id} who is suspended.
  suspended_member_id String @db.Uuid

  /// Moderator/admin's {@link discussionboard_moderators.id} issuing the suspension.
  issued_by_moderator_id String @db.Uuid

  /// Start time of suspension. Not nullable. For audit and enforcement logic.
  start_at DateTime @db.Timestamptz

  /// End time; null if permanent.
  end_at DateTime? @db.Timestamptz

  /// Moderator's reason for suspension, atomic string field. For example, 'Multiple code of conduct violations'.
  reason String

  /// True if the suspension has been formally revoked/freed before end_at. Supports workflow around appeal and moderation audit.
  revoked Boolean

  /// When the record was created.
  created_at DateTime @db.Timestamptz

  /// If revoked, when the suspension was ended early. Nullable.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  suspensions_member discussionboard_members @relation(fields: [suspended_member_id], references: [id], onDelete: Cascade)
  suspensions_moderator discussionboard_moderators @relation(fields: [issued_by_moderator_id], references: [id], onDelete: Cascade)

  @@index([issued_by_moderator_id])

  @@unique([suspended_member_id, start_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Warning record - Table for warnings issued to members. Implements 'Warnings and Escalations' from business rules. Tracks member, issuer, timestamp and detailed warning message. 3NF maintained: atomic fields, referenced users. Provides historical audit for escalation (multiple warnings before suspension) in normalization-compliant structure.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_warning_records {
  //----
  // COLUMNS
  //----
  /// Primary Key. Identifies each warning issued.
  id String @id @db.Uuid

  /// Warned member's {@link discussionboard_members.id}.
  warned_member_id String @db.Uuid

  /// Moderator's {@link discussionboard_moderators.id} who gave the warning.
  issued_by_moderator_id String @db.Uuid

  /// Flexible string reason or warning details. For example, '1st warning for inappropriate language.'
  reason String

  /// Timestamp of warning action.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  warnings_member discussionboard_members @relation(fields: [warned_member_id], references: [id], onDelete: Cascade)
  warnings_moderator discussionboard_moderators @relation(fields: [issued_by_moderator_id], references: [id], onDelete: Cascade)

  @@index([issued_by_moderator_id])

  @@unique([warned_member_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Content flag - Records system or moderator flags on threads/posts/comments for filtering, abuse detection or moderation queues. Implements 'Automated & Manual Flagging' requirement in requirements analysis. Fully normalized; foreign keys for user/content sources, atomic flag attributes. Used to queue content for moderator review or for auto-hide. Key relationships: references flagged post/comment and flag setter (by member or moderator).
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_content_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key for each flagged content event.
  id String @id @db.Uuid

  /// Flagged post's {@link discussionboard_posts.id}. Nullable if flag set on comment only.
  flagged_post_id String? @db.Uuid

  /// Flagged comment's {@link discussionboard_comments.id}. Nullable if flag set for post only.
  flagged_comment_id String? @db.Uuid

  /// Member's {@link discussionboard_members.id} if the flag was set manually. Nullable for automated/system flags.
  flagged_by_member_id String? @db.Uuid

  /// Moderator's {@link discussionboard_moderators.id} if the flag was set by a moderator. Nullable for automated/user flags.
  set_by_moderator_id String? @db.Uuid

  /// Atomic string code (e.g. 'spam', 'profanity', 'abuse') indicating flag reason.
  flag_type String

  /// Timestamp when flag was applied. Used for queue/audit compliance.
  flagged_at DateTime @db.Timestamptz

  /// True if the flag was set by system/automation (not a user or moderator). Maintains workflow clarity.
  auto_flagged Boolean

  //----
  // RELATIONS
  //----
  flags_post discussionboard_posts? @relation(fields: [flagged_post_id], references: [id], onDelete: Cascade)
  flags_comment discussionboard_comments? @relation(fields: [flagged_comment_id], references: [id], onDelete: Cascade)
  flags_member discussionboard_members? @relation(fields: [flagged_by_member_id], references: [id], onDelete: Cascade)
  flags_moderator discussionboard_moderators? @relation(fields: [set_by_moderator_id], references: [id], onDelete: Cascade)

  @@index([flagged_by_member_id])
  @@index([set_by_moderator_id])

  @@index([flag_type])
  @@index([flagged_post_id])
  @@index([flagged_comment_id])
}

schemas.schema-07-notifications.prisma:
/// Discussion Board Notification - Implements the notification delivery and logging requirement as detailed in the Requirements and Business Rules document. This model stores every notification event, such as a reply, mention, moderation update, or announcement, ensuring both reliable delivery and audit trail. Business purpose: accurately targets member accounts and tracks delivery/read states. Maintains strict 3NF normalization; each notification event is atomic, referring to exactly one recipient. Usage examples: generating member notification lists, marking messages as read, auditing notification delivery timelines. Key relationships: references discussionboard_members. Special behaviors: notification records are immutable and individually timestamped for delivery and read receipts.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the notification record.
  id String @id @db.Uuid

  /// Recipient member's {@link discussionboard_members.id}. References the user who receives this notification. Maintains referential integrity and supports targeted delivery.
  discussionboard_member_id String @db.Uuid

  /// Notification type, e.g. 'reply', 'mention', 'moderation', 'announcement'. Ensures atomic, categorical classification and supports filtering. Example: 'comment_reply', 'moderator_notice'.
  type String

  /// Notification title/subject. Briefly summarizes the event. Example: 'You've received a new comment reply.'
  title String

  /// Main content of the notification. Full textual message (e.g., 'Alice replied to your comment ...'). Normalized so that each field is atomic.
  body String

  /// URL to take the user directly to the relevant thread/post/moderation record. Atomic, optional field only present if the notification involves a direct link.
  url String? @db.VarChar(80000)

  /// Timestamp when the notification was delivered. Must be filled at the time of sending for traceability.
  delivered_at DateTime @db.Timestamptz

  /// Timestamp indicating when the user read the notification. Nullable if unread.
  read_at DateTime? @db.Timestamptz

  /// When notification record was created. Used for robust audit trails and business intelligence.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id, delivered_at])
  @@index([delivered_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Member Notification Settings - Implements members' personalized notification delivery settings as described in user journeys and requirements. Each record holds a member's per-channel and per-type notification preferences, supporting full normalization and a single row per user. Ensures no redundant or derived data. Typical use: allows members to mute certain notification types/channels while leaving others active. Key relationships: unique 1:1 with discussionboard_members. Special behaviors: one record per member; nullable only for updated_at if not yet updated. Used for programmatically querying or modifying user preferences.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_member_notification_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the settings record.
  id String @id @db.Uuid

  /// Member's {@link discussionboard_members.id}. Foreign key to the user's account. Enforces 1:1 mapping for user preference storage.
  discussionboard_member_id String @db.Uuid

  /// Whether in-app notifications are enabled for this member. Used for quick delivery flag checks. Example: true for active, false for muted in-app alerts.
  in_app_enabled Boolean

  /// Whether email notifications are enabled for this member. Ensures atomic tracking and filtering by delivery channel.
  email_enabled Boolean

  /// Whether to alert for replies to the member's content. Each flag is atomic, representing a unique notification scenario.
  reply_notification_enabled Boolean

  /// Whether to alert when the member is @mentioned. Stored atomically and normalized from other notification preferences.
  mention_notification_enabled Boolean

  /// Whether moderation alerts (actions, warnings, suspensions) are enabled for this user. Supports opt-out privacy/business use cases.
  moderation_notification_enabled Boolean

  /// Whether board-wide announcements should be pushed to this user. Complies with business requirement for member-driven preference control.
  announcement_notification_enabled Boolean

  /// When this preference record was created. For compliance and audit trail integrity.
  created_at DateTime @db.Timestamptz

  /// When this preference record was last updated. Accurate for reviewing user setting changes over time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id])
  @@index([in_app_enabled])
  @@index([email_enabled])
}

