schemas.schema-01-systematic.prisma:
/// Discussion Board Channels - This implements the requirement for multi-channel/forum environments from the original business requirements (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.3, 2.4). 
///
/// Channel represents a top-level grouping for boards/forums for both scalability and community segmentation. Maintains 3NF normalization by separating channel metadata from board or topic-specific data. For example, a platform with 'Politics', 'Economics', and 'International Relations' channels allows targeted thread organization and user permissions per channel.
///
/// Key relationships: referenced by boards in other domains (not directly here). 
/// Special behaviors: Disabling a channel hides all associated boards and content without deletion.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique channel identifier.
  id String @id @db.Uuid

  /// Channel code - Implements unique channel identifier for internal reference. Example: 'POLI', 'ECON'. Ensures normalization by providing atomic lookup field without duplication. Usage: for routing and analytics.
  code String

  /// Human-readable channel name - Implements user interface representation. Example: 'Politics', 'Economics'. Keeps display values separate from codes for flexibility.
  name String

  /// Extended channel description - For longer UI help text or onboarding popups. Atomic, nullable for optional UX.
  description String?

  /// Channel enabled status - Indicates whether this channel is active and visible to users. Fulfills configurability requirement without hard deletion.
  enabled Boolean

  /// Creation timestamp - When the channel was first created. Supports auditability, required for 3NF and not derived.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp - When channel metadata was last changed. Supports audit trails and user interface freshness.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Implements business rule: channels never hard-deleted, are flagged for removal. If null, not deleted; if set, should not be shown to users.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_categories discussionboard_categories[]

  @@unique([code])
  @@index([created_at])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Categories - This supports hierarchical topic grouping within channels, directly mapping to the business requirement for organized board structuring from 03_DiscussionBoard_User_Journeys_and_Workflows.md and 04_Requirements_and_Business_Rules.md (section 2.3, 2.4). 
///
/// Category allows grouping boards for navigational clarity and thematic relevance. Maintains 3NF normalization by atomically storing categories separate from boards or topics. Example: categories like 'International', 'Domestic', 'Elections', under a 'Politics' channel.
///
/// Key relationships: often referenced by boards (in other files); can support parent-child via 'parent_id' field if hierarchy is desired.
/// Special behaviors: Disabling a category hides its boards/topics from users but retains data.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique category identifier.
  id String @id @db.Uuid

  /// Belonged channel's {@link discussionboard_channels.id} - Associates the category with its parent channel, ensuring each category is correctly placed in the forum hierarchy. Enforces normalization by separating channel from category business logic.
  discussionboard_channel_id String @db.Uuid

  /// Optional parent category's {@link discussionboard_categories.id} - Enables category nesting for themes/subcategories. Null when top-level; fulfills 3NF by storing hierarchy atomically.
  parent_id String? @db.Uuid

  /// Category code - Atomic, unambiguous handle for programmatic reference. E.g., 'ELECTIONS'. Maintains normalization and allows unique lookups.
  code String

  /// Category name - Display string for UI, supports search and multilingual use. Atomic, not derived.
  name String

  /// Long category description - For help popups, onboarding, or detailed UI. Nullable, kept atomic for 3NF.
  description String?

  /// Category enabled state - Fulfills admin business rule for soft-hiding categories without data loss.
  enabled Boolean

  /// Creation timestamp - For audit/logging, non-derived.
  created_at DateTime @db.Timestamptz

  /// Update timestamp - Last metadata modification. Maintains full normalization and is not derived.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Category is hidden, not deleted. 3NF compliant, nullable for full retention/audit support.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_categories_channel_id discussionboard_channels    @relation(fields: [discussionboard_channel_id], references: [id], onDelete: Cascade)
  fk_discussionboard_categories_parent_id  discussionboard_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive              discussionboard_categories[] @relation("recursive")
  discussionboard_boards discussionboard_boards[]

  @@unique([discussionboard_channel_id, code])
  @@index([parent_id])
  @@index([discussionboard_channel_id])
  @@index([enabled])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Global Settings - Implements central configuration management as required in business rules (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.6 and 3). 
///
/// Allows admin and system-wide settings to be referenced from code and API. All settings are atomic key-value pairs, fully normalized (no pre-calculated aggregates). For example: spam filter thresholds, maintenance modes, global flags. This model is NOT used for user-specific settings (those are in other components).
///
/// Key relationships: None (standalone configuration repository).
/// Special behaviors: Only admin users can modify; changes are logged in the audit records.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique configuration setting row.
  id String @id @db.Uuid

  /// Setting key - Atomic string, namespaced for collision avoidance. E.g., 'maintenance_mode', 'email:smtp_host'. Fulfills 3NF by logically separating individual settings.
  key String

  /// Setting value - Actual config data, stored as string for flexibility (booleans stored as 'true'/'false', numbers as strings, etc.). Remains atomic and is not calculated/derived.
  value String

  /// Description of this setting - Used for admin UI and inline documentation. Nullable for flexibility. Maintains 3NF by separating metadata.
  description String?

  /// Timestamp when setting was first added. Fulfills audit/history requirement.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last modification for tracking. Business use: rollback or troubleshooting.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([created_at])
}

/// Discussion Board System Audit Trail - Implements mandatory audit logging (see 04_DiscussionBoard_Requirements_and_Business_Rules.md Section 2.5, 4, 6). 
///
/// Captures all system-critical and admin/moderator actions for legal compliance, accountability, and troubleshooting. Maintains 3NF by separating each log entry as an atomic event record. Usage example: records when an admin changes a setting, a moderator deletes content, or a user is suspended. Read-only unless system/admin privilege.
///
/// Key relationships: References acting user in other actor components (not handled here).
/// Special behaviors: Entries are immutable and must not be modified/deleted except by hard data retention policies.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique audit log entry.
  id String @id @db.Uuid

  /// Audit action description - Atomic, non-derived string classifying the action (e.g., 'SETTING_UPDATE', 'ACCOUNT_SUSPEND'). Fully normalized: each event is one row. Examples: 'BOARD_CREATE', 'POST_DELETE', 'WARNING_ISSUED'.
  action String

  /// ID of user performing the action - Cross-references actors (members, moderators, admins) in other domains. Fulfills audit traceability requirement by unambiguously linking log to user. This is NOT a foreign key to allow for actor deletion scenarios.
  actor_id String @db.Uuid

  /// Target table/entity affected - Describes what system entity was changed (e.g., 'discussionboard_boards', 'discussionboard_threads'). Key for traceability and reporting.
  target_table String?

  /// ID of affected entity - When applicable, stores the row/entity affected by the event. Separate from 'actor_id'. Nullable for actions like login, where there may be no entity affected.
  target_id String? @db.Uuid

  /// Additional details - JSON string or extended data for complex actions (e.g., before/after snapshot). Fully atomic as business rule prohibits redundancy.
  details String?

  /// Audit entry creation timestamp - Required, non-derived, for every action (full audit compliance).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([actor_id])
  @@index([action])
  @@index([created_at])
}

schemas.schema-02-actors.prisma:
/// Member entity for board platform - Implements actor/user identity core from the Actors domain and requirement sections (esp. Role & Registration).  
///
/// This models the base member user that can register, post, comment, and interact. Maintains full 3NF normalization—member preferences, authentications, roles, and profile are handled in related tables. Used when linking posts, comments, reports, notifications to a unique user identity.
///
/// Example usage: Track who authored a thread, likes a post, or receives a notification.
///
/// Key relationships: Links to profiles, authentications, suspensions, moderator/admin entities. 
/// Special behaviors: Member can only have one unique identity, unique email enforced at authentication level.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each member in the system.
  id String @id @db.Uuid

  /// Member join date/time - Implements audit/tracking requirement. Indicates when the member registered. Ensures normalization by placing date in member (not profile) for clear audit. E.g. "2025-07-22T11:00:00+09:00".
  joined_at DateTime @db.Timestamptz

  /// Current member status - Implements business rules on activation/suspension. Values like 'active', 'pending', or 'suspended'. For example, initial status is 'active'; if suspended, some privileges are blocked; status field reflects business logic, not derived from suspension table.
  status String

  //----
  // RELATIONS
  //----
  discussionboard_moderators                   discussionboard_moderators?
  discussionboard_admins                       discussionboard_admins?
  discussionboard_member_profiles              discussionboard_member_profiles?
  discussionboard_member_authentications       discussionboard_member_authentications[]
  discussionboard_member_suspensions           discussionboard_member_suspensions[]
  discussionboard_threads                      discussionboard_threads[]
  discussionboard_posts                        discussionboard_posts[]
  discussionboard_comments                     discussionboard_comments[]
  discussionboard_post_likes                   discussionboard_post_likes[]
  discussionboard_post_dislikes                discussionboard_post_dislikes[]
  discussionboard_comment_likes                discussionboard_comment_likes[]
  discussionboard_comment_dislikes             discussionboard_comment_dislikes[]
  discussionboard_post_reports                 discussionboard_post_reports[]
  discussionboard_comment_reports              discussionboard_comment_reports[]
  discussionboard_tag_proposals                discussionboard_tag_proposals[]
  discussionboard_reports                      discussionboard_reports[]
  discussionboard_suspension_records           discussionboard_suspension_records[]
  discussionboard_warning_records              discussionboard_warning_records[]
  discussionboard_content_flags                discussionboard_content_flags[]
  discussionboard_notifications                discussionboard_notifications[]
  discussionboard_member_notification_settings discussionboard_member_notification_settings?

  @@index([joined_at])
}

/// Moderator entity - Implements moderator elevation from requirements (Role & Permission, Moderation Workflows). 
///
/// Stores references to member IDs elevated as moderators. Maintains 3NF as separate table. E.g., a member can have a record here when promoted to moderator; demotion is soft by setting an end timestamp.
///
/// Key usage: Map member to moderator privileges, history, and actions.
/// Key relationships: Links to member, logs actions in discussionboard_moderator_actions.
/// Special behaviors: Only admins can add records; member cannot be moderator twice at the same time.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Link to the promoted member's {@link discussionboard_members.id}. Establishes which user is the moderator.
  discussionboard_member_id String @db.Uuid

  /// Datetime member became moderator. Implements audit and escalation requirement for privilege history.
  promoted_at DateTime @db.Timestamptz

  /// Datetime moderator stopped being moderator. Null if currently holds role. Maintains audit trail; 3NF (not in member base table).
  demoted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member_moderator_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_member_suspensions discussionboard_member_suspensions[]
  discussionboard_moderator_actions  discussionboard_moderator_actions[]
  discussionboard_reports            discussionboard_reports[]
  discussionboard_moderation_logs    discussionboard_moderation_logs[]
  discussionboard_suspension_records discussionboard_suspension_records[]
  discussionboard_warning_records    discussionboard_warning_records[]
  discussionboard_content_flags      discussionboard_content_flags[]

  @@unique([discussionboard_member_id])
  @@index([promoted_at])
}

/// Admin entity - Implements admin user architecture per requirements. 
///
/// Records which members are elevated to admin status (system superuser). Keeps normalized; not merged with member or moderator. Usage: assign admin API permissions, log system config changes, etc.
///
/// Key relationships: FK to member. 
/// Special: Only unique for each member; admin may also be moderator.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Link to member who is admin. References {@link discussionboard_members.id}.
  discussionboard_member_id String @db.Uuid

  /// Datetime admin privilege granted; implements privilege audit. For example, assigned by platform owner.
  elevated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member_admin_fk discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  discussionboard_member_suspensions  discussionboard_member_suspensions[]
  discussionboard_board_announcements discussionboard_board_announcements[]

  @@unique([discussionboard_member_id])
