schemas.schema-03-boards.prisma:
/// Board definition entity - Implements section 2.3 Content Operations and 4. Business Rules, supporting organization of discussions by topic (e.g., 'Politics', 'Economics'). 
///
/// Business explanation: This table holds the definitions of all boards visible in the system, each representing a broad topical area. Fully normalized: each board is atomic with no denormalized or pre-calculated data. Example: 'Global Politics', 'Macroeconomics'.
///
/// Key relationships: May be referenced by board topics; may reference categories (from other components) for further organization. 
/// Special behaviors: Board codes must be unique.
///
/// @namespace Boards
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_boards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the board entity.
  id String @id @db.Uuid

  /// Parent category's {@link discussionboard_categories.id}. Organizes boards under broader discussion categories (category is managed by another domain).
  discussionboard_category_id String @db.Uuid

  /// Board code - Implements unique identification for boards for routing and business logic. Example: 'POLITICS', 'ECONOMICS'. Ensures normalization; not derived from name. Usage: programmatic API references.
  code String

  /// Board name - Implements display and search requirements. Used for UI listing. Normalized atomic field.
  name String

  /// Board description - Implements business rule for onboarding and help text. Provides context to users. Example: 'Discuss current events and policy in global politics.'
  description String?

  /// Whether the board is currently active and visible to users. Supports moderation/administrative workflows. Implements part of business rule for board visibility.
  is_active Boolean

  /// Timestamp of board creation. Required for audit and governance. Used in onboarding and reporting. Not pre-calculated. Always present.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the board. Enables tracking of administrative changes. Part of audit trail compliance.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  BoardCategory discussionboard_categories @relation(fields: [discussionboard_category_id], references: [id], onDelete: Cascade)

  discussionboard_board_topics        discussionboard_board_topics[]
