  TestValidator.equals("fields present")(Object.keys(fetchedAdmin).sort())(["id","discussionboard_post_id","discussionboard_member_id","reason","created_at"].sort());

  // 4. Retrieve as reporting member
  const fetchedSelf: IDiscussionboardPostReport = await api.functional.discussionboard.interactions.postReports.getById(connection, {
