) {
  // 1. Register a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a profile for the new member with all valid fields
  const profileInput: IDiscussionBoardMemberProfile.ICreate = {
    discussionboard_member_id: member.id,
    display_name: "Test User",
    bio: "Enthusiastic member of the discussion board!",
