export async function test_api_discussionboard_test_update_member_profile_owner_and_admin_verification(
  connection: api.IConnection,
) {
  // 1. Register a new member (profile owner)
  const owner = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
