  // Attempt to delete Member A's profile as B (simulate role-switch by just re-using connection)
  await TestValidator.error("non-owner cannot delete profile")(() =>
    api.functional.discussionboard.actors.memberProfiles.eraseById(connection, {
      id: profileA.id,
    })
  );

  // 4. Register Member C
  const memberC = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(memberC);
  // Register a profile for Member C
  const profileC = await api.functional.discussionboard.actors.memberProfiles.post(connection, {
    body: {
      discussionboard_member_id: memberC.id,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.content()()(),
      avatar_uri: null,
      website: null,
      location: null,
    },
  });
  typia.assert(profileC);

  // Pretend current connection is an admin, delete profileC
  // (Since there is no real admin API, this simply simulates elevated privilege: in a real test suite, connection swapping would be required)
  const deleteResultC = await api.functional.discussionboard.actors.memberProfiles.eraseById(connection, {
    id: profileC.id,
  });
  typia.assert(deleteResultC);
  TestValidator.equals("admin delete profile id")(deleteResultC.id)(profileC.id);
  TestValidator.equals("admin delete status")(deleteResultC.status)("deleted");

  // 5. Attempt to delete already-deleted profile (should fail or return clear status)
  await TestValidator.error("deleting already deleted profile fails")(() =>
    api.functional.discussionboard.actors.memberProfiles.eraseById(connection, {
      id: profileC.id,
    })
  );
  await TestValidator.error("deleting deleted or nonexistent profile fails")(() =>
    api.functional.discussionboard.actors.memberProfiles.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 6. Confirm deleting a profile does not remove member entity itself
  // MemberC should still exist
  TestValidator.equals("member C still active")(memberC.status)("active");
}

