  TestValidator.equals("revoked_at null for new, unrevoked record")(fetched.revoked_at)(null);
  TestValidator.equals("start_at matches")(fetched.start_at)(suspensionCreateInput.start_at);

  // 4. Attempt to fetch a suspension record with a non-existent random ID
  await TestValidator.error("fetch non-existent suspension record returns error or 404")(() =>
    api.functional.discussionboard.moderation.suspensionRecords.getById(connection, {
