 * and that all details match the record as created: action, actor, target table/id, details, and creation timestamp.
 *
 * **Workflow Steps:**
 * 1. Assign admin role to a random discussion board member by creating a DiscussionBoardAdmins record.
 * 2. Create an audit log entry as that admin (actor_id references the admin member ID) with all fields filled.
 * 3. Retrieve the audit log entry by its unique ID as an admin.
 * 4. Assert that all returned fields match what was initially stored—including action, actor_id, target_table, target_id, details, and valid timestamp.
 */
export async function test_api_discussionboard_systematic_auditLogs_getById(
  connection: api.IConnection,
) {
  // 1. Assign admin role to a member
  const member_id = typia.random<string & tags.Format<"uuid">>();
  const elevated_at = new Date().toISOString();
  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member_id,
      elevated_at,
    },
  });
  typia.assert(admin);

  // 2. Create an audit log entry as that admin
  const action = "SETTING_UPDATE";
  const target_table = "discussionboard_settings";
  const target_id = typia.random<string & tags.Format<"uuid">>();
  const details = "Changed site title from 'Old' to 'New'";
