 *   - Failures: exceeding daily quota (over 10 reports), missing required fields, 
 *     reporting non-existent or deleted comment, attempts by non-active/suspended members,
 *     and duplicate same-day report on same comment
 *   - Output verification for correctness of returned entity
 *
 * Steps:
 * 1. Create a member (reporter)
 * 2. Create a comment for reporting
 * 3. (SUCCESS) Reporter submits a valid report
 *     - Check: response contains correct reporter, comment, and timestamp
 * 4. (FAIL) Attempt report for non-existent comment ID
 * 5. (FAIL) Attempt report for (soft-)deleted comment
 * 6. (FAIL) Exceed daily report quota: submit 10 reports, then one more -- last must fail
 * 7. (FAIL) Suspended member attempts report (must fail)
 * 8. (FAIL) Duplicate report on same comment by same member, same day
 */
export async function test_api_discussionboard_test_create_comment_report_with_valid_and_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create a member (reporter)
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a comment for reporting
  const comment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Test comment for reporting.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 3. SUCCESS: Reporter submits a valid report
  const reason = "Spam or inappropriate content";
  const report = await api.functional.discussionboard.interactions.commentReports.post(
    connection,
    {
      body: {
        discussionboard_comment_id: comment.id,
        reason,
      } satisfies IDiscussionboardCommentReport.ICreate,
    },
  );
  typia.assert(report);
  TestValidator.equals("reporter matches")(report.discussionboard_member_id)(member.id);
  TestValidator.equals("comment matches")(report.discussionboard_comment_id)(comment.id);
  TestValidator.predicate("created_at is present")(!!report.created_at);

  // 4. FAIL: Non-existent comment ID
  await TestValidator.error("should fail: report non-existent comment")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
            reason: "Non-existent comment",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 5. FAIL: Deleted comment
  // Simulate by creating a comment and assuming deleted_at would make it ineligible
  const deletedComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Deleted comment.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(deletedComment);
  // Pretend this comment is now deleted (business logic would prevent report)
  await TestValidator.error("should fail: report deleted comment")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: deletedComment.id,
            reason: "Report deleted comment",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 6. FAIL: Exceed daily report quota: submit 10 valid reports, then one more (should fail)
  const quotaReports = [] as IDiscussionboardComment[];
  for (let i = 0; i < 10; ++i) {
    const toReport = await api.functional.discussionboard.threads.comments.post(
      connection,
      {
        body: {
          discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
          discussionboard_member_id: member.id,
          body: `Quota test comment ${i}`,
        } satisfies IDiscussionboardComment.ICreate,
      },
    );
    typia.assert(toReport);
    quotaReports.push(toReport);
    const reportResult = await api.functional.discussionboard.interactions.commentReports.post(
      connection,
      {
        body: {
          discussionboard_comment_id: toReport.id,
          reason: `Reason ${i}`,
        } satisfies IDiscussionboardCommentReport.ICreate,
      },
    );
    typia.assert(reportResult);
  }
  // Attempt 11th report (should fail)
  const extraComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "11th quota comment",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(extraComment);
  await TestValidator.error("should fail: exceed 10 reports/day")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: extraComment.id,
            reason: "Exceed quota",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 7. FAIL: Suspended member attempts to report
  const suspended = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "suspended",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(suspended);
  const suspendedComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: suspended.id,
        body: "Comment for suspended user report test.",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(suspendedComment);
  await TestValidator.error("should fail: suspended member cannot report")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: suspendedComment.id,
            reason: "Test by suspended member",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );

  // 8. FAIL: Duplicate report for same comment by same member, same day
  const dupeComment = await api.functional.discussionboard.threads.comments.post(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        body: "Comment to test duplicate report",
      } satisfies IDiscussionboardComment.ICreate,
    },
  );
  typia.assert(dupeComment);
  const dupeReport = await api.functional.discussionboard.interactions.commentReports.post(
    connection,
    {
      body: {
        discussionboard_comment_id: dupeComment.id,
        reason: "First report",
      } satisfies IDiscussionboardCommentReport.ICreate,
    },
  );
  typia.assert(dupeReport);
  await TestValidator.error("should fail: duplicate report on same comment by same user")(
    async () =>
      await api.functional.discussionboard.interactions.commentReports.post(
        connection,
        {
          body: {
            discussionboard_comment_id: dupeComment.id,
            reason: "Duplicate report",
          } satisfies IDiscussionboardCommentReport.ICreate,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Test moderator/admin update of a comment report (reason correction).
 *
 * Validates successful and failed update attempts to a comment report by ID in
 * the Discussion Board system:
 *
 * - Only a moderator/admin can update (correct reason for) a comment report.
 * - Non-privileged members cannot update reports (no privilege escalation).
 * - Attempts to update with forbidden fields do not succeed (type error, so skipped).
 * - Attempts to update non-existent report IDs result in error.
 * - Updating the same report twice (circular/repeat update) is allowed at the DTO level
 *   (no status field/lock), so both updates succeed if permitted.
 * - Simultaneous/concurrent updates as moderator/admin both succeed, last write wins.
 *
 * Steps in this test function:
 * 1. Register two members: one regular user, one moderator (simulated as both are just members by DTO).
 * 2. Regular member creates a comment.
 * 3. Regular member files a comment report for that comment.
 * 4. Moderator member updates the comment report's reason successfully; assert update propagates.
 * 5. Attempt to update a report with invalid ID as moderator (should error).
 * 6. Attempt by original reporting member to update the report (should error: forbidden).
 * 7. Concurrent/successive updates as moderator (simulate two quick updates; both allowed by current DTO).
 * 8. Documentation clarifies that, due to DTO/API limitations, status/resolution fields and true role handling are not implemented/testable.
 */
export async function test_api_discussionboard_test_update_comment_report_review_status_and_resolution(
  connection: api.IConnection,
) {
  // 1. Register members
  const member1Res = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member1Res);

  const member2Res = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member2Res);

  const member1Id = member1Res.id;
  const member2Id = member2Res.id;

  // 2. Create comment by member1
  const commentRes = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member1Id,
      body: "First comment for report test.",
      parent_id: null,
    },
  });
  typia.assert(commentRes);

  // 3. Member1 files a report against their own comment (for setup)
  const commentReportRes = await api.functional.discussionboard.interactions.commentReports.post(connection, {
    body: {
      discussionboard_comment_id: commentRes.id,
      reason: "Spam or inappropriate content.",
    },
  });
  typia.assert(commentReportRes);
  const reportId = commentReportRes.id;

  // 4. As moderator (member2), successfully update the report reason
  const updatedReason1 = "Updated reason by moderator: violation confirmed.";
  const updateRes1 = await api.functional.discussionboard.interactions.commentReports.putById(connection, {
    id: reportId,
    body: {
      reason: updatedReason1,
    },
  });
  typia.assert(updateRes1);
  TestValidator.equals("reason updated")(updateRes1.reason)(updatedReason1);
  TestValidator.equals("report id unchanged")(updateRes1.id)(reportId);

  // 5. Try to update non-existent report ID as moderator
  await TestValidator.error("non-existent report update errors")(
    async () => {
      await api.functional.discussionboard.interactions.commentReports.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // Likely not present in DB
        body: { reason: "Impossible update." },
      });
    },
  );

  // 6. Try to update report as regular member (simulate privilege check; business server should enforce this)
  //    (NOTE: system only accepts members by id; no role field/test possible with these DTOs)
  await TestValidator.error("reporting member cannot update report")(
    async () => {
      // Simulate operation as reporting member (member1)
      // In a real system, connection would reflect logged-in user; here assume backend checks forbidden
      await api.functional.discussionboard.interactions.commentReports.putById(connection, {
        id: reportId,
        body: { reason: "Attempted illicit update by member." },
      });
    },
  );

  // 7. Simulate successive/concurrent updates as moderator
  const updatedReason2 = "Moderator 2nd review.";
  const updateRes2 = await api.functional.discussionboard.interactions.commentReports.putById(connection, {
    id: reportId,
    body: {
      reason: updatedReason2,
    },
  });
  typia.assert(updateRes2);
  TestValidator.equals("reason updated again")(updateRes2.reason)(updatedReason2);
  TestValidator.equals("report id unchanged, again")(updateRes2.id)(reportId);

  // Forbidden-field/state/role scenarios cannot be directly tested as current DTO/API does not expose those fields.
}

