import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReply } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReply";

/**
 * End-to-end test for updating comment reply mapping (discussionboard_comment_replies) via the PUT endpoint.
 *
 * Validates the following scenarios:
 * 1. Successfully update an existing reply mapping to a new parent comment and verify the mapping is updated.
 * 2. Attempt to update the mapping to reference a parent or reply comment that does not exist (should error).
 * 3. Attempt to introduce a cycle in the comment hierarchy by updating mapping so that parent and reply form a loop, expecting business rule rejection.
 * 4. Attempt the update from a different member to check if insufficient permission triggers a forbidden/authorization error.
 *
 * Prerequisites:
 * - At least two members are created for permission/authorization testing.
 * - Several comments are created for mapping purposes.
 * - An initial reply mapping is created (to be updated in various cases).
 *
 * Steps:
 * 1. Create two members (memberA and memberB).
 * 2. Create at least three comments (root, child, extra) by these members.
 * 3. Create a reply mapping where one comment is a reply to another.
 * 4. Update the mapping to change the parent_id to a different (valid) comment, verify update is successful and reflected.
 * 5. Attempt to update to a non-existent comment id (parent or reply), expect error.
 * 6. Try to update mapping to create a cycle (parent=reply or parent is already a child), expect rejection.
 * 7. Attempt to update the mapping as the non-creator member, expect forbidden error.
 */
export async function test_api_discussionboard_test_update_comment_reply_mapping_with_valid_and_invalid_changes(
  connection: api.IConnection,
) {
  // 1. Create two discussion board members (memberA, memberB)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberB);

  // 2. Create three comments (root, child, extra)
  const discussionboard_post_id = typia.random<string & tags.Format<"uuid">>();
  const commentRoot = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id,
      discussionboard_member_id: memberA.id,
      body: "parent comment",
      parent_id: null
    } satisfies IDiscussionboardComment.ICreate
  });
  typia.assert(commentRoot);

  const commentChild = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id,
      discussionboard_member_id: memberA.id,
      body: "child reply",
      parent_id: commentRoot.id
    } satisfies IDiscussionboardComment.ICreate
  });
  typia.assert(commentChild);

  const commentExtra = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id,
      discussionboard_member_id: memberB.id,
      body: "extra comment",
      parent_id: null
    } satisfies IDiscussionboardComment.ICreate
  });
  typia.assert(commentExtra);

  // 3. Create initial reply mapping between root and child
  const replyMapping = await api.functional.discussionboard.threads.commentReplies.post(connection, {
    body: {
      comment_id: commentRoot.id,
      reply_id: commentChild.id,
    } satisfies IDiscussionboardCommentReply.ICreate,
  });
  typia.assert(replyMapping);

  // 4. Update mapping's comment_id to commentExtra (valid new parent), expect success
  const updatedMapping = await api.functional.discussionboard.threads.commentReplies.putById(connection, {
    id: replyMapping.id,
    body: { comment_id: commentExtra.id } satisfies IDiscussionboardCommentReply.IUpdate,
  });
  typia.assert(updatedMapping);
  TestValidator.equals("Update reflected")(updatedMapping.comment_id)(commentExtra.id);
  TestValidator.equals("Reply id unchanged")(updatedMapping.reply_id)(commentChild.id);

  // 5. Update mapping to non-existent comment_id, expect not found/validation error
  const NON_EXISTING_ID = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent comment as parent triggers error")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.putById(connection, {
        id: replyMapping.id,
        body: { comment_id: NON_EXISTING_ID } satisfies IDiscussionboardCommentReply.IUpdate,
      });
    },
  );
  await TestValidator.error("non-existent comment as reply triggers error")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.putById(connection, {
        id: replyMapping.id,
        body: { reply_id: NON_EXISTING_ID } satisfies IDiscussionboardCommentReply.IUpdate,
      });
    },
  );

  // 6. Try updating mapping to form a cycle (reply mapped as own parent)
  await TestValidator.error("cycle (reply mapped as own parent) triggers error")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.putById(connection, {
        id: replyMapping.id,
        body: { comment_id: commentChild.id, reply_id: commentChild.id } satisfies IDiscussionboardCommentReply.IUpdate,
      });
    },
  );
  // Optionally: try parent=child, reply=extra (if such logic introduces cycle)
  await TestValidator.error("cycle (parent and reply swapped) triggers error")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.putById(connection, {
        id: replyMapping.id,
        body: { comment_id: commentChild.id, reply_id: commentExtra.id } satisfies IDiscussionboardCommentReply.IUpdate,
      });
    },
  );

  // 7. Attempt forbidden update by non-creator member (simulate by swapping comments)
  await TestValidator.error("forbidden update by non-creator member")(
    async () => {
      await api.functional.discussionboard.threads.commentReplies.putById(connection, {
        id: replyMapping.id,
        body: { comment_id: commentRoot.id, reply_id: commentExtra.id } satisfies IDiscussionboardCommentReply.IUpdate,
      });
    },
  );
}

