import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IPageDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardMembers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 회원 개인정보 보호(비관리자 사용자 본인만 리스트 포함) 검증.
 *
 * 이 테스트는 다음을 확인합니다.
 *  - 일반 회원(관리자/모더레이터 아님)이 회원 목록을 조회할 때 본인 계정만 보이며,
 *    타인의 계정은 노출되지 않습니다.
 *  - 목록 결과에 민감/불필요 필드가 노출되지 않습니다(id, joined_at, status 외).
 *
 * 테스트 시나리오:
 * 1. 회원 두 명을 등록합니다(서로 다른 가입 일시).
 * 2. 두 번째 회원이 본인 세션이라고 가정(실제 로그인 엔드포인트 없음).
 * 3. 본인 계정으로 멤버 리스트 PATCH 요청.
 * 4. 반환되는 데이터가 오직 내 계정 하나인지 확인.
 * 5. 리스트 반환 객체(key)가 id/joined_at/status만 있는지 체크.
 * 6. 추가로 GET by ID 요청으로 본인(두 번째 계정) 정보도 재확인.
 */
export async function test_api_discussionboard_test_list_members_privacy_filtering_for_non_admin(
  connection: api.IConnection,
) {
  // 1. 회원 두 명 생성
  const memberA = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(), // 하루 전
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: new Date().toISOString(),
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(memberB);

  // 2. 본인 세션(memberB) 상태에서 회원 리스트(PATCH) 조회
  const page = await api.functional.discussionboard.actors.members.patch(
    connection,
    {
      body: {} satisfies IDiscussionboardMembers.IRequest,
    },
  );
  typia.assert(page);

  // 3. 리스트 반환이 본인 1건인지 확인
  TestValidator.equals("반환 회원 수==1")(page.data.length)(1);
  const ownProfile = page.data[0];
  TestValidator.equals("내 계정 id와 동일")(ownProfile.id)(memberB.id);

  // 4. 반환 객체에 id, joined_at, status만 존재하는지 체크(민감정보 유출 방지)
  TestValidator.predicate("허용 키만 존재")(Object.keys(ownProfile).every((k) => ["id", "joined_at", "status"].includes(k)));

  // 5. 본인 상세 조회(GET by ID) 후, 리스트 결과와 값 일치 재확인
  const selfById = await api.functional.discussionboard.actors.members.getById(
    connection,
    { id: memberB.id },
  );
  typia.assert(selfById);
  TestValidator.equals("상세조회 결과와 동일")(selfById)(ownProfile);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * Validates retrieval of complete member profile details by an admin user.
 *
 * This test ensures that after successfully creating a new member (using the POST endpoint),
 * an admin can obtain the full set of member details by member ID via the GET endpoint.
 *
 * Steps:
 * 1. Create a new member profile using the POST /discussionboard/actors/members endpoint.
 * 2. Retrieve the member's profile using GET /discussionboard/actors/members/{id} as an admin.
 * 3. Validate that all expected (including sensitive and non-sensitive) profile fields are returned.
 * 4. Assert that the returned member profile matches the created profile information exactly (within allowed fields).
 */
export async function test_api_discussionboard_actors_members_getById(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberInput: IDiscussionboardMembers.ICreate = {
    joined_at: typia.random<string & tags.Format<"date-time">>(),
    status: "active",
  };

  const createdMember: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(
    connection,
    { body: memberInput },
  );
  typia.assert(createdMember);

  // 2. Retrieve full member profile using GET by ID
  const retrievedMember: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.getById(
    connection,
    { id: createdMember.id },
  );
  typia.assert(retrievedMember);

  // 3. Validate all expected fields are present and match the POST input (excluding id which is generated)
  TestValidator.equals("id matches")(retrievedMember.id)(createdMember.id);
  TestValidator.equals("joined_at matches")(retrievedMember.joined_at)(memberInput.joined_at);
  TestValidator.equals("status matches")(retrievedMember.status)(memberInput.status);
}

