 *
 * Workflow:
 * 1. Register a new member (simulates self-registration).
 * 2. Use their own ID to fetch detail via GET (self-view context).
 * 3. Confirm all valid profile properties are returned (id, joined_at, status).
 * 4. Confirm no extra or forbidden/admin-only fields are present in the response.
 */
export async function test_api_discussionboard_actors_members_getById_test_get_self_detail_as_member_limited_fields(
