import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * Test updating a member's status via PUT as an administrator.
 *
 * This E2E test simulates an administrative action to update a board member's status field (such as setting to 'suspended').
 * 
 * Test workflow:
 * 1. Register a new member (with status 'active').
 * 2. As admin (no special authentication scope needed), update the member's status field to 'suspended'.
 * 3. Assert the response contains the correct ID, unchanged join date, and updated status.
 * 4. Attempt to update a non-existent member, ensuring an error is thrown.
 */
export async function test_api_discussionboard_test_update_member_status_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a new member (test subject) with status 'active'.
  const createInput: IDiscussionboardMembers.ICreate = {
    joined_at: new Date().toISOString(),
    status: "active",
  };
  const member = await api.functional.discussionboard.actors.members.post(connection, { body: createInput });
  typia.assert(member);

  // 2. Update the member's status to 'suspended' (admin scenario).
  const updateInput: IDiscussionboardMembers.IUpdate = { status: "suspended" };
  const updated = await api.functional.discussionboard.actors.members.putById(connection, {
    id: member.id,
    body: updateInput,
  });
  typia.assert(updated);
  // Validate fields: ID, join date/time, and updated status.
  TestValidator.equals("ID unchanged")(updated.id)(member.id);
  TestValidator.equals("Join date unchanged")(updated.joined_at)(member.joined_at);
  TestValidator.equals("Status updated")(updated.status)("suspended");

  // 3. Negative case: attempt update for a non-existent member - should throw.
  await TestValidator.error("Update should fail for non-existent member")(
    async () => {
      await api.functional.discussionboard.actors.members.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: { status: "inactive" },
      });
    },
  );
}

