import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and filtering tag proposals as a moderator or admin.
 *
 * This test verifies that:
 * - Tag proposals can be searched and filtered by tag string and member
 * - Pagination (limit/page/total) behaves correctly
 * - Members with and without proposals are both handled
 * - Multiple members can propose different tags
 * - Moderators/admins see all proposals; normal users either cannot access or have restricted access
 *
 * Steps:
 * 1. Create several members (at least 3, with randomized join dates/statuses)
 * 2. For a subset of those members, submit multiple tag proposals each with clearly different tag strings
 * 3. List all proposals with no filters as 'moderator'—verify all are returned and total matches insert count
 * 4. List proposals with filters (proposed_tag, member_id) and check filtered results and counts
 * 5. Test pagination: fetch a page with limit < total proposals, check returned count, and total-record count
 * 6. Confirm a member with no proposals does not appear in results for member-filtered queries
 * 7. Attempt to list as ordinary member—check access or confirm proper data restriction/denial
 *   (Not possible to simulate user roles with current APIs; step is explained only.)
 */
export async function test_api_discussionboard_test_list_tag_proposals_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create several members
  const members = await ArrayUtil.asyncRepeat(3)(async () => {
    const createMember = {
      joined_at: new Date(Date.now() - Math.floor(Math.random() * 1000000000)).toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate;
    const member = await api.functional.discussionboard.actors.members.post(connection, { body: createMember });
    typia.assert(member);
    return member;
  });

  // 2. For 2 of those members, submit multiple unique tag proposals
  const tagSamples = [
    "macroeconomics", "campaignfinance", "elections", "kpop", "AI", "openai", "musicbiz"
  ];
  const memberProps = await ArrayUtil.asyncMap(members.slice(0,2))(async (m, i) => {
    return ArrayUtil.asyncRepeat(2)(async (j) => {
      const tag = tagSamples[(i*2 + j) % tagSamples.length];
      const body = {
        discussionboard_member_id: m.id,
        proposed_tag: tag
      } satisfies IDiscussionboardTagProposal.ICreate;
      const proposal = await api.functional.discussionboard.interactions.tagProposals.post(connection, { body });
      typia.assert(proposal);
      return proposal;
    });
  });
  const proposals = memberProps.flat();

  // 3. List all proposals as admin/moderator (assumes test runner has elevated access)
  const allList = await api.functional.discussionboard.interactions.tagProposals.patch(connection, {
    body: {} satisfies IDiscussionboardTagProposal.IRequest
  });
  typia.assert(allList);
  TestValidator.equals("proposal count matches insert")(allList.data.length)(proposals.length);
  TestValidator.equals("pagination total records matches")(allList.pagination.records)(proposals.length);

  // 4. Filtering by proposed_tag exact match
  const filterTag = proposals[0].proposed_tag;
  const tagFilterList = await api.functional.discussionboard.interactions.tagProposals.patch(connection, {
    body: { proposed_tag: filterTag } satisfies IDiscussionboardTagProposal.IRequest
  });
  typia.assert(tagFilterList);
  TestValidator.predicate("all results match filter tag")(
    tagFilterList.data.every(x => x.proposed_tag === filterTag),
  );

  // Filtering by member
  const memberId = members[0].id;
  const memberFilterList = await api.functional.discussionboard.interactions.tagProposals.patch(connection, {
    body: { discussionboard_member_id: memberId } satisfies IDiscussionboardTagProposal.IRequest
  });
  typia.assert(memberFilterList);
  TestValidator.predicate("all results belong to member")(
    memberFilterList.data.every(x => x.discussionboard_member_id === memberId),
  );

  // 5. Pagination test - limit to 1
  const pagedList = await api.functional.discussionboard.interactions.tagProposals.patch(connection, {
    body: { limit: 1, page: 1 } satisfies IDiscussionboardTagProposal.IRequest
  });
  typia.assert(pagedList);
  TestValidator.equals("page size is 1")(pagedList.data.length)(1);
  TestValidator.equals("total record count matches")(pagedList.pagination.records)(proposals.length);

  // 6. Member with no proposals should yield zero
  const noPropMember = members[2];
  const noPropResult = await api.functional.discussionboard.interactions.tagProposals.patch(connection, {
    body: { discussionboard_member_id: noPropMember.id } satisfies IDiscussionboardTagProposal.IRequest
  });
  typia.assert(noPropResult);
  TestValidator.equals("no proposals for this member")(noPropResult.data.length)(0);

  // 7. Attempt to query as ordinary user — cannot test since no user role APIs exist
}

