/**
 * Test creation of new tag proposals as an active or suspended member.
 *
 * This test verifies that:
 *   - Active members can propose new tags when data is valid and unique.
 *   - Duplicate tag proposals by the same member are rejected.
 *   - Invalid tag content (e.g., too short, potentially banned) is rejected by validation.
 *   - Suspended members are prevented from creating proposals.
 *
 * Steps:
 * 1. Register a new active member (status: "active").
 * 2. Propose a unique, valid tag and verify success.
 * 3. Attempt to propose the same tag again (should fail).
 * 4. Try to propose an invalid tag (should fail).
 * 5. Suspend the member (reason: violation, open-ended).
 * 6. Try to propose a tag after suspension (should fail).
 */
export async function test_api_discussionboard_test_create_tag_proposal_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Register a new active member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Propose a unique, valid tag
  const validTag = `unique_tag_${RandomGenerator.alphaNumeric(8)}`;
  const tagProposal = await api.functional.discussionboard.interactions.tagProposals.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      proposed_tag: validTag,
    } satisfies IDiscussionboardTagProposal.ICreate,
  });
  typia.assert(tagProposal);
  TestValidator.equals("proposer matches")(tagProposal.discussionboard_member_id)(member.id);
  TestValidator.equals("proposed_tag matches")(tagProposal.proposed_tag)(validTag);

  // 3. Attempt to propose the same tag again (should fail)
  await TestValidator.error("duplicate proposal causes error")(() =>
    api.functional.discussionboard.interactions.tagProposals.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        proposed_tag: validTag,
      } satisfies IDiscussionboardTagProposal.ICreate,
    })
  );

  // 4. Try to propose an invalid tag (should fail)
  const invalidTag = "x";
  await TestValidator.error("invalid tag proposal causes error")(() =>
    api.functional.discussionboard.interactions.tagProposals.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        proposed_tag: invalidTag,
      } satisfies IDiscussionboardTagProposal.ICreate,
    })
  );

  // 5. Suspend the member (reason: policy violation, no end date)
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      reason: "Policy violation",
      starts_at: new Date().toISOString(),
      ends_at: null,
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(suspension);
  TestValidator.equals("suspended member matches")(suspension.discussionboard_member_id)(member.id);

  // 6. Try to propose a tag as the suspended member (should fail)
  await TestValidator.error("suspended member cannot create proposal")(() =>
    api.functional.discussionboard.interactions.tagProposals.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        proposed_tag: `another_tag_${RandomGenerator.alphaNumeric(8)}`,
      } satisfies IDiscussionboardTagProposal.ICreate,
    })
  );
}

