  TestValidator.equals("correct moderator returned for member1")(listByMember1.data[0].discussionboard_member_id)(member1.id);

  // 5. Query active moderators with no member_id filter (should get both)
  const listAllActive = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
    },
  });
  typia.assert(listAllActive);
  const returnedIds = listAllActive.data.map((x) => x.discussionboard_member_id);
  TestValidator.predicate("both member1 and member2 are returned")(returnedIds.includes(member1.id) && returnedIds.includes(member2.id));

  // 6. Test promoted_from filter (after member1's promotion, only member2)
  const listAfter1 = await api.functional.discussionboard.actors.moderators.patch(connection, {
    body: {
      is_active: true,
      promoted_from: promoted2.promoted_at,
    },
  });
  typia.assert(listAfter1);
  TestValidator.equals("only member2 returned for promoted_from")(listAfter1.data.length)(1);
  TestValidator.equals("member2 returned for promoted_from")(listAfter1.data[0].discussionboard_member_id)(member2.id);

  // 7. Pagination: since IRequest doesn't have explicit page/limit, validate both expected moderators in full list
  TestValidator.equals("pagination returns both moderators")(listAllActive.data.map((m) => m.discussionboard_member_id).sort())([
    member1.id,
    member2.id,
  ].sort());
}

