import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";

/**
 * 테스트: Discussion Board 멤버 정지 등록 및 비즈니스 규칙 검증
 *
 * 이 테스트는 다음을 검증합니다:
 * 1. 관리 권한(관리자/모더레이터)을 가진 사용자가 유효한 사유, 시작/종료 시각으로 정상적으로 멤버 정지를 수행하고, 모든 반환 값이 요청값과 동일하며, 감사(Audit) 관련 필드가 올바르게 채워지는지 확인합니다.
 * 2. 이미 정지된 멤버를 중복 정지할 수 없음을 확인합니다.
 * 3. 권한 없는 사용자가 정지 요청 시 거부됨을 검증합니다.
 * 4. 정지 기간(일시적/영구), 사유(reason), 발행 주체(관리자/모더레이터) 조합 및 모든 필드 타입, null 처리, 비즈니스 규칙 위반 까지 아우르는 시나리오를 다룹니다.
 *
 * [진행 단계]
 * 1. (의존성) 정지 대상 일반 멤버 생성
 * 2. (의존성) 정지 발행자(관리자/모더레이터) 멤버 생성
 * 3. 관리자가 정상적으로 일시 정지 생성 시도 → 성공/응답 필드 검증
 * 4. 같은 대상을 동일 기간에 중복 정지 시도 → 오류 발생 검증
 * 5. 권한 없는 일반 사용자를 정지 발행인으로 지정해 요청 → 오류 발생 검증
 * 6. 영구 정지(ends_at=null) 시나리오 성공 여부 검증
 */
export async function test_api_discussionboard_test_create_member_suspension_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 정지 대상 일반 멤버 생성
  const targetMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(targetMember);

  // 2. 정지 발행 주체(관리자, 테스트에서는 별다른 role 구현 없이 일반 멤버로 생성)
  const adminIssuer = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(adminIssuer);

  // 3. 정상적인 일시 정지 진행
  const reason = "비정상 게시물 업로드로 인한 경고 정지";
  const startsAt = new Date(Date.now() + 1000 * 60).toISOString(); // 1분 후
  const endsAt = new Date(Date.now() + 1000 * 60 * 10).toISOString(); // 10분 후
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: targetMember.id,
      issued_by_admin_id: adminIssuer.id,
      issued_by_moderator_id: null,
      reason,
      starts_at: startsAt,
      ends_at: endsAt,
    },
  });
  typia.assert(suspension);
  TestValidator.equals("member ID")(suspension.discussionboard_member_id)(targetMember.id);
  TestValidator.equals("admin ID")(suspension.issued_by_admin_id)(adminIssuer.id);
  TestValidator.equals("moderator null")(suspension.issued_by_moderator_id)(null);
  TestValidator.equals("reason")(suspension.reason)(reason);
  TestValidator.equals("starts_at")(suspension.starts_at)(startsAt);
  TestValidator.equals("ends_at")(suspension.ends_at)(endsAt);

  // 4. 이미 정지된 멤버를 다시 정지하려 시도(중복 불가)
  await TestValidator.error("동일 멤버 중복 정지 예외")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
        body: {
          discussionboard_member_id: targetMember.id,
          issued_by_admin_id: adminIssuer.id,
          issued_by_moderator_id: null,
          reason: "중복 정지 시도",
          starts_at: startsAt,
          ends_at: endsAt,
        },
      });
    },
  );

  // 5. 권한 없는 일반 사용자가 정지 발행자로 지정될 경우 예외
  const unprivilegedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(unprivilegedMember);
  await TestValidator.error("권한 없는 사용자의 정지 시도 예외")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
        body: {
          discussionboard_member_id: targetMember.id,
          issued_by_admin_id: null,
          issued_by_moderator_id: unprivilegedMember.id,
          reason: "권한 없는 정지 발행 시도",
          starts_at: new Date(Date.now() + 1000 * 120).toISOString(),
          ends_at: new Date(Date.now() + 1000 * 180).toISOString(),
        },
      });
    },
  );

  // 6. 영구 정지(ends_at=null) 옵션 정상 동작 여부
  const permanentReason = "심각한 이용 약관 위반 영구 조치";
  const permStartsAt = new Date(Date.now() + 1000 * 200).toISOString();
  const permanent = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: targetMember.id,
      issued_by_admin_id: adminIssuer.id,
      issued_by_moderator_id: null,
      reason: permanentReason,
      starts_at: permStartsAt,
      ends_at: null,
    },
  });
  typia.assert(permanent);
  TestValidator.equals("permanent, ends_at null")(permanent.ends_at)(null);
  TestValidator.equals("permanent reason")(permanent.reason)(permanentReason);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
