import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";

/**
 * Validate member suspension overlap prevention.
 *
 * This test ensures that a member cannot have overlapping active suspensions. The test flow is:
 * 1. Create a member (the target to be suspended).
 * 2. Create another member who acts as the admin/moderator issuing the suspension.
 * 3. Issue the first suspension for the member, making it active.
 * 4. Attempt to create another active suspension for the same member (with overlapping period).
 *    - The API must reject the request, typically returning a 409 error.
 *    - The error response should clearly indicate that the member already has an active suspension.
 */
export async function test_api_discussionboard_actors_memberSuspensions_test_create_member_suspension_for_already_suspended_member(
  connection: api.IConnection,
) {
  // 1. Create target member
  const targetMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(targetMember);

  // 2. Create admin/moderator (issuer of the suspension)
  const admin = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  // 3. Issue initial (active) suspension for the member, valid for 7 days
  const now = new Date();
  const endsAt = new Date(now.getTime());
  endsAt.setDate(now.getDate() + 7);
  const initialSuspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: {
      discussionboard_member_id: targetMember.id,
      issued_by_admin_id: admin.id,
      reason: "Initial 7-day suspension.",
      starts_at: now.toISOString(),
      ends_at: endsAt.toISOString(),
    } satisfies IDiscussionBoardMemberSuspension.ICreate,
  });
  typia.assert(initialSuspension);

  // 4. Attempt a second overlapping (active) suspension for same member
  await TestValidator.error("Duplicate/overlapping suspension should result in error")(
    async () => {
      await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
        body: {
          discussionboard_member_id: targetMember.id,
          issued_by_admin_id: admin.id,
          reason: "Attempted duplicate overlap suspension.",
          starts_at: now.toISOString(), // Same as the first
          ends_at: endsAt.toISOString(),
        } satisfies IDiscussionBoardMemberSuspension.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionBoardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberSuspension";
import type { DiscussionboardMemberSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionboardMemberSuspension";

/**
 * Test updating a member suspension record, including privilege checks, business logic, and error scenarios.
 *
 * This test simulates the full workflow for updating an existing suspension:
 * 1. Create an admin (issuer) and a target member.
 * 2. Admin issues a suspension to the target member.
 * 3. Admin updates the suspension's ends_at date (extends).
 * 4. Admin updates only the reason text.
 * 5. Update both ends_at (shorten) and reason at once.
 * 6. Attempt update as unauthorized (non-admin/non-moderator) -> should fail with 403.
 * 7. Attempt to update immutable fields (not possible—fields not in IUpdate, type checker prevents).
 * 8. Attempt update with an invalid/nonexistent suspension ID -> should get 404.
 * 9. Mark suspension as revoked via revoked_at, then further updates are rejected/blocked (test error/no-op).
 * 10. Simulate expired: set ends_at to past and confirm further updates rejected/blocked.
 *
 * All assertions use typia.assert for type checks and TestValidator to confirm business and error logic.
 */
export async function test_api_discussionboard_test_update_member_suspension_valid_and_invalid(
  connection: api.IConnection,
) {
  // Step 1: Create admin (issuer) and target member
  const now = new Date();
  const admin: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  const member: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // Step 2: Admin issues a member suspension
  const originalEndsAt = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(); // 3 days from now
  const createSuspensionBody = {
    discussionboard_member_id: member.id,
    issued_by_admin_id: admin.id,
    reason: "Initial suspension due to terms violation.",
    starts_at: now.toISOString(),
    ends_at: originalEndsAt,
  } satisfies IDiscussionBoardMemberSuspension.ICreate;
  const suspension = await api.functional.discussionboard.actors.memberSuspensions.post(connection, {
    body: createSuspensionBody,
  });
  typia.assert(suspension);
  TestValidator.equals("created suspension matches input")(suspension.reason)(createSuspensionBody.reason);
  TestValidator.equals("created suspension ends_at")(suspension.ends_at)(originalEndsAt);
  TestValidator.equals("issuer")(suspension.issued_by_admin_id)(admin.id);
  TestValidator.equals("target")(suspension.discussionboard_member_id)(member.id);

  // Step 3: Admin extends ends_at
  const newEndsAt = new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(); // 5 days from now
  const update1Body = {
    ends_at: newEndsAt,
  } satisfies DiscussionboardMemberSuspension.IUpdate;
  const updated1 = await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspension.id,
    body: update1Body,
  });
  typia.assert(updated1);
  TestValidator.equals("ends_at extended")(updated1.ends_at)(newEndsAt);
  TestValidator.equals("reason unchanged")(updated1.reason)(suspension.reason);

  // Step 4: Admin changes reason
  const newReason = "Adjustment - follow-up moderation.";
  const update2Body = {
    reason: newReason,
  } satisfies DiscussionboardMemberSuspension.IUpdate;
  const updated2 = await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspension.id,
    body: update2Body,
  });
  typia.assert(updated2);
  TestValidator.equals("reason updated")(updated2.reason)(newReason);
  TestValidator.equals("ends_at unchanged")(updated2.ends_at)(updated1.ends_at);

  // Step 5: Admin shortens ends_at & updates reason
  const earlierEndsAt = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(); // 2 days from now
  const newReason2 = "Reducing suspension duration after review.";
  const update3Body = {
    ends_at: earlierEndsAt,
    reason: newReason2,
  } satisfies DiscussionboardMemberSuspension.IUpdate;
  const updated3 = await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspension.id,
    body: update3Body,
  });
  typia.assert(updated3);
  TestValidator.equals("ends_at shortened")(updated3.ends_at)(earlierEndsAt);
  TestValidator.equals("reason updated again")(updated3.reason)(newReason2);

  // Step 6: Unauthorized member tries to update (should fail 403)
  const unauthorized: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now.toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(unauthorized);
  await TestValidator.error("unauthorized update should fail with 403")(
    () => api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
      id: suspension.id,
      body: { reason: "Should not be allowed" } satisfies DiscussionboardMemberSuspension.IUpdate,
    })
  );

  // Step 7: Attempt to update immutable fields (not possible—these fields not present in IUpdate, type checker prevents)
  // No-op as IUpdate does not permit modifying issued_by_admin_id, issued_by_moderator_id, discussionboard_member_id, or starts_at

  // Step 8: Update with invalid (random) ID (should get 404)
  await TestValidator.error("update with non-existent ID yields 404")(
    () => api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { reason: "No record exists" } satisfies DiscussionboardMemberSuspension.IUpdate,
    })
  );

  // Step 9: Mark suspension as revoked, then test further updates
  const revokeTime = new Date(Date.now() + 1 * 60 * 60 * 1000).toISOString(); // 1 hour from now
  const revokeBody = {
    revoked_at: revokeTime,
    reason: updated3.reason,
  } satisfies DiscussionboardMemberSuspension.IUpdate;
  const revoked = await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspension.id,
    body: revokeBody,
  });
  typia.assert(revoked);
  TestValidator.equals("revoked_at set")(revoked.revoked_at)(revokeTime);
  // Now try updating after revoked_at set
  await TestValidator.error("update after revoked should fail or be no-op")(
    () => api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
      id: suspension.id,
      body: { ends_at: newEndsAt } satisfies DiscussionboardMemberSuspension.IUpdate,
    })
  );
  // Simulate as expired: update ends_at to past and try update
  const expiredEndsAt = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // 1 day ago
  const expiredUpdateBody = {
    ends_at: expiredEndsAt,
    reason: "Set to expired in the past",
  } satisfies DiscussionboardMemberSuspension.IUpdate;
  const expiredRecord = await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: suspension.id,
    body: expiredUpdateBody,
  });
  typia.assert(expiredRecord);
  // Now try another update
  await TestValidator.error("update after expired should fail or be no-op")(
    () => api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
      id: suspension.id,
      body: { reason: "Late update" } satisfies DiscussionboardMemberSuspension.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
