import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 시스템 설정의 신규 등록(정상 동작)
 *
 * discussionboard_settings의 신규 레코드를 고유한 key/value/description으로 등록할 수 있어야 한다.
 * 관리자가 POST /discussionboard/systematic/settings를 호출할 때,
 *  - 입력값(key, value, description)이 정확히 반영되어 응답에 포함되고,
 *  - id는 uuid, created_at/updated_at은 현재 시간 기준 허용 오차 내에 들어오며,
 *  - DB 삽입 후 감사 추적이 가능함을 보장하는 핵심 시나리오이다.
 *
 *    1. 고유한 key + value + description으로 새로운 시스템 설정을 등록한다.
 *    2. 응답이 타입(IDiscussionboardSettings)과 스키마에 맞는지 typia.assert로 검증한다.
 *    3. 입력값(key/value/description)과 응답의 값이 정확히 일치하는지 TestValidator로 점검한다.
 *    4. id가 uuid 포맷인지, created_at/updated_at이 허용 시간(±5초) 내에 생성됐는지 검증한다.
 *
 * (오류 시: key 중복 등은 별도 음수 케이스에서 검증함)
 */
export async function test_api_discussionboard_test_create_system_setting_with_valid_unique_key(
  connection: api.IConnection,
) {
  // 1. 고유한 설정 입력값 준비
  const uniqueKey = `setting_${typia.random<string>().replace(/[^a-zA-Z0-9]/g, "").slice(0, 10)}_${Date.now()}`;
  const value = `val_${RandomGenerator.alphaNumeric(6)}`;
  const description = RandomGenerator.paragraph()(1);

  // 2. 시스템 설정 신규 등록
  const setting = await api.functional.discussionboard.systematic.settings.post(connection, {
    body: {
      key: uniqueKey,
      value,
      description,
    } satisfies IDiscussionboardSettings.ICreate,
  });
  typia.assert(setting);

  // 3. 입력값과 응답값의 일치성 검증
  TestValidator.equals("설정 key 반영됨")(setting.key)(uniqueKey);
  TestValidator.equals("설정 value 반영됨")(setting.value)(value);
  TestValidator.equals("설명 반영됨")(setting.description)(description);

  // 4. id는 uuid 포맷인지
  TestValidator.predicate("id가 uuid 포맷")(typia.is<string & tags.Format<"uuid">>(setting.id));

  // 5. created_at/updated_at 현재 시간(±5초) 내 생성 여부 확인
  const now = Date.now();
  const createdAt = Date.parse(setting.created_at);
  const updatedAt = Date.parse(setting.updated_at);
  TestValidator.predicate("created_at 오차 5초 내")(Math.abs(now - createdAt) < 5000);
  TestValidator.predicate("updated_at 오차 5초 내")(Math.abs(now - updatedAt) < 5000);
}

