import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 시스템 설정의 value 및 description을 성공적으로 수정하는 E2E 시나리오를 검증합니다.
 *
 * - 기존 system setting의 값과 설명 변경 가능성 (key는 불변)을 테스트합니다.
 * - 사전: 신규 설정을 생성한 뒤 바로 update 테스트를 진행합니다.
 * - 검증: id, key는 불변, value/description은 요청값, updated_at 갱신됨을 확인합니다.
 */
export async function test_api_discussionboard_systematic_settings_test_update_system_setting_value_and_description_successfully(
  connection: api.IConnection,
) {
  // 1. 사전 준비 - 시스템 설정 생성 (POST)
  const createInput = {
    key: `test_setting_${RandomGenerator.alphabets(8)}`,
    value: `default_value_${RandomGenerator.alphaNumeric(6)}`,
    description: "초기 설명",
  } satisfies IDiscussionboardSettings.ICreate;
  const created = await api.functional.discussionboard.systematic.settings.post(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // 2. 수정 전 정보 저장
  const beforeId = created.id;
  const beforeKey = created.key;
  const beforeValue = created.value;
  const beforeDescription = created.description;
  const beforeUpdatedAt = created.updated_at;

  // 3. value/description 변경 요청 (PUT)
  const updateInput = {
    value: `new_value_${RandomGenerator.alphaNumeric(6)}`,
    description: "수정된 설명",
  } satisfies IDiscussionboardSettings.IUpdate;
  const updated = await api.functional.discussionboard.systematic.settings.putById(
    connection,
    {
      id: beforeId,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 4. 실제 결과 검증
  TestValidator.equals("id unchanged")(updated.id)(beforeId);
  TestValidator.equals("key unchanged")(updated.key)(beforeKey);
  TestValidator.notEquals("value updated")(updated.value)(beforeValue);
  TestValidator.equals("value matched")(updated.value)(updateInput.value);
  TestValidator.equals("description updated")(updated.description ?? undefined)(updateInput.description);
  TestValidator.notEquals("updated_at changed")(updated.updated_at)(beforeUpdatedAt);
}

