import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * 시스템 설정의 key 필드는 불변(immutable)임을 보장하는 테스트 케이스입니다.
 *
 * - 시스템 설정 신규 생성 후, 값(value)/설명(description)만 정상적으로 변경됩니다.
 * - key 필드 자체는 PUT(update) API에서 변경 시도가 불가능하도록 타입 시스템상 완전히 봉쇄되어 있습니다.
 * - 타입 안전성이 철저히 적용되어, 비정상적인 key 교체 시도(예: body에 key 포함)가 컴파일 타임에 차단됨을 검증합니다.
 * - 실제 업데이트 후 반환된 객체의 key 값이 기존과 동일함을 통해 비즈니스 불변 조건이 코드로 보장됨을 확인합니다.
 *
 * 1. 신규 시스템 설정을 등록한다 (key, value, description 지정).
 * 2. 해당 id 레코드에 대해서, value/description만 변경하는 정상 업데이트를 실행한다.
 * 3. 업데이트 후 객체의 key 필드가 변경되지 않았음을 검증한다.
 * 4. (부가 설명) PUT API 본문(body)에 key 필드를 타입/스펙상 전달할 수 없으므로 비정상 시나리오를 코드로 작성할 수 없음.
 */
export async function test_api_discussionboard_systematic_settings_test_update_setting_key_field_should_fail(
  connection: api.IConnection,
) {
  // 1. 신규 시스템 설정 생성
  const created = await api.functional.discussionboard.systematic.settings.post(connection, {
    body: {
      key: RandomGenerator.alphaNumeric(14),
      value: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
    }
  });
  typia.assert(created);

  // 2. value/description만 변경 - 정상 update
  const updated = await api.functional.discussionboard.systematic.settings.putById(connection, {
    id: created.id,
    body: {
      value: RandomGenerator.alphaNumeric(17),
      description: RandomGenerator.paragraph()(1),
    }
  });
  typia.assert(updated);
  // 3. key가 immutable임을 확인
  TestValidator.equals("시스템 설정의 key 필드는 불변")(updated.key)(created.key);

  // 4. (음수 케이스) PUT API 본문에 key 필드를 전달하는 코드는 타입 시스템상 작성 자체가 불가함 (컴파일 에러 발생)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
