  // 3. 삭제된 설정의 값(삭제 전후 기록) 필드 검증
  TestValidator.equals("삭제된 설정 key")(deleted.key)(createInput.key);
  TestValidator.equals("삭제된 설정 value")(deleted.value)(createInput.value);

  // 4. (GET API 미존재로 미확인)
  // 만약 GET /discussionboard/systematic/settings/{id} 지원 시, try-catch로 조회가 실패하는지 검증 필요
  // (예시)
  // await TestValidator.error("삭제 후 조회 불가")(() =>
  //   api.functional.discussionboard.systematic.settings.at(connection, { id: created.id })
  // );

  // 별도 감사/로그 검증은 현재 API 스펙 범위에서는 수행 불가
}

