import type { IPageIDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostDislike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터, 페이지네이션, 권한 제약을 테스트하는 post dislikes 조회 E2E.
 *
 * - 여러 멤버와 여러 게시글을 사전 생성하고,
 * - 여러 멤버들이 다양한 포스트에 dislike를 남긴다.
 * - 이후 PATCH(postDislikes) 엔드포인트로
 *   · post id, member id, 날짜 범위, 페이지/limit 등 다양한 필터로 검색/검증
 * - 응답 데이터의 정합성과 필터링 반영 여부, 기본 정렬, 페이지네이션 동작, 
 *   (권한별 민감정보 노출 제한 또는 오류 케이스는 실제 상황에 따라 skip 또는 error 테스트 가능)
 *
 * 1. 멤버 3명 생성 (A/B/C)
 * 2. Thread 2개, Post 3개 생성 (멤버 소유 분산)
 * 3. 여러 멤버가 여러 포스트 dislike
 * 4. PATCH(postDislikes)로
 *    - 포스트 id로 필터
 *    - 멤버 id로 필터
 *    - created_at 범위
 *    - 페이지네이션/limit
 * 5. (옵션) 비권한자 접근 제한 또는 정보 제한 테스트
 */
export async function test_api_discussionboard_test_list_post_dislikes_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 멤버 생성 (A/B/C)
  const now = new Date();
  const members = await Promise.all([
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
    api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: now.toISOString(),
        status: "active",
      },
    }),
  ]);
  typia.assert(members[0]);
  typia.assert(members[1]);
  typia.assert(members[2]);

  // 2. Thread 2개, Post 3개 생성
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threads = await Promise.all([
    api.functional.discussionboard.threads.threads.post(connection, {
      body: {
        discussionboard_board_id: boardId,
        discussionboard_member_id: members[0].id,
        title: "Thread 1 by A",
        status: "open",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.threads.post(connection, {
      body: {
        discussionboard_board_id: boardId,
        discussionboard_member_id: members[1].id,
        title: "Thread 2 by B",
        status: "open",
        created_at: now.toISOString(),
      },
    }),
  ]);
  typia.assert(threads[0]);
  typia.assert(threads[1]);

  const posts = await Promise.all([
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        discussionboard_member_id: members[0].id,
        body: "Post 1 in Thread 1 (A)",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        discussionboard_member_id: members[0].id,
        body: "Post 2 in Thread 1 (A)",
        created_at: now.toISOString(),
      },
    }),
    api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: threads[1].id,
        discussionboard_member_id: members[1].id,
        body: "Post 3 in Thread 2 (B)",
        created_at: now.toISOString(),
      },
    }),
  ]);
  typia.assert(posts[0]);
  typia.assert(posts[1]);
  typia.assert(posts[2]);

  // 3. 여러 멤버가 여러 포스트 dislike 생성
  const dislikes = [
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[0].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[1].id,
        discussionboard_member_id: members[1].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[2].id,
      },
    }),
    await api.functional.discussionboard.interactions.postDislikes.post(connection, {
      body: {
        discussionboard_post_id: posts[2].id,
        discussionboard_member_id: members[2].id,
      },
    }),
  ];
  dislikes.forEach((d) => typia.assert(d));

  // 4. PATCH - 포스트 id로 필터링
  const resByPost = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { discussionboard_post_id: posts[0].id },
  });
  typia.assert(resByPost);
  TestValidator.predicate("post 0 dislikes만 포함 여부")(
    resByPost.data.every((d) => d.discussionboard_post_id === posts[0].id)
  );

  // PATCH - 멤버 id로 필터링
  const resByMember = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { discussionboard_member_id: members[2].id },
  });
  typia.assert(resByMember);
  TestValidator.predicate("member 2 dislikes만 포함 여부")(
    resByMember.data.every((d) => d.discussionboard_member_id === members[2].id)
  );

  // PATCH - 날짜(from, to) 범위 (now시점만 모두 포함)
  const isoNow = now.toISOString();
  const resByDate = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: {
      from_created_at: isoNow,
      to_created_at: isoNow,
    },
  });
  typia.assert(resByDate);
  TestValidator.predicate("created_at=now만 filter")(
    resByDate.data.every((d) => d.created_at === isoNow)
  );

  // PATCH - 페이지네이션(페이지/limit)
  const resPage1 = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(resPage1);
  TestValidator.equals("1페이지, 2limit 길이 확인")(resPage1.data.length)(2);
  TestValidator.equals("1페이지 current 필드 확인")(resPage1.pagination.current)(1);

  const resPage2 = await api.functional.discussionboard.interactions.postDislikes.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(resPage2);
  TestValidator.equals("2페이지, 2limit 길이 확인")(resPage2.data.length)(2);
  TestValidator.equals("2페이지 current 필드 확인")(resPage2.pagination.current)(2);

  // 5. (옵션) 권한 없는 일반/비권한자 접근 제한 시나리오 (API 지원시)
  // 실제로 정보 제한/예외 발생 시 TestValidator.error 등으로 검증 가능
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostDislike";

/**
 * E2E test of fetching a discussion post dislike by ID with full workflow and permission edge cases.
 *
 * This test scenario ensures:
 * - A post dislike can be fetched by its owner
 * - Access is denied for non-owner member (ensuring permissions)
 * - 404 is returned for non-existent dislike ID
 *
 * Steps:
 * 1. Create two members: one as the disliker, one as a regular member.
 * 2. Create a thread (requires board ID), and a post in that thread authored by the disliker.
 * 3. The disliker member dislikes the post (creating the dislike record, capturing its ID)
 * 4. The disliker performs a GET by ID and receives full details (should not error, all data present)
 * 5. Switch context to the second member, attempt the same GET by ID (expect error, e.g. 403 Forbidden)
 * 6. Attempt to fetch a non-existent dislike ID (expect error, e.g. 404 Not Found)
 *
 * Note: No authentication/switching API exists, so all calls use the same connection (actual permission checks cannot be tested realistically; non-owner permission check is included for contract completeness but may always pass/fail depending on system setup).
 */
export async function test_api_discussionboard_test_get_post_dislike_by_id_success_and_permission_denied(
  connection: api.IConnection,
) {
  // 1. Create two members (disliker and would-be adversary)
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(member2);

  // 2. Create a thread as member1
  const boardId = typia.random<string & tags.Format<'uuid'>>();
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: member1.id,
      title: RandomGenerator.paragraph()(1),
      description: null,
      status: 'open',
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create a post in the thread by member1
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member1.id,
      body: RandomGenerator.content()()(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. Member1 dislikes the post
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member1.id,
    },
  });
  typia.assert(dislike);

  // 5. Member1 GETs the dislike by its ID
  const fetched = await api.functional.discussionboard.interactions.postDislikes.getById(connection, {
    id: dislike.id,
  });
  typia.assert(fetched);
  TestValidator.equals('Fetched dislike matches the created one')(fetched)(dislike);

  // 6. (Simulated) Member2 attempts to fetch the same dislike by ID (no real context switching available)
  await TestValidator.error('Should be permission denied for non-owner')(async () => {
    await api.functional.discussionboard.interactions.postDislikes.getById(connection, {
      id: dislike.id,
    });
  });

  // 7. Try to fetch a non-existent dislike (random UUID)
  await TestValidator.error('Should be 404 Not Found')(async () => {
    await api.functional.discussionboard.interactions.postDislikes.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostDislike";

/**
 * Validate successful creation of a post dislike and duplicate prevention.
 *
 * This test simulates a member who dislikes a post for the first time, then attempts to dislike the same post again.
 * The first action should succeed and the API should return a valid dislike entity.
 * The second action should be rejected due to the unique constraint that a member cannot dislike the same post twice.
 *
 * Test Steps:
 * 1. Register a member (the actor giving the dislike).
 * 2. Create a dummy thread (as post container).
 * 3. Create a post in that thread (target for the dislike).
 * 4. Have the member issue a dislike (should succeed).
 * 5. Attempt to dislike the same post again with this member (should fail due to uniqueness rule).
 */
export async function test_api_discussionboard_test_create_post_dislike_successful_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register the member who will dislike the post
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Create a dummy thread as context for the post
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(4),
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create a post in the dummy thread
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()(1)(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. Member expresses initial dislike (should succeed)
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
    },
  });
  typia.assert(dislike);
  TestValidator.equals("member ID")(dislike.discussionboard_member_id)(member.id);
  TestValidator.equals("post ID")(dislike.discussionboard_post_id)(post.id);

  // 5. Attempt to dislike the same post again (should fail because of unique constraint)
  await TestValidator.error("duplicate dislike rejected")(
    async () => {
      await api.functional.discussionboard.interactions.postDislikes.post(connection, {
        body: {
          discussionboard_post_id: post.id,
          discussionboard_member_id: member.id,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostDislike";

/**
 * Test updating a post dislike (PUT /discussionboard/interactions/postDislikes/{id}) for own resource and access errors.
 *
 * Validates that a member can update their own dislike to a post, and checks that non-owners cannot update others' dislikes.
 * Also verifies that updating a non-existent dislike returns a not found error.
 *
 * Workflow:
 * 1. Create two members: owner and non-owner.
 * 2. Create a thread (simulate a random board ID, due to lack of board creation API).
 * 3. Create a post within that thread by the owner.
 * 4. Have the owner dislike the post.
 * 5. Attempt to update the dislike as the owner (should succeed).
 * 6. Attempt to update the dislike as the non-owner (should fail with permission error).
 * 7. Attempt to update a completely random dislike ID (should fail with not found error).
 */
export async function test_api_discussionboard_test_update_post_dislike_own_and_permission_error(
  connection: api.IConnection,
) {
  // 1. Create two members
  const member1 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member2);

  // 2. Create a thread (random board UUID as no board-create API)
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member1.id,
      title: RandomGenerator.paragraph()(10),
      description: RandomGenerator.content()()(),
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create a post in the thread by member1
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member1.id,
      body: RandomGenerator.content()()(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. member1 dislikes the post
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member1.id,
    },
  });
  typia.assert(dislike);

  // 5. Owner (member1) updates their own dislike (simulate update, field values remain the same)
  const updatedDislike = await api.functional.discussionboard.interactions.postDislikes.putById(connection, {
    id: dislike.id,
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member1.id,
    },
  });
  typia.assert(updatedDislike);
  TestValidator.equals("dislike id remains the same")(updatedDislike.id)(dislike.id);
  TestValidator.equals("member remains the same")(updatedDislike.discussionboard_member_id)(member1.id);
  TestValidator.equals("post remains the same")(updatedDislike.discussionboard_post_id)(post.id);

  // 6. Non-owner tries to update the dislike
  await TestValidator.error("non-owner update forbidden")(() =>
    api.functional.discussionboard.interactions.postDislikes.putById(connection, {
      id: dislike.id,
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member2.id,
      },
    })
  );

  // 7. Try to update a random dislike id (non-existent)
  await TestValidator.error("updating non-existent dislike yields not found")(() =>
    api.functional.discussionboard.interactions.postDislikes.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member1.id,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostDislike";

/**
 * E2E validation for authorized and unauthorized deletion of post dislikes in the Discussion Board system.
 *
 * This function enforces and tests the following business logic:
 * 1. A member can delete their own post dislike.
 * 2. Authorized roles (e.g., moderator/admin) can delete any user's dislike.
 * 3. Unauthorized users (regular members) cannot delete dislikes owned by others.
 * 4. A not-found error occurs when deleting a non-existent dislike.
 * 5. Each delete action is assumed to be audited as per business rules.
 *
 * Workflow:
 * 1. Create three members: ordinaryMember, anotherMember, adminMember (admin emulated by 'status' = 'admin').
 * 2. ordinaryMember creates a thread, then a post in the thread.
 * 3. ordinaryMember dislikes the post (creates a dislike record).
 * 4. Verify ordinaryMember can successfully delete their own dislike (should be removed, no error).
 * 5. Recreate the dislike. anotherMember tries to delete it (expect error).
 * 6. adminMember deletes the same dislike (should succeed as admin).
 * 7. Attempt deletion on a random non-existent dislike ID (expect not found error).
 * 8. (Assume auditing is done server-side; not verifiable with current API surface.)
 *
 * Edge Cases:
 * - Unauthorized deletion returns error.
 * - Deletion of non-existent dislike returns not found error.
 * - Re-creating after deletion is possible (not tested here for brevity).
 */
export async function test_api_discussionboard_test_delete_post_dislike_authorized_and_unauthorized(
  connection: api.IConnection,
) {
  // 1. Create three members with different roles/status.
  const now = new Date().toISOString();

  const ordinaryMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: 'active',
    }
  });
  typia.assert(ordinaryMember);

  const anotherMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: 'active',
    }
  });
  typia.assert(anotherMember);

  const adminMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: 'admin', // Emulate admin via status (for test)
    }
  });
  typia.assert(adminMember);

  // 2. ordinaryMember creates a thread.
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_member_id: ordinaryMember.id,
      title: RandomGenerator.paragraph()(8),
      description: RandomGenerator.paragraph()(24),
      status: 'open',
      created_at: now,
    }
  });
  typia.assert(thread);

  // 3. ordinaryMember creates a post in the thread.
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: ordinaryMember.id,
      body: RandomGenerator.content()()(),
      created_at: now,
    }
  });
  typia.assert(post);

  // 4. ordinaryMember dislikes their own post.
  const dislike = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: ordinaryMember.id,
    }
  });
  typia.assert(dislike);

  // 5. ordinaryMember deletes their own dislike.
  await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
    id: dislike.id,
  });

  // Try deleting again (should be gone), expect not found
  await TestValidator.error("Deleting already-deleted dislike returns error")(
    async () => {
      await api.functional.discussionboard.interactions.postDislikes.eraseById(connection, {
        id: dislike.id,
      });
    }
  );

  // 6. Recreate the dislike for the next tests
  const dislike2 = await api.functional.discussionboard.interactions.postDislikes.post(connection, {
    body: {
      discussionboard_post_id: post.id,
