 *
 * This test covers the following:
 * 1. Successful creation of a new authentication record for a valid member
 * 2. Error on duplicate provider/identifier submission for the same member
 * 3. Acceptance of another authentication for the same member/identifier if provider is different
 * 4. Error when attempting authentication creation with a non-existent member ID
 *
 * Business significance: ensures uniqueness, referential integrity, and correct error handling for identity credential storage on the discussion board system.
 *
 * Test Steps:
 * 1. Create a discussion board member for use in the positive/negative authentication cases
 * 2. Register valid authentication for that member (provider = 'local')
 * 3. Attempt duplicate creation for the same provider/identifier (expect error)
 * 4. Register new authentication with another provider but same identifier (should succeed)
 * 5. Attempt authentication creation with a randomly generated non-existent member UUID (expect error)
 */
export async function test_api_discussionboard_test_create_member_authentication_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Create a new member (prerequisite for auth records)
  const memberReg = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
