/**
 * Test updating an existing member authentication record with full property replacement and business validations.
 *
 * This test validates:
 * - Successful full replacement of all properties in a member authentication record (provider, provider_identifier, password_hash, last_login_at).
 * - Business rule: Uniqueness constraint violation if another auth already uses the same provider+provider_identifier (should trigger an error).
 * - Error case: Attempting to update a non-existent auth record (should yield 404).
 *
 * Steps:
 * 1. Create MemberA and MemberB for test setup.
 * 2. Register AuthA for MemberA, and AuthB for MemberB (distinct provider+identifier for uniqueness test).
 * 3. Update AuthA with a full, valid property replacement; check all fields update as expected.
 * 4. Attempt to update AuthA to use the provider+identifier from AuthB (should fail: uniqueness constraint).
 * 5. Attempt to update a random, non-existent authentication record (should fail with 404).
 *
 * Prerequisite APIs for creating members and auths are used. No authorization/role constraint is tested due to insufficient provided auth APIs.
 */
export async function test_api_discussionboard_actors_memberAuthentications_test_update_member_authentication_with_full_replacement_and_validation(
  connection: api.IConnection,
) {
  // 1. Create MemberA
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    },
  });
  typia.assert(memberA);

  // 2. Create MemberB
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    },
  });
  typia.assert(memberB);

  // 3. Register AuthA (MemberA)
  const authA = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      provider: "local",
      provider_identifier: RandomGenerator.alphabets(10),
      password_hash: RandomGenerator.alphabets(30),
    },
  });
  typia.assert(authA);

  // 4. Register AuthB (MemberB, different provider+id for uniqueness)
  const authB = await api.functional.discussionboard.actors.memberAuthentications.post(connection, {
    body: {
      discussionboard_member_id: memberB.id,
      provider: "google",
      provider_identifier: RandomGenerator.alphabets(10),
      password_hash: null,
    },
  });
  typia.assert(authB);

  // 5. FULL REPLACEMENT UPDATE: AuthA (should succeed)
  const newProvider = "kakao";
  const newIdentifier = RandomGenerator.alphabets(12);
  const newLastLogin = typia.random<string & tags.Format<"date-time">>();
  const updated = await api.functional.discussionboard.actors.memberAuthentications.putById(connection, {
    id: authA.id,
    body: {
      provider: newProvider,
      provider_identifier: newIdentifier,
      password_hash: null,
      last_login_at: newLastLogin,
    },
  });
  typia.assert(updated);
  TestValidator.equals("provider updated")(updated.provider)(newProvider);
  TestValidator.equals("provider_identifier updated")(updated.provider_identifier)(newIdentifier);
  TestValidator.equals("password_hash updated")(updated.password_hash)(null);
  TestValidator.equals("last_login_at updated")(updated.last_login_at)(newLastLogin);

  // 6. UNIQUENESS CONSTRAINT: Try to clone AuthB's provider+id to AuthA (should fail)
  await TestValidator.error("should fail: uniqueness constraint on provider+identifier")(
    async () => {
      await api.functional.discussionboard.actors.memberAuthentications.putById(connection, {
        id: authA.id,
        body: {
          provider: authB.provider,
          provider_identifier: authB.provider_identifier,
          password_hash: null,
          last_login_at: typia.random<string & tags.Format<"date-time">>(),
        },
      });
    },
  );

  // 7. NOT FOUND: Try to update a random non-existent record
  await TestValidator.error("should fail: non-existent authentication id")(
    async () => {
      await api.functional.discussionboard.actors.memberAuthentications.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          provider: "local",
          provider_identifier: RandomGenerator.alphabets(10),
          password_hash: RandomGenerator.alphabets(30),
          last_login_at: typia.random<string & tags.Format<"date-time">>(),
        },
      });
    },
  );
}

