  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("fetching non-existent category throws error")(() =>
    api.functional.discussionboard.systematic.categories.getById(
      connection,
      { id: randomUuid },
    )
  );
  // Step 4: (Soft-deleted scenario omitted due to absence of delete API)
}

