 *
 * This test verifies:
 * 1. Deleting a nonexistent category returns a 404 error.
 * 2. Only admin accounts may delete categories: tries to delete as moderator/member and expects permission denied errors.
 * 3. Successful soft-delete works with admin privilege; response is validated.
 *
 * Steps:
 * 1. Create a category as admin.
 * 2. Attempt to delete a nonexistent category (random uuid) and expect 404 error.
 * 3. Attempt to delete the valid category as a moderator and expect forbidden error.
 * 4. Attempt to delete the valid category as a regular member and expect forbidden error.
 * 5. Delete the category as admin; check result.
 */
export async function test_api_discussionboard_test_delete_category_not_found_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create a category as admin
  const createInput: IDiscussionboardCategory.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(12),
    enabled: true,
    parent_id: null,
    description: RandomGenerator.paragraph()(),
  };
  const created = await api.functional.discussionboard.systematic.categories.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Attempt to delete a nonexistent category (should return 404)
  await TestValidator.error("nonexistent category should return 404")(
    async () => {
      await api.functional.discussionboard.systematic.categories.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 3. Simulate moderator attempting deletion (should fail)
