/**
 * E2E test for creating comments on discussion board posts covering both valid and invalid scenarios.
 *
 * This test performs the following validations:
 * 1. Register two member accounts (one active, one intended to be suspended for permission testing)
 * 2. Create a post as the active member
 * 3. Create a top-level comment on the post as the active member
 * 4. Create a reply (nested comment) to that comment
 * 5. Assert that new comments contain all required IDs, timestamps, relations (post/member/parent), and body
 * 6. Attempt to create a comment as a suspended user (expect forbidden error)
 * 7. Attempt to create a comment on an invalid post ID (expect not found error)
 * 8. Attempt to create a comment with missing/empty body (expect validation error)
 * 9. Attempt to reply to an invalid parent comment (expect validation error or not found)
 *
 * Limitations:
 * - Suspension is applied using a random UUID since the API does not allow direct targeting of a specific newly registered member for suspension (per provided SDK).
 * - Maximum nesting depth, prohibited body content, and comment quota are not directly tested without further API features/support.
 */
export async function test_api_discussionboard_test_create_comment_on_post_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Register two members: one active, one to be suspended later
  const activeMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(activeMember);

  const suspendedMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(suspendedMember);

  // 2. Create a post as activeMember (simulated thread ID)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.paragraph()(),
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 3. Create a top-level comment
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.content()()(),
      parent_id: null,
    },
  });
  typia.assert(comment);
  TestValidator.equals("post id relation")(comment.discussionboard_post_id)(post.id);
  TestValidator.equals("member relation")(comment.discussionboard_member_id)(activeMember.id);
  TestValidator.equals("no parent")(comment.parent_id)(null);
  TestValidator.predicate("body content present")(!!comment.body);
  TestValidator.predicate("created_at present")(!!comment.created_at);
  TestValidator.predicate("updated_at present")(!!comment.updated_at);

  // 4. Create a reply (nested comment)
  const reply = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: activeMember.id,
      body: RandomGenerator.content()()(),
      parent_id: comment.id,
    },
  });
  typia.assert(reply);
  TestValidator.equals("reply post id relation")(reply.discussionboard_post_id)(post.id);
  TestValidator.equals("reply parent_id")(reply.parent_id)(comment.id);

  // 5. Suspend the (second) member (limitation: random UUID, not directly the created member)
  await api.functional.discussionboard.actors.memberSuspensions.putById(connection, {
    id: typia.random<string & tags.Format<"uuid">>(),
    body: {
      ends_at: null,
      reason: "Test suspension",
      revoked_at: null,
    },
  });

  // 6. Attempt to create a comment as suspended member (should fail, forbidden)
  await TestValidator.error("suspended member forbidden")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: suspendedMember.id,
        body: "Suspended attempt",
        parent_id: null,
      },
    })
  );

  // 7. Attempt to create a comment on an invalid post ID
  await TestValidator.error("invalid post id")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: "00000000-0000-0000-0000-000000000000",
        discussionboard_member_id: activeMember.id,
        body: "Bad post id",
        parent_id: null,
      },
    })
  );

  // 8. Attempt to create a comment with empty body (invalid)
  await TestValidator.error("missing body")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: activeMember.id,
        body: "",
        parent_id: null,
      },
    })
  );

  // 9. Attempt to reply to a deleted/invalid parent comment
  await TestValidator.error("invalid parent_id")(() =>
    api.functional.discussionboard.threads.comments.post(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: activeMember.id,
        body: "Bad parent",
        parent_id: "00000000-0000-0000-0000-000000000000",
      },
    })
  );
}

