 *   2. Non-author cannot update someone else's comment (permission denied)
 *   3. Update is forbidden after comment is deleted (soft-deleted)
 *   4. Update fails with empty body or invalid comment ID
 *
 * Skips staff/admin update and edit window expiration cases, as neither are supported in schema/API.
 * Relies only on DTO and API functions present. Throughout, asserts all major business and data invariants.
 *
 * Step-by-step process:
 * 1. Create author and non-author board members
 * 2. Author creates a discussion comment
 * 3. Author updates comment content successfully
 * 4. Non-author's update attempt fails
 * 5. Author deletes (soft-deletes) the comment
 * 6. Attempts to update deleted comment are rejected
 * 7. Attempts to update with empty body or invalid ID are rejected
 */
export async function test_api_discussionboard_threads_comments_test_update_comment_as_author_and_staff_handling_permissions_and_window(
  connection: api.IConnection,
) {
  // 1. Create author and non-author board members
  const author: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(author);
  const nonAuthor: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    }
  });
  typia.assert(nonAuthor);

  // 2. Author creates a discussion comment
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: author.id,
      body: "Original comment content"
    }
  });
  typia.assert(comment);

  // 3. Author updates the comment content successfully
