  await TestValidator.error("invalid id update fails")(async () => {
    await api.functional.discussionboard.threads.comments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        body: "Random id edit"
      }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate permissions and results of soft-deleting discussion board comments.
 *
 * This test covers business logic and permission rules for soft-deleting comments on the discussion board system:
 *   - Author (member) can delete their own comment (if deletable by window/rule)
 *   - Moderator/admin can always delete any comment (ignoring time windows)
 *   - Non-author regular members are forbidden from deleting others' comments
 *   - Cannot delete comments that are locked, under moderation, or already deleted
 *   - Nested/threaded comment cases and repeated deletion attempts are also checked
 *   - Deletion must update the comment's deleted_at field (soft delete) and enforce visibility rules
 *
 * Steps:
 * 1. Create three member accounts: author, moderator/admin, non-author member
 * 2. Author posts a comment and a nested reply (threaded comment)
 * 3. Author deletes their top-level comment: expect success, deleted_at set, comment returned
 * 4. Author deletes their own nested (reply) comment: expect success
 * 5. Non-author regular member attempts to delete both comments: expect 403 error
 * 6. Moderator/admin deletes an undeleted comment: expect success
 * 7. Attempt repeated deletion of an already deleted comment: expect 404
 * 8. Lock a comment (simulate lock by update), then attempt deletion as both author and moderator: expect correct error
 * 9. Confirm that after deletion, deleted_at is set, and downstream business rules (e.g., cannot update) are respected
 * 10. (If possible) Check audit/log entry or response hinting audit action (if returned)
 */
export async function test_api_discussionboard_test_delete_comment_own_and_others_permissions_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create three member accounts: author, moderator/admin, and another member
  const author = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(author);
  const moderator = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(moderator);
  const other = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(other);

  // 2. Author creates a post/thread id (simulate as uuid, since no post creation API exists)
  const post_id = typia.random<string & tags.Format<"uuid">>();

  // 2a. Author posts a top-level comment
  const topComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a top-level comment",
    },
  });
  typia.assert(topComment);

  // 2b. Author posts a reply (nested comment)
  const replyComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "This is a nested reply",
      parent_id: topComment.id,
    },
  });
  typia.assert(replyComment);

  // 3. Author deletes their top-level comment
  const deletedTop = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: topComment.id,
  });
  typia.assert(deletedTop);
  TestValidator.predicate("deleted_at must be set after soft delete")(!!deletedTop.deleted_at);

  // 4. Author deletes their own nested reply
  const deletedReply = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: replyComment.id,
  });
  typia.assert(deletedReply);
  TestValidator.predicate("deleted_at must be set for nested delete")(!!deletedReply.deleted_at);

  // 5. Non-author attempts to delete other's comment (should fail)
  TestValidator.error("non-author cannot delete other's comment")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: topComment.id,
    })
  );
  TestValidator.error("non-author cannot delete other's nested reply")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: replyComment.id,
    })
  );

  // 6. Moderator deletes an undeleted comment created by author (should succeed)
  const thirdComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "Moderatable comment by author",
    },
  });
  typia.assert(thirdComment);
  // (Simulating connection switch for moderator privileges is not available, so we execute as is)
  const deletedByModerator = await api.functional.discussionboard.threads.comments.eraseById(connection, {
    id: thirdComment.id,
  });
  typia.assert(deletedByModerator);
  TestValidator.predicate("deleted_at set by moderator")(!!deletedByModerator.deleted_at);

  // 7. Attempt repeated deletion of an already deleted comment (should result in error)
  TestValidator.error("deleting already deleted comment gives not found error")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: topComment.id,
    })
  );

  // 8. Lock a comment using update, then deletion is not allowed
  const lockedComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: post_id,
      discussionboard_member_id: author.id,
      body: "Comment to lock for deletion edge case",
    },
  });
  typia.assert(lockedComment);
  // Simulate lock by updating without changing data (since no lock property exists)
  const lockedUpdated = await api.functional.discussionboard.threads.comments.putById(connection, {
    id: lockedComment.id,
    body: {
      body: lockedComment.body,
      parent_id: lockedComment.parent_id,
    },
  });
  typia.assert(lockedUpdated);
  // Attempting to delete after lock simulation (should error)
  TestValidator.error("cannot delete locked comment")(() =>
    api.functional.discussionboard.threads.comments.eraseById(connection, {
      id: lockedComment.id,
    })
  );

  // 9. Confirm after deletion, cannot update a deleted comment
  TestValidator.error("cannot update a deleted comment")(() =>
    api.functional.discussionboard.threads.comments.putById(connection, {
      id: topComment.id,
      body: {
        body: "edit after delete",
        parent_id: null,
      },
    })
  );

  // 10. If response contains audit/logging info, it is already checked via deleted_at and soft-delete results.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";
import type { IPageIDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered retrieval of post likes.
 *
 * This test ensures that listing of post likes supports correct filtering, pagination, and access control by simulating realistic board activity.
 *
 * 1. Create 3 member accounts with different join times and statuses (all initially 'active').
 * 2. Prepare 2 posts authored by different members (cross-member activity).
 * 3. Each member likes various posts:
 *    - Member 1 likes Post A and B
 *    - Member 2 likes Post A
 *    - Member 3 likes Post B
 * 4. Retrieve post likes with various filters:
 *    a. Filter by member 1 ID (should only return likes made by member 1)
 *    b. Filter by post B ID (should only return likes for Post B)
 *    c. Paginate likes with limit=2 (results for all likes, split by pages)
 * 5. Confirm each result set matches expectations for filtering, matches correct members/posts, and pagination meta is correct (current page, limit, total records, pages).
 * 6. Edge case: request a page and filter that returns no records (high page number, or filter on unmatched post/member ID) and ensure empty data with correct pagination meta.
 */
export async function test_api_discussionboard_test_list_post_likes_with_valid_filters_and_pagination(connection: api.IConnection) {
  // 1. Create multiple members
  const now = new Date();
  const members = await ArrayUtil.asyncRepeat(3)(async (i) =>
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date(now.getTime() - i * 60000).toISOString(),
        status: "active",
      },
    }),
  );
  typia.assert(members);

  // 2. Create posts (each by different member)
  const posts = await ArrayUtil.asyncRepeat(2)(async (i) =>
    await api.functional.discussionboard.threads.posts.post(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(), // Simulate thread for isolation
        discussionboard_member_id: members[i].id,
        body: `Test post body ${i}`,
        created_at: new Date(now.getTime() + i * 1000).toISOString(),
      },
    }),
  );
  typia.assert(posts);

  // 3. Likes mapping:
  // Member 1 likes Post A & B
  // Member 2 likes Post A
  // Member 3 likes Post B
  const likeRecords: Array<{
    memberIdx: number;
    postIdx: number;
    like: Awaited<ReturnType<typeof api.functional.discussionboard.interactions.postLikes.post>>;
  }> = [];

  // Member 1 likes Post A (0) and B (1)
  likeRecords.push({
    memberIdx: 0,
    postIdx: 0,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[0].id, discussionboard_member_id: members[0].id },
    }),
  });
  likeRecords.push({
    memberIdx: 0,
    postIdx: 1,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[1].id, discussionboard_member_id: members[0].id },
    }),
  });

  // Member 2 likes Post A
  likeRecords.push({
    memberIdx: 1,
    postIdx: 0,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[0].id, discussionboard_member_id: members[1].id },
    }),
  });

  // Member 3 likes Post B
  likeRecords.push({
    memberIdx: 2,
    postIdx: 1,
    like: await api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: { discussionboard_post_id: posts[1].id, discussionboard_member_id: members[2].id },
    }),
  });
  typia.assert(likeRecords.map(x => x.like));

  // 4a. Filter likes by member 1 ID
  const likesByMember1 = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_member_id: members[0].id },
  });
  typia.assert(likesByMember1);
  TestValidator.equals("member 1 likes count")(likesByMember1.data.length)(2);
  TestValidator.predicate("all member 1 likes")(likesByMember1.data.every(x => x.discussionboard_member_id === members[0].id));

  // 4b. Filter likes by post B ID
  const likesForPostB = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_post_id: posts[1].id },
  });
  typia.assert(likesForPostB);
  TestValidator.equals("likes for post B")(likesForPostB.data.length)(2);
  TestValidator.predicate("all likes for post B")(likesForPostB.data.every(x => x.discussionboard_post_id === posts[1].id));

  // 4c. Paginate likes with limit=2 (unfiltered, page 1)
  const likesPage1 = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(likesPage1);
  TestValidator.equals("pagination: page 1")(likesPage1.pagination.current)(1);
  TestValidator.equals("pagination: limit")(likesPage1.pagination.limit)(2);
  TestValidator.equals("pagination: total records")(likesPage1.pagination.records)(4);
  TestValidator.predicate("max 2 records on page 1")(likesPage1.data.length <= 2);

  // 5. Edge case: query for a page with no records (page way beyond max; page 5 in this 4-record dataset)
  const likePageNone = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { page: 5, limit: 2 },
  });
  typia.assert(likePageNone);
  TestValidator.equals("page with no records: count")(likePageNone.data.length)(0);
  TestValidator.equals("page with no records: correct page")(likePageNone.pagination.current)(5);
  TestValidator.equals("page with no records: limit")(likePageNone.pagination.limit)(2);
  TestValidator.equals("page with no records: records")(likePageNone.pagination.records)(4);
  TestValidator.predicate("empty page is actually empty")(likePageNone.data.length === 0);

  // 6. Edge case: filter for likes with impossible member/post id
  const likesNone = await api.functional.discussionboard.interactions.postLikes.patch(connection, {
    body: { discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(likesNone);
  TestValidator.equals("empty result set")(likesNone.data.length)(0);
}

