  await TestValidator.error("both IDs non-existent")(() =>
    api.functional.discussionboard.interactions.postLikes.post(connection, {
      body: {
        discussionboard_post_id: fakePostId,
        discussionboard_member_id: fakeMemberId,
      },
    })
