/**
 * Validate retrieval of a paginated and filterable moderation reports list with role-based access control.
 *
 * This ensures the endpoint correctly supports various filtering, pagination, and access control workflows for moderation reports.
 *
 * 1. Create two members: one acts as report filer; another as subject (optionally for realism).
 * 2. Reporter submits two moderation reports: one about a fake post, one about a fake comment (using random UUIDs as targets).
 * 3. Attempt to list moderation reports as an unauthorized member and confirm access is denied.
 * 4. (Simulate privileged/moderator context) Call the moderation reports list API with:
 *    - No filter (should get paginated list containing both reports)
 *    - Filter by status
 *    - Filter by reported_by_member_id
 *    - Pagination settings
 *    - Combination of filters
 * 5. Validate returned results are paginated/filtered as expected and response matches schema.
 */
export async function test_api_discussionboard_test_list_moderation_reports_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create reporter and optional reported member
  const reporter = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(reporter);

  const reported = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(reported);

  // 2. Reporter files two reports: one about a post, one about a comment
  const report1 = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: reporter.id,
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Spam or inappropriate post",
    },
  });
  typia.assert(report1);
  TestValidator.equals("report1 reporter")(report1.reported_by_member_id)(reporter.id);
  TestValidator.equals("report1 status")(report1.status)("pending");

  const report2 = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: reporter.id,
      target_comment_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Attack or harassment in comment",
    },
  });
  typia.assert(report2);
  TestValidator.equals("report2 reporter")(report2.reported_by_member_id)(reporter.id);
  TestValidator.equals("report2 status")(report2.status)("pending");

  // 3. As a regular member, attempt to list moderation reports and expect error
  TestValidator.error("only moderators/admins can list moderation reports")(async () => {
    await api.functional.discussionboard.moderation.reports.patch(connection, {
      body: {},
    });
  });

  // 4. Simulate privileged context: test list with filters/pagination
  // (In real context, should use actual moderator/admin auth)

  // a) List all moderation reports (no filter)
  const allReports = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: {},
  });
  typia.assert(allReports);
  TestValidator.predicate("allReports contains both reports")(allReports.data.length >= 2);
  const allReportIds = allReports.data.map((r) => r.id);
  TestValidator.predicate("allReports includes report1")(allReportIds.includes(report1.id));
  TestValidator.predicate("allReports includes report2")(allReportIds.includes(report2.id));

  // b) Filter by reporter: reported_by_member_id
  const byReporter = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { reported_by_member_id: reporter.id },
  });
  typia.assert(byReporter);
  TestValidator.predicate("byReporter: only reports by reporter")(
    byReporter.data.every((r) => r.reported_by_member_id === reporter.id)
  );

  // c) Filter by status (pending)
  const byStatus = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { status: "pending" },
  });
  typia.assert(byStatus);
  TestValidator.predicate("byStatus: all are pending")(
    byStatus.data.every((r) => r.status === "pending")
  );

  // d) Combo filter: reporter + status
  const comboFiltered = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { reported_by_member_id: reporter.id, status: "pending" },
  });
  typia.assert(comboFiltered);
  TestValidator.predicate("comboFiltered: all match reporter & pending")(
    comboFiltered.data.every((r) => r.status === "pending" && r.reported_by_member_id === reporter.id)
  );

  // e) Pagination: limit = 1, page = 1
  const paginated = await api.functional.discussionboard.moderation.reports.patch(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(paginated);
  TestValidator.equals("paginated page")(paginated.pagination.current)(1);
  TestValidator.equals("paginated limit")(paginated.pagination.limit)(1);
  TestValidator.equals("paginated records")(paginated.pagination.records)(allReports.pagination.records);
  TestValidator.predicate("one record per page or fewer")(paginated.data.length <= 1);
}

