      reported_by_member_id: member.id,
      target_comment_id: comment.id,
      reason: "규정 위반",
    } satisfies IDiscussionboardReport.ICreate,
  });
  typia.assert(commentReport);
  TestValidator.equals("댓글 신고 대조")(commentReport.target_comment_id)(comment.id);

  // 6. 존재하지 않는 포스트/댓글 ID 신고(오류)
  await TestValidator.error("존재하지 않는 포스트 신고오류")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "잘못된 포스트ID",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );
  await TestValidator.error("존재하지 않는 댓글 신고오류")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "잘못된 댓글ID",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 7. 필수값 누락 (reason 없음)
  await TestValidator.error("이유 누락시 실패")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id
        // reason 누락 (타입오류라 실제로는 아예 패스할 수 없음)
      } as any,
    })
  );
  // 7-2. 대상 ID 없음 (포스트/댓글 없음)
  await TestValidator.error("대상ID 미입력시 실패")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        reason: "대상ID 없음"
        // target_post_id, target_comment_id 없음
      } as any,
    })
  );

  // 8. 일일 신고 한도 초과 (10회 성공, 11회째 실패)
  for (let i = 0; i < 10; ++i) {
    const report: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: `중복 신고 ${i+1}`,
      } satisfies IDiscussionboardReport.ICreate,
    });
    typia.assert(report);
  }
  await TestValidator.error("11회째 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: "11번째 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 9. 회원 정지 상태에서 신고 금지
  const suspended: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.putById(connection, {
    id: member.id,
    body: { status: "suspended" } satisfies IDiscussionboardMembers.IUpdate,
  });
  typia.assert(suspended);
  await TestValidator.error("정지회원 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: member.id,
        target_post_id: post.id,
        reason: "정지 중 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );

  // 10. 비회원(없는ID) 신고 금지
  await TestValidator.error("비회원 신고 차단")(() =>
    api.functional.discussionboard.moderation.reports.post(connection, {
      body: {
        reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
        target_post_id: post.id,
        reason: "비회원 신고",
      } satisfies IDiscussionboardReport.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
