/**
 * Validate the update workflow for moderation reports (status and metadata changes).
 *
 * This test covers the complete report update logic for the moderation system including status changes, assignment of a resolver (moderator), and metadata resolution (resolved_at timestamp) according to workflow, audit, and permission rules.
 *
 * Test steps:
 * 1. Create two members: one standard (reporter), one moderator (resolver).
 * 2. Reporter member generates a moderation report (targets a post or a comment, supplies reason).
 * 3. As a moderator, update the report to:
 *    a. Set resolved_by_moderator_id (moderator UUID).
 *    b. Change status to 'reviewed' or another post-resolution state.
 *    c. Provide a resolved_at timestamp.
 * 4. Validate updated fields (status, resolver, resolved_at) are properly reflected and audit safe.
 * 5. Edge: Try to update immutable fields (e.g., reported_by_member_id, target_post_id after creation) and verify modification is blocked or ignored.
 * 6. Edge: Try invalid status transitions or incomplete resolution input, verify errors.
 * 7. Edge: Try an update as a non-moderator (if possible) and expect error/rejection.
 * 8. Edge: Attempt to update a non-existent report (random UUID), expecting proper error handling.
 */
export async function test_api_discussionboard_moderation_reports_test_update_moderation_report_status_and_resolver_metadata(
  connection: api.IConnection,
) {
  // 1. Create two members: reporter and moderator
  const reporter: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(reporter);

  const moderator: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(moderator);

  // 2. Reporter files a moderation report
  const report: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.post(connection, {
    body: {
      reported_by_member_id: reporter.id,
      reason: 'Offensive content',
    } satisfies IDiscussionboardReport.ICreate,
  });
  typia.assert(report);

  // 3. Moderator updates the report (status/resolver/timestamp)
  const updateInput: IDiscussionboardReport.IUpdate = {
    resolved_by_moderator_id: moderator.id,
    status: 'reviewed',
    resolved_at: new Date().toISOString(),
  };
  const updatedReport: IDiscussionboardReport = await api.functional.discussionboard.moderation.reports.putById(connection, {
    id: report.id,
    body: updateInput,
  });
  typia.assert(updatedReport);
  TestValidator.equals('status updated')(updatedReport.status)('reviewed');
  TestValidator.equals('resolver assigned')(updatedReport.resolved_by_moderator_id)(moderator.id);
  TestValidator.equals('resolution timestamp')(updatedReport.resolved_at)(updateInput.resolved_at);

  // 4. Edge case: try modifying immutable fields (not allowed by IUpdate type)
  // Skipped: immutable fields (e.g., reported_by_member_id, target_post_id) are not updatable (compile error if attempted)

  // 5. Edge: Invalid status, missing fields
  await TestValidator.error('invalid status should fail')(() =>
    api.functional.discussionboard.moderation.reports.putById(connection, {
      id: report.id,
      body: {
        ...updateInput,
        status: '', // invalid: empty status
      } satisfies IDiscussionboardReport.IUpdate,
    })
  );

  // 6. Edge: update non-existent report
  await TestValidator.error('updating non-existent report fails')(() =>
    api.functional.discussionboard.moderation.reports.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: updateInput,
    })
  );

  // 7. Edge: attempt update as non-moderator cannot be tested due to lack of authentication simulation APIs.
}

