/**
 * 검증: 게시글 첨부파일 상세 조회 성공 및 권한/오류 검증
 *
 * 이 테스트는 게시글 첨부파일의 메타데이터를 그 업로더, 스레드 다른 참가자, 비참가자(권한 없음)가 각각 조회하는 권한 및 권한 없음 오류, 그리고 존재하지 않는 첨부파일 ID의 조회 실패(404 Not Found)까지 모두 검증합니다.
 *
 * 세 단계(멤버 3명, 단일 스레드)로 구성되며, 실제 첨부파일 업로드/조회가 정상 동작하는지와 함께 권한 비검증 사용자 및 랜덤 ID의 오류처리까지 검증합니다.
 *
 * 테스트 시나리오 순서:
 * 1. 업로더, 참가자, 비참가자 - 3명의 멤버 계정 생성
 * 2. 업로더가 스레드 및 초기 게시글 생성
 * 3. 업로더가 게시글에 첨부파일 업로드 (id 기록)
 * 4. 업로더가 첨부파일 상세 조회 (성공/필드 검증)
 * 5. 참가자가 동일 스레드에 게시글 작성(참가자로 인정)
 * 6. 참가자가 첨부파일 상세 조회 (성공/필드 검증)
 * 7. 비참가자가 첨부파일 상세 조회 (권한 오류 검증)
 * 8. 임의의 존재하지 않는 첨부파일 ID로 조회 시 NotFound 오류 검증
 */
export async function test_api_discussionboard_test_get_post_attachment_detail_success_and_permission(
  connection: api.IConnection,
) {
  // 1. 업로더, 참가자, 비참가자 - 멤버 계정 3개 생성
  const now = new Date().toISOString();
  const uploader = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: "active" } });
  typia.assert(uploader);
  const participant = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: "active" } });
  typia.assert(participant);
  const outsider = await api.functional.discussionboard.actors.members.post(connection, { body: { joined_at: now, status: "active" } });
  typia.assert(outsider);

  // 2. 업로더가 스레드 및 게시글 생성
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: uploader.id,
      title: "E2E 첨부파일 시나리오 스레드",
      description: "파일첨부 연동/권한/오류 검증용 테스트 스레드",
      status: "open",
      created_at: now,
    },
  });
  typia.assert(thread);
  const post = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: uploader.id,
      body: "첨부파일 테스트 게시글 본문",
      created_at: now,
    },
  });
  typia.assert(post);

  // 3. 업로더가 첨부파일 업로드
  const attachment = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      file_uri: "https://cdn.example.com/e2e-file.jpg",
      file_name: "e2e-file.jpg",
      file_type: "image/jpeg",
      uploaded_by: uploader.id,
    },
  });
  typia.assert(attachment);

  // 4. 업로더가 첨부파일 상세 조회 (성공 & 필드 검증)
  let output = await api.functional.discussionboard.threads.postAttachments.getById(connection, { id: attachment.id });
  typia.assert(output);
  TestValidator.equals("파일명 일치")(output.file_name)("e2e-file.jpg");
  TestValidator.equals("파일 타입 일치")(output.file_type)("image/jpeg");
  TestValidator.equals("업로더 ID 일치")(output.uploaded_by)(uploader.id);

  // 5. 참가자가 동일 스레드에 게시글 작성 (참가자 권한 획득)
  const participantPost = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: participant.id,
      body: "스레드 참가자 게시글",
      created_at: now,
    },
  });
  typia.assert(participantPost);

  // 6. 참가자가 첨부파일 상세 조회 (성공)
  output = await api.functional.discussionboard.threads.postAttachments.getById(connection, { id: attachment.id });
  typia.assert(output);
  TestValidator.equals("참가자 파일명 일치")(output.file_name)("e2e-file.jpg");

  // 7. 비참가자가 파일 조회 시 권한 오류
  await TestValidator.error("비참가자 권한 오류 발생")(
    async () => {
      await api.functional.discussionboard.threads.postAttachments.getById(connection, { id: attachment.id });
    },
  );

  // 8. 존재하지 않는 첨부파일 id로 조회 시 404 NotFound
  await TestValidator.error("미존재 id NotFound 오류")(
    async () => {
      await api.functional.discussionboard.threads.postAttachments.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";

/**
 * Test uploading new file attachments to a post—including both success and failure scenarios.
 *
 * This E2E test will cover:
 *  1. Registering a new member (will act as post author and primary test user)
 *  2. Creating a thread as this member for the post context
 *  3. Creating a post in that thread as the member (attachment will be added to this post)
 *  4. Authenticated as the post author, uploading a file attachment (valid MIME/type/size)
 *  5. Verifying returned attachment metadata (file name, URI, type, uploaded_by, post relation)
 *  6. Testing failure modes:
 *      - Uploading as a different member (should be rejected)
 *      - Using invalid or missing post_id (should fail with not found/invalid)
 *      - Using an invalid or unsupported file type or oversized payload (should fail)
 *      - Exceeding attachment quota for user if such limit exists (should rate-limit/deny)
 *
 * Notes:
 *   - Because IDiscussionboardPostAttachment.ICreate expects file_uri already present (not raw binary upload),
 *     the test mocks file_uri and accepts business validation on type/size constraints at the API request property level (e.g., valid MIME strings, plausible URIs, plausible file_name).
 *   - The quota/rate error loop will stop on the first failure; if all attempts succeed, this is not treated as a test failure unless business rules require it.
 *   - All failure cases are checked for correct error.
 *   - Author/member distinction is asserted.
 */
export async function test_api_discussionboard_test_create_post_attachment_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Register a new member (will act as post author)
  const author: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(author);

  // 2. Create thread as the author
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: author.id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "open",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Create post in that thread
  const post: IDiscussionboardPosts = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: author.id,
      body: RandomGenerator.content()()(),
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 4. Authenticated as author, upload attachment (valid)
  const validAttachmentInput: IDiscussionboardPostAttachment.ICreate = {
    discussionboard_post_id: post.id,
    file_uri: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    file_name: `test_image_${RandomGenerator.alphaNumeric(8)}.jpg`,
    file_type: "image/jpeg",
    uploaded_by: author.id,
  };
  const attachment: IDiscussionboardPostAttachment = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: validAttachmentInput,
  });
  typia.assert(attachment);
  // Validate metadata matches the upload request
  TestValidator.equals("attached file uri")(attachment.file_uri)(validAttachmentInput.file_uri);
  TestValidator.equals("attached file name")(attachment.file_name)(validAttachmentInput.file_name);
  TestValidator.equals("attached file type")(attachment.file_type)(validAttachmentInput.file_type);
  TestValidator.equals("uploaded_by")(attachment.uploaded_by)(author.id);
  TestValidator.equals("linked post id")(attachment.discussionboard_post_id)(post.id);

  // 5. Failure: Upload as non-author should fail
  const otherMember: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(otherMember);
  TestValidator.notEquals("members are distinct")(author.id)(otherMember.id);
  const invalidMemberAttachment: IDiscussionboardPostAttachment.ICreate = {
    ...validAttachmentInput,
    // Only the 'uploaded_by' field changes
    uploaded_by: otherMember.id,
    file_name: `should_fail_${RandomGenerator.alphaNumeric(5)}.jpg`,
  };
  await TestValidator.error("non-author cannot upload attachment")(() =>
    api.functional.discussionboard.threads.postAttachments.post(connection, {
      body: invalidMemberAttachment,
    })
  );

  // 6. Failure: Invalid/missing post id (random, not real)
  const invalidPostIdAttachment: IDiscussionboardPostAttachment.ICreate = {
    ...validAttachmentInput,
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(), // unlikely to exist
    file_name: `nofile_${RandomGenerator.alphaNumeric(4)}.jpg`,
  };
  await TestValidator.error("upload to invalid post id should fail")(() =>
    api.functional.discussionboard.threads.postAttachments.post(connection, {
      body: invalidPostIdAttachment,
    })
  );

  // 7. Failure: Invalid file type
  const invalidFileTypeAttachment: IDiscussionboardPostAttachment.ICreate = {
    ...validAttachmentInput,
    file_type: "application/x-malware-exe", // pretend disallowed type
    file_name: `virus.exe`,
  };
  await TestValidator.error("disallowed file type should fail")(() =>
    api.functional.discussionboard.threads.postAttachments.post(connection, {
      body: invalidFileTypeAttachment,
    })
  );

  // 8. (Optional) Quota/rate error: upload > 3 attachments to see if quota is enforced; stop on first error
  let failOnQuota = false;
  for (let i=0;i<5 && !failOnQuota;i++) {
    const quotaTestAttachment: IDiscussionboardPostAttachment.ICreate = {
      ...validAttachmentInput,
      file_uri: `https://cdn.example.com/files/${typia.random<string & tags.Format<"uuid">>()}_${i}.png`,
      file_name: `quota_test${i}.png`,
      file_type: "image/png",
    };
    try {
      await api.functional.discussionboard.threads.postAttachments.post(connection, {
        body: quotaTestAttachment,
      });
    } catch {
      failOnQuota = true;
      // If quota is enforced, this is the expected result. If not, test passes anyway.
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";

/**
 * Validate permissions and error cases when updating metadata of a post attachment in Discussion Board.
 *
 * This test covers a variety of business rules and permission checks around the attachment update API:
 * - Only the owner/uploader and authorized moderators should have the ability to modify attachment metadata (file_name, file_type, file_uri).
 * - Unauthorized members are forbidden from making changes—such attempts should produce an appropriate permission error.
 * - Attempts to update a deleted attachment or a non-existent ID MUST result in a not found or business logic error (e.g., 404).
 * - Changing attachment metadata to a forbidden value (such as disallowed file types, empty file_name, or malformed URIs) must fail validation and NOT alter the attachment.
 *
 * Test process:
 * 1. Create 3 users: uploader (owner), a legitimate moderator (represented as a member here for test), and an unauthorized member.
 * 2. Create a thread and post as the owner.
 * 3. Upload an attachment to the post as the owner.
 * 4. As the owner/uploader, update the attachment metadata successfully; verify fields are updated.
 * 5. As moderator/admin (represented as a second member), also attempt update and verify it succeeds (normally this would be a role check—role simulation skipped if not available in API).
 * 6. As unauthorized member, attempt update and expect error.
 * 7. Attempt update on a non-existent attachment ID; expect not found/error.
 * 8. Attempt update with forbidden file_type or invalid value; expect validation error.
 *
 * Edge cases cover user-level permission as well as core business validation flows.
 */
export async function test_api_discussionboard_test_update_post_attachment_metadata_permission_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create uploader/owner
  const uploader: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, { body: {
    joined_at: new Date().toISOString(),
    status: "active",
  }});
  typia.assert(uploader);

  // 2. Create authorized staff (simulated as another member)
  const authorizedStaff: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, { body: {
    joined_at: new Date().toISOString(),
    status: "active",
  }});
  typia.assert(authorizedStaff);

  // 3. Create unauthorized ordinary member
  const unauthorized: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, { body: {
    joined_at: new Date().toISOString(),
    status: "active",
  }});
  typia.assert(unauthorized);

  // 4. Create thread as uploader
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.threads.post(connection, { body: {
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: uploader.id,
    title: "Thread for attachment test",
    description: "Thread to host test attachments",
    status: "open",
    created_at: new Date().toISOString(),
  }});
  typia.assert(thread);

  // 5. Create post as uploader
  const postEntity: IDiscussionboardPosts = await api.functional.discussionboard.threads.posts.post(connection, { body: {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: uploader.id,
    body: "This is a post with attachment",
    created_at: new Date().toISOString(),
  }});
  typia.assert(postEntity);

  // 6. Upload an attachment to post as uploader
  const attachment: IDiscussionboardPostAttachment = await api.functional.discussionboard.threads.postAttachments.post(connection, { body: {
    discussionboard_post_id: postEntity.id,
    file_uri: "https://example.com/original.pdf",
    file_name: "original.pdf",
    file_type: "application/pdf",
    uploaded_by: uploader.id,
  }});
  typia.assert(attachment);

  // 7. Owner updates metadata successfully
  const updated: IDiscussionboardPostAttachment = await api.functional.discussionboard.threads.postAttachments.putById(connection, {
    id: attachment.id,
    body: {
      file_name: "renamed.pdf",
      file_type: "application/pdf",
      file_uri: "https://example.com/renamed.pdf",
    },
  });
  typia.assert(updated);
  TestValidator.equals("metadata updated")(updated.file_name)("renamed.pdf");
  TestValidator.equals("metadata updated")(updated.file_uri)("https://example.com/renamed.pdf");
  TestValidator.equals("metadata updated")(updated.file_type)("application/pdf");

  // 8. Authorized staff (simulated as another member) updates metadata
  const updatedByStaff: IDiscussionboardPostAttachment = await api.functional.discussionboard.threads.postAttachments.putById(connection, {
    id: attachment.id,
    body: {
      file_name: "mod_staff.pdf",
      file_type: "application/pdf",
      file_uri: "https://example.com/mod_staff.pdf",
    },
  });
  typia.assert(updatedByStaff);
  TestValidator.equals("staff metadata update")(updatedByStaff.file_name)("mod_staff.pdf");

  // 9. Unauthorized member attempts update (should fail)
  TestValidator.error("unauthorized update error")(async () => {
    await api.functional.discussionboard.threads.postAttachments.putById(connection, {
      id: attachment.id,
      body: {
        file_name: "hacker.pdf",
        file_type: "application/pdf",
        file_uri: "https://example.com/hacker.pdf",
      },
    });
  });

  // 10. Update fails for non-existent attachment ID
  TestValidator.error("not found on non-existent ID")(async () => {
    await api.functional.discussionboard.threads.postAttachments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        file_name: "notfound.pdf",
        file_type: "application/pdf",
        file_uri: "https://example.com/notfound.pdf",
      },
    });
  });

  // 11. Validation error – forbidden file_type
  TestValidator.error("forbidden file_type")(async () => {
    await api.functional.discussionboard.threads.postAttachments.putById(connection, {
      id: attachment.id,
      body: {
        file_name: "virus.exe",
        file_type: "application/x-msdownload", // forbidden
        file_uri: "https://example.com/virus.exe",
      },
    });
  });

  // 12. Validation error – bad/malformed file_uri
  TestValidator.error("malformed file_uri")(async () => {
    await api.functional.discussionboard.threads.postAttachments.putById(connection, {
      id: attachment.id,
      body: {
        file_name: "file.pdf",
        file_type: "application/pdf",
        file_uri: "not-a-uri",
      },
    });
  });

  // 13. Validation error – empty file_name
  TestValidator.error("empty file_name")(async () => {
    await api.functional.discussionboard.threads.postAttachments.putById(connection, {
      id: attachment.id,
      body: {
        file_name: "",
        file_type: "application/pdf",
        file_uri: "https://example.com/file.pdf",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * Test deleting (soft-deleting) a post attachment as uploader, unauthorized member, moderator/admin, and with edge error cases.
 *
 * This test verifies:
 * - Only the uploader or admin can delete a post attachment.
 * - Deletion results in a soft-delete (record is marked as deleted, not fully removed).
 * - Attempting to delete again yields an appropriate error (already deleted/not found).
 * - An unauthorized member cannot delete the attachment (permission denied error).
 * - Deleting a non-existent attachment results in an error (not found).
 * - After deletion, record is flagged deleted for audit, but not accessible as active resource to regular members.
 *
 * Steps:
 * 1. Register uploader and unauthorized member
 * 2. Create a thread (under dummy board) as uploader
 * 3. Create a post under the thread as uploader
 * 4. Upload a post attachment as uploader
 * 5. Delete the attachment as uploader (should succeed, see deleted_at in response)
 * 6. Try to delete as unauthorized user (should fail: permission denied)
 * 7. Try to delete again as uploader (should fail: already deleted / not found)
 * 8. Try to delete a random non-existent attachment (should fail: not found)
 */
export async function test_api_discussionboard_test_delete_post_attachment_by_authorized_and_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create members (uploader and unauthorized)
  const uploader: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(uploader);

  const unauthorized: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(unauthorized);

  // 2. Create a thread (requires board id—we'll use a random UUID as board)
  const boardId: string = typia.random<string & tags.Format<"uuid">>();
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.threads.post(connection, {
    body: {
      discussionboard_board_id: boardId,
      discussionboard_member_id: uploader.id,
      title: `Thread for attachment delete test ${Math.random()}`,
      description: null,
      status: "open",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(thread);

  // 3. Create a post as uploader
  const post: IDiscussionboardPosts = await api.functional.discussionboard.threads.posts.post(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: uploader.id,
      body: `Test post body at ${new Date().toISOString()}`,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  // 4. Upload an attachment as uploader
  const attachment: IDiscussionboardPostAttachment = await api.functional.discussionboard.threads.postAttachments.post(connection, {
    body: {
      discussionboard_post_id: post.id,
      file_uri: `https://static.example.com/testfile-${Math.random()}.txt`,
      file_name: `testfile-${Math.random()}.txt`,
      file_type: "text/plain",
      uploaded_by: uploader.id,
    },
  });
  typia.assert(attachment);

  // 5. Delete the attachment as uploader (should succeed)
  const deleteResult: IDeleteResult = await api.functional.discussionboard.threads.postAttachments.eraseById(connection, {
    id: attachment.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("delete successful and deleted_at present")(deleteResult.status)("success");
  TestValidator.predicate("deleted_at timestamp is present and is ISO string")(typeof deleteResult.deleted_at === "string" && deleteResult.deleted_at.length > 0);

  // 6. Try to delete the same attachment as unauthorized member (should fail, permission denied)
  TestValidator.error("unauthorized member cannot delete attachment")(async () => {
    await api.functional.discussionboard.threads.postAttachments.eraseById(connection, {
      id: attachment.id,
    });
  });

  // 7. Try to delete again as uploader (should fail, already deleted)
  TestValidator.error("cannot delete already deleted attachment")(async () => {
    await api.functional.discussionboard.threads.postAttachments.eraseById(connection, {
      id: attachment.id,
    });
  });

  // 8. Try to delete a non-existent attachment (should fail, not found)
  TestValidator.error("cannot delete non-existent attachment")(async () => {
    await api.functional.discussionboard.threads.postAttachments.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";
import type { IPageDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardModerationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated/filtered retrieval of moderation logs as admin.
 *
 * This test validates that admin users can search moderation logs using all supported filters and that pagination and permission rules are enforced.
 *
 * Steps:
 * 1. Create a base member (will serve as moderator/admin)
 * 2. Promote member to admin
 * 3. Create multiple moderation log entries with varied action_types and targets using the admin
 * 4. Retrieve logs using different filters:
 *    a. By moderator_id
 *    b. By action_type
 *    c. By entity type/id
 *    d. By date range
 *    e. Combined filters
 *    f. Pagination (limit/page)
 *    g. Query with no matches
 *    h. Malformed filter (invalid UUID)
 *    i. Excessive page/limit
 *    j. Permissions: regular member or unauthenticated user forbidden
 */
export async function test_api_discussionboard_test_list_moderation_logs_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a base member user
  const member: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member);

  // Step 2: Promote the member to admin
  const adminAssignment: DiscussionBoardAdmins =
    await api.functional.discussionboard.actors.admins.post(connection, {
      body: {
        discussionboard_member_id: member.id,
        elevated_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies DiscussionBoardAdmins.ICreate,
    });
  typia.assert(adminAssignment);

  // Step 3: Create multiple moderation log entries with varied action_types, targets, and timestamps
  const actionTypes = ["delete_post", "warn_user", "suspend_member"];
  const logEntries: IDiscussionboardModerationLog[] = [];
  for (let i = 0; i < 6; ++i) {
    const type = actionTypes[i % actionTypes.length];
    const isEven = i % 2 === 0;
    const log: IDiscussionboardModerationLog =
      await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
        body: {
          moderator_id: member.id,
          action_type: type,
          target_member_id: isEven ? member.id : undefined,
          target_post_id: isEven ? typia.random<string & tags.Format<"uuid">>() : undefined,
          target_comment_id: isEven ? typia.random<string & tags.Format<"uuid">>() : undefined,
          action_details: `Log entry #${i} - ${type}`,
        } satisfies IDiscussionboardModerationLog.ICreate,
      });
    typia.assert(log);
    logEntries.push(log);
    // Space logs apart by 1 minute
    await new Promise((resolve) => setTimeout(resolve, 10)); // Not real time, but in reality would set ISO string differently
  }

  // Helper: Earliest/Latest log timestamps
  const timestamps = logEntries.map((l) => l.created_at).sort();
  const firstTimestamp = timestamps[0];
  const lastTimestamp = timestamps[timestamps.length - 1];

  // Step 4a: Filter by moderator_id
  {
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: member.id,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("all logs by moderator id")(output.data.every((l) => l.moderator_id === member.id))(true);
  }

  // Step 4b: Filter by action_type
  {
    const actionType = "warn_user";
    const expected = logEntries.filter((l) => l.action_type === actionType);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        action_type: actionType,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("correct action_type count")(output.data.length)(expected.length);
    TestValidator.equals("all logs with action_type warn_user")(output.data.every((l) => l.action_type === actionType))(true);
  }

  // Step 4c: Filter by entity type/id (target_member_id)
  {
    const id = member.id;
    const expected = logEntries.filter((l) => l.target_member_id === id);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        target_id: id,
        target_type: "member",
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("all by target_member_id")(output.data.every((l) => l.target_member_id === id))(true);
    TestValidator.equals("target_type set")(output.data.every((l) => l.target_member_id !== undefined))(true);
  }

  // Step 4d: Filter by date range
  {
    // We'll filter for only the logs created at/after the first, before the last
    const expected = logEntries.filter((l) => l.created_at >= firstTimestamp && l.created_at <= lastTimestamp);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        from: firstTimestamp as string & tags.Format<"date-time">,
        to: lastTimestamp as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("date range all in")(output.data.every((l) => l.created_at >= firstTimestamp && l.created_at <= lastTimestamp))(true);
    TestValidator.equals("count equals range")(output.data.length)(expected.length);
  }

  // Step 4e: Combined filters (moderator_id + action_type)
  {
    const actionType = "delete_post";
    const expected = logEntries.filter((l) => l.moderator_id === member.id && l.action_type === actionType);
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: member.id,
        action_type: actionType,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("combined filter moderator + action")(output.data.length)(expected.length);
  }

  // Step 4f: Pagination test (limit/page)
  {
    // Use typia.random to create values of correct intersection type for limit and page
    const limit = 2;
    const makeLimit = (n: number): number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }> => {
      const v = typia.random<number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }>>();
      return (n as typeof v);
    };
    const page1 = makeLimit(1);
    const page2 = makeLimit(2);
    const limit2 = makeLimit(limit);
    const outputPage1 = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit: limit2,
        page: page1,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(outputPage1);
    TestValidator.equals("pagination limit applies")(outputPage1.data.length <= limit)(true);
    TestValidator.equals("pagination page correct")(outputPage1.pagination.current)(1);

    const outputPage2 = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit: limit2,
        page: page2,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(outputPage2);
    TestValidator.equals("page 2 offset")(outputPage2.pagination.current)(2);
    TestValidator.equals("data no overlap")(outputPage1.data.every((a) => !outputPage2.data.map((b) => b.id).includes(a.id)))(true);
  }

  // Step 4g: Query with no matching filters (use fake UUID)
  {
    const noMatchUUID = typia.random<string & tags.Format<"uuid">>();
    const output = await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: noMatchUUID,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty set returns for no matches")(output.data.length)(0);
    TestValidator.equals("pagination meta present")(typeof output.pagination.current === "number")(true);
  }

  // Step 4h: Malformed filter (invalid UUID)
  await TestValidator.error("malformed UUID in filter returns error")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        moderator_id: "not-a-uuid-123" as string & tags.Format<"uuid">,
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
  });

  // Step 4i: Excessive paging (limit > 1000, which should be rejected by server business rules)
  const makeLimit = (n: number): number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }> => {
    const v = typia.random<number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "int32"; }>>();
    return (n as typeof v);
  };
  await TestValidator.error("over-limit on page size returns error")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
      body: {
        limit: makeLimit(100000),
      } satisfies IDiscussionboardModerationLog.IRequest,
    });
  });

  // Step 4j: Permissions – as regular member should be forbidden
  const member2: IDiscussionboardMembers =
    await api.functional.discussionboard.actors.members.post(connection, {
      body: {
        joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member2);
  await TestValidator.error("non-admin member gets 403")(
    async () => {
      await api.functional.discussionboard.moderation.moderationLogs.patch(connection, {
        body: {},
      });
    },
  );

  // Step 4j: Permissions – as unauthenticated (simulate by removing connection.headers.Authorization)
  const unauthConn: api.IConnection = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers && "Authorization" in unauthConn.headers)
    delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated access gets 403")(
    async () => {
      await api.functional.discussionboard.moderation.moderationLogs.patch(unauthConn, {
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
