import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";
import type { IDiscussionboardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationLog";

/**
 * Test permission and validation logic for updating discussionboard moderation log entries.
 *
 * This test ensures:
 * 1. Only admins (or permitted moderators) are able to update log entries
 * 2. Modified action detail or corrected targets are reflected in the response
 * 3. Attempts to update non-existent log entries yield 404 Not Found
 * 4. Regular members cannot update log entries – they receive 403 Forbidden
 * 5. Invalid payloads (e.g., missing required fields) trigger 400 Bad Request
 * 6. Business rules block updates to immutable/forbidden fields (if present)
 *
 * Steps:
 * 1. Register a new member and elevate to admin
 * 2. Admin creates a moderation log entry
 * 3. Admin updates the log entry (valid change): check fields are updated
 * 4. Attempt to update a non-existent log ID as admin (should get 404)
 * 5. Attempt to update as a regular member (should get 403)
 * 6. Send invalid payload (missing required fields): should get 400
 * 7. Attempt to change immutable fields (e.g., created_at): should fail (400/409)
 */
export async function test_api_discussionboard_test_update_moderation_log_entry_permissions_and_validation(
  connection: api.IConnection,
) {
  // Step 1: Register and promote a member to admin for permissions
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  const admin = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: new Date().toISOString(),
    },
  });
  typia.assert(admin);

  // Step 2: Admin creates a moderation log entry
  const log = await api.functional.discussionboard.moderation.moderationLogs.post(connection, {
    body: {
      moderator_id: member.id,
      action_type: "delete_post",
      action_details: "First moderation log entry.",
    },
  });
  typia.assert(log);

  // Step 3: Admin updates the log entry with a new action_details and target_post_id
  const updatedLog = await api.functional.discussionboard.moderation.moderationLogs.putById(connection, {
    id: log.id,
    body: {
      moderator_id: member.id,
      action_type: "delete_post",
      action_details: "This log entry was updated.",
      created_at: log.created_at,
      target_member_id: log.target_member_id ?? null,
      target_post_id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa",
      target_comment_id: log.target_comment_id ?? null,
    },
  });
  typia.assert(updatedLog);
  TestValidator.equals("action details updated")(updatedLog.action_details)("This log entry was updated.");
  TestValidator.equals("target post updated")(updatedLog.target_post_id)("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");

  // Step 4: Attempt update on a non-existent log
  await TestValidator.error("404 for missing log entry")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.putById(connection, {
      id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb",
      body: {
        moderator_id: member.id,
        action_type: "warn_user",
        created_at: log.created_at,
      },
    });
  });

  // Step 5: Create a second member (regular user, not admin)
  const regular = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(regular);

  // Attempt to update the log as a regular member (simulate non-admin)
  await TestValidator.error("403 forbidden for regular member")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.putById(connection, {
      id: log.id,
      body: {
        moderator_id: regular.id,
        action_type: "delete_post",
        created_at: log.created_at,
      },
    });
  });

  // Step 6: Send update with missing required fields (should 400)
  await TestValidator.error("400 bad request for invalid update")(async () => {
    // action_type missing
    await api.functional.discussionboard.moderation.moderationLogs.putById(connection, {
      id: log.id,
      body: {
        moderator_id: member.id,
        created_at: log.created_at,
      } as any,
    });
  });

  // Step 7: Attempt to update immutable/audit fields (e.g., created_at)
  await TestValidator.error("business rule, cannot modify created_at timestamp")(async () => {
    await api.functional.discussionboard.moderation.moderationLogs.putById(connection, {
      id: log.id,
      body: {
        moderator_id: member.id,
        action_type: "delete_post",
        created_at: new Date("2000-01-01T00:00:00.000Z").toISOString(),
      },
    });
  });
}

