import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IPageIDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching channels as an admin with pagination, filters, and search.
 *
 * This test ensures that:
 * 1. Channels are created with a mix of enabled states, codes, names, and descriptions.
 * 2. Admin can list channels:
 *    - with no filter (retrieves all)
 *    - filtered by enabled status
 *    - searched by text (name/description)
 *    - using pagination (limit/page)
 * 3. Each response: data/pagination are validated for correctness.
 * 4. Schema requirements (required fields present) are checked for all returned entities.
 * 5. Edge case: confirm empty result for non-matching filter/search.
 *
 * Workflow:
 * 1. Seed distinct channels (unique, random codes) with a variety of enabled states
 * 2. Query with:
 *    a. No filter/query
 *    b. enabled=true
 *    c. enabled=false
 *    d. search term for name and description
 *    e. pagination (limit/page)
 *    f. query that matches no results
 * 3. Assert for each step:
 *    - Data set matches expectation
 *    - Pagination metadata correct
 *    - All required fields per schema are present
 */
export async function test_api_discussionboard_systematic_channels_test_list_channels_with_search_and_pagination_by_admin(
  connection: api.IConnection,
) {
  // 1. Seed channel data: unique codes/names to ensure test idempotence
  const channelSeed = [
    { code: `ECON_${RandomGenerator.alphaNumeric(6)}`, name: "Economics Alpha", description: "Economic analysis", enabled: true },
    { code: `POLI_${RandomGenerator.alphaNumeric(6)}`, name: "Politics Beta", description: "Political forum", enabled: true },
    { code: `SCI_${RandomGenerator.alphaNumeric(6)}`, name: "Science Gamma", description: "Science discussion", enabled: true },
    { code: `ART_${RandomGenerator.alphaNumeric(6)}`, name: "Art Delta", description: "Art and culture", enabled: false },
    { code: `SPORT_${RandomGenerator.alphaNumeric(6)}`, name: "Sports Epsilon", description: "Sports fans club", enabled: false },
  ];
  const seeded: IDiscussionboardChannel[] = [];
  for(const input of channelSeed) {
    const channel = await api.functional.discussionboard.systematic.channels.post(connection, {
      body: {
        code: input.code,
        name: input.name,
        description: input.description,
        enabled: input.enabled
      } satisfies IDiscussionboardChannel.ICreate,
    });
    typia.assert(channel);
    seeded.push(channel);
  }

  // Helper: Sort canonically by code for test assertions
  const sortByCode = (arr: IDiscussionboardChannel[]) => [...arr].sort((a, b) => a.code.localeCompare(b.code));

  // 2a. List all channels (no filter)
  const resAll = await api.functional.discussionboard.systematic.channels.patch(connection, { body: {} });
  typia.assert(resAll);
  const allCodes = sortByCode(seeded).map(c => c.code);
  // All created codes should be present in global fetch
  TestValidator.predicate("All seeded channels appear")(
    allCodes.every(code => resAll.data.some(item => item.code === code))
  );

  // 2b. List enabled channels
  const resEnabled = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { enabled: true } });
  typia.assert(resEnabled);
  const enabledSeed = sortByCode(seeded.filter(c => c.enabled));
  TestValidator.equals("Only enabled channels returned")(
    sortByCode(resEnabled.data).map(c=>c.code)
  )(enabledSeed.map(c=>c.code));

  // 2c. List disabled channels
  const resDisabled = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { enabled: false } });
  typia.assert(resDisabled);
  const disabledSeed = sortByCode(seeded.filter(c => !c.enabled));
  TestValidator.equals("Only disabled channels returned")(
    sortByCode(resDisabled.data).map(c=>c.code)
  )(disabledSeed.map(c=>c.code));

  // 2d. Search by unique name substring
  const searchTerm = "Delta";
  const resSearchName = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { search: searchTerm } });
  typia.assert(resSearchName);
  TestValidator.predicate("Search by name substring")(
    resSearchName.data.every(item => item.name.includes(searchTerm) || (item.description ?? "").includes(searchTerm))
  );
  // 2d2. Search by unique description substring
  const descTerm = "fans";
  const resSearchDesc = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { search: descTerm } });
  typia.assert(resSearchDesc);
  TestValidator.predicate("Search by description substring")(
    resSearchDesc.data.every(item => (item.description ?? "").toLowerCase().includes(descTerm))
  );

  // 2e. Pagination (limit=2, page=1 and 2)
  const resPag1 = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { limit: 2, page: 1 } });
  typia.assert(resPag1);
  TestValidator.equals("Page 1 length")(resPag1.data.length)(2);
  TestValidator.equals("Page 1 number")(resPag1.pagination.current)(1);

  const resPag2 = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { limit: 2, page: 2 } });
  typia.assert(resPag2);
  TestValidator.equals("Page 2 length")(resPag2.data.length)(2);
  TestValidator.equals("Page 2 number")(resPag2.pagination.current)(2);

  // Pagination metadata: record count matches seeded
  TestValidator.equals("Total records matches seed count")(resPag2.pagination.records)(seeded.length);
  // No duplicates between pages 1 and 2
  TestValidator.predicate("Pages do not overlap")(
    resPag1.data.every(r1 => resPag2.data.every(r2 => r1.id !== r2.id))
  );
  // All seed codes appear in union of paginated page1/page2/page3
  const resPag3 = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { limit: 2, page: 3 } });
  typia.assert(resPag3);
  const pagedDat = [...resPag1.data, ...resPag2.data, ...resPag3.data];
  TestValidator.predicate("All seeded codes among all pages")(
    allCodes.every(code => pagedDat.some(item => item.code === code))
  );

  // 2f. Edge case: search for non-existent value returns empty
  const magic = "ZzzzUnlikelyMagicTerm";
  const resEmpty = await api.functional.discussionboard.systematic.channels.patch(connection, { body: { search: magic } });
  typia.assert(resEmpty);
  TestValidator.equals("Empty result for non-existent search")(resEmpty.data.length)(0);
  TestValidator.equals("Empty page for non-existent search")(resEmpty.pagination.records)(0);

  // 3. Check all required channel fields are present for all data returned in a full fetch
  for (const item of resAll.data) {
    ["id","code","name","enabled","created_at","updated_at"].forEach(key => {
      TestValidator.predicate(`Channel has field: ${key}`)(typeof (item as any)[key] !== "undefined");
    });
  }
}

