  let channelAfterDelete: IDiscussionboardChannel | null = null;
  try {
    channelAfterDelete = await api.functional.discussionboard.systematic.channels.getById(connection, {
      id: created.id,
    });
    typia.assert(channelAfterDelete);
  } catch (err) {
    retrievalError = err as Error;
  }

  // 4. Validate system behavior: either an error OR deleted_at is set in response
  if (channelAfterDelete) {
    TestValidator.equals("Soft-deleted flag present")(channelAfterDelete.deleted_at !== null && channelAfterDelete.deleted_at !== undefined)(true);
    TestValidator.equals("deleted_at matches erase result")(channelAfterDelete.deleted_at)(removed.deleted_at);
  } else {
    TestValidator.predicate("Should return error for soft-deleted channel")(retrievalError !== null);
  }
}

