/**
 * Validate updating a discussion board channel's details by an admin with valid input.
 *
 * Business context:
 * Channels are top-level forum divisions managed by admins. This test ensures an admin can successfully update a channel's display properties and onboarding info, and that the mutation persists as expected and meets business audit requirements (timestamps, id invariance, etc).
 *
 * Step-by-step process:
 * 1. Create a new channel (setup for update test)
 * 2. Update the channel's name, description, and enabled state using valid new values
 * 3. Verify all mutations persist, non-editable fields are unchanged, and updated_at advances
 */
export async function test_api_discussionboard_systematic_channels_test_update_channel_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new channel (setup)
  const createInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const original: IDiscussionboardChannel = await api.functional.discussionboard.systematic.channels.post(
    connection, { body: createInput }
  );
  typia.assert(original);

  // 2. Update editable channel details (name, description, enabled)
  const updateInput: IDiscussionboardChannel.IUpdate = {
    name: RandomGenerator.paragraph()(1) + " updated",
    description: RandomGenerator.paragraph()(),
    enabled: false,
  };
  const updated: IDiscussionboardChannel = await api.functional.discussionboard.systematic.channels.putById(
    connection,
    {
      id: original.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 3. Verify mutations and invariants
  // ID must not change
  TestValidator.equals("id unchanged")(updated.id)(original.id);
  // Code should not be affected by update
  TestValidator.equals("code unchanged")(updated.code)(original.code);
  // Name should reflect the new value
  TestValidator.equals("name reflects update")(updated.name)(updateInput.name);
  // Description should reflect the new value
  TestValidator.equals("description reflects update")(updated.description)(updateInput.description);
  // Enabled state should reflect the changed value
  TestValidator.equals("enabled reflects update")(updated.enabled)(updateInput.enabled);
  // Updated_at should move forward in time
  TestValidator.predicate("updated_at is more recent")(
    new Date(updated.updated_at) > new Date(original.updated_at)
  );
  // Audit log verification omitted (not available via API)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Validates that channel code uniqueness constraint *cannot* be directly tested on update,
 * because the API does not permit channel `code` changes via update.
 *
 * This test demonstrates that the existing API (per IDiscussionboardChannel.IUpdate)
 * only allows patching name/description/enabled, not code. Thus, trying to induce a code conflict on update
 * is impossible via the current contract. For completeness, the test shows that the API
 * correctly prevents code changes (by omission): an attempt to set code would be rejected by TypeScript.
 *
 * Steps:
 * 1. Create channel A with code 'firstCode'.
 * 2. Create channel B with code 'secondCode'.
 * 3. Attempt to update channel B -- code update not permitted, so only name/description/enabled may change.
 *
 * This test asserts that the code field is immutable post-creation, so uniqueness is enforced at creation only.
 * It also signals to system maintainers/testers that putById cannot be used to cause code duplication.
 */
export async function test_api_discussionboard_systematic_channels_test_update_channel_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create channel A with a unique code
  const channelA = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: 'firstCode',
      name: 'First Channel',
      description: 'Channel A description',
      enabled: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channelA);

  // 2. Create channel B with another unique code
  const channelB = await api.functional.discussionboard.systematic.channels.post(connection, {
    body: {
      code: 'secondCode',
      name: 'Second Channel',
      description: 'Channel B description',
      enabled: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channelB);

  // 3. Attempt to update channelB's code to cause duplication -- not permitted by API contract.
  //    The only allowed updatable fields are name, description, and enabled.
  //    Attempting to include a `code` property here would violate TypeScript typing
  //    and cause a compile-time error. Thus, documented as untestable.
  //
  // Example of a permitted update (does not test duplication; just for demonstration):
  const updated = await api.functional.discussionboard.systematic.channels.putById(connection, {
    id: channelB.id,
    body: {
      name: 'Updated Second Channel',
      description: 'Updated description',
      enabled: false,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("update channel name")(updated.name)('Updated Second Channel');
  TestValidator.equals("update channel description")(updated.description)('Updated description');
  TestValidator.equals("update channel enabled")(updated.enabled)(false);
  TestValidator.equals("update channel code unchanged")(updated.code)(channelB.code);
  //
  // Conclusion: There is no way to trigger a code duplication update via the current API.
}

