  const like = await api.functional.discussionboard.interactions.commentLikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    } satisfies IDiscussionboardCommentLike.ICreate,
  });
  typia.assert(like);

  // 4. Retrieve the like by its ID as the liking member (should succeed)
