/**
 * Test successful creation of a comment like by an authenticated member, duplicate like prevention,
 * unauthenticated access prevention, and handling of invalid comment scenarios (audit/audit trail implied).
 *
 * Business context:
 *  - Members (users) can like comments in the forum, but only once per comment (unique constraint: member+comment).
 *  - Unauthenticated users must be rejected when trying to like a comment.
 *  - Liking nonexistent comments must also fail (foreign key constraint).
 *  - Audit trail (implicit in DB timestamps and errors) must be verifiable.
 *
 * Steps:
 * 1. Register a new member (will act as the liker).
 * 2. Create a comment (must belong to a post, so generate reasonable random IDs as needed for post/discussion relation).
 * 3. Like the comment as the member — expect success, check that created record contains correct member and comment IDs and timestamp.
 * 4. Attempt to like the same comment again with the same member — expect error (duplicate prevention, business rule enforced via DB constraint). TestValidator.error.
 * 5. Attempt to like as an unauthenticated user (simulate by sending with an empty/bare connection) — expect error.
 * 6. Attempt to like a clearly nonexistent comment as a valid member (use a random UUID not used ever) — expect error.
 * 7. (Implicitly) Confirm audit data on error is correct (timestamp tracked, error thrown etc).
 */
export async function test_api_discussionboard_test_create_comment_like_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // Step 1. Register a new member
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    },
  });
  typia.assert(member);

  // Step 2. Create a comment (on random post, as the new member)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member.id,
      body: "This is a test comment for like.",
      parent_id: null,
    },
  });
  typia.assert(comment);

  // Step 3. Like the comment as the member (expect success)
  const like = await api.functional.discussionboard.interactions.commentLikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id,
    },
  });
  typia.assert(like);
  TestValidator.equals("like record matches member")(like.discussionboard_member_id)(member.id);
  TestValidator.equals("like record matches comment")(like.discussionboard_comment_id)(comment.id);
  TestValidator.predicate("like created_at non-empty")(!!like.created_at);

  // Step 4. Attempt duplicate like (should fail with error)
  await TestValidator.error("duplicate like prevented")(async () => {
    await api.functional.discussionboard.interactions.commentLikes.post(connection, {
      body: {
        discussionboard_comment_id: comment.id,
      },
    });
  });

  // Step 5. Attempt to like as unauthenticated user (simulate by wiping headers)
  const bareConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated like prevented")(async () => {
    await api.functional.discussionboard.interactions.commentLikes.post(bareConnection, {
      body: {
        discussionboard_comment_id: comment.id,
      },
    });
  });

  // Step 6. Attempt to like a nonexistent comment as the member (should fail)
  const fakeCommentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("like on nonexistent comment fails")(async () => {
    await api.functional.discussionboard.interactions.commentLikes.post(connection, {
      body: {
        discussionboard_comment_id: fakeCommentId,
      },
    });
  });

  // Step 7. (Audit trail is implicitly verified via timestamp and API errors.)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
