/**
 * Validates the update behavior of comment like resources in the Discussion Board.
 *
 * This test covers several business permission and audit scenarios for the comment like update API:
 * 1. The liking member should be able to update their own like (SUCCESS case).
 * 2. A moderator/admin can update any like (SUCCESS case, permission elevation).
 * 3. A different regular member must not be able to update other users' comment likes (FAILURE, forbidden).
 * 4. Performing an update with a non-existent like ID should return a 404 (FAILURE).
 * 5. If an update succeeds, the changes should be reflected in the returned resource, and all updates must be tracked in audit logs (though audit log validation is not possible via SDK, so focus on update result validation).
 *
 * Steps:
 * - Create three members: owner (who creates the like), regular non-owner, and admin/moderator.
 * - Use the owner to create a comment.
 * - Owner likes the comment.
 * - Owner attempts to update the like (should succeed/200).
 * - Admin attempts to update the owner’s like (should succeed/200).
 * - Non-owner member attempts to update the owner’s like (should fail with forbidden/403).
 * - Attempt to update a non-existent like ID (should fail with 404).
 * - After successful update(s), fetch the like resource and validate result matches update.
 */
export async function test_api_discussionboard_test_update_comment_like_by_owner_admin_moderator_or_forbidden_user(connection: api.IConnection) {
  // Step 1: Create three members (owner, admin, and non-owner)
  const owner: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(owner);

  const admin: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
      status: "active" // For test, treat this as admin (permission model is not visible, can't fake extra role)
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(admin);

  const stranger: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(stranger);

  // Step 2: Owner creates a comment
  const comment: IDiscussionboardComment = await api.functional.discussionboard.threads.comments.post(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),  // Simulate real thread context
      discussionboard_member_id: owner.id,
      body: "Initial comment body for like test"
    } satisfies IDiscussionboardComment.ICreate
  });
  typia.assert(comment);

  // Step 3: Owner likes the comment
  const like: IDiscussionboardCommentLike = await api.functional.discussionboard.interactions.commentLikes.post(connection, {
    body: {
      discussionboard_comment_id: comment.id
    } satisfies IDiscussionboardCommentLike.ICreate
  });
  typia.assert(like);

  // Step 4: Owner attempts to update the like (should succeed)
  const updated_comment_id_by_owner: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const updatedLikeByOwner: IDiscussionboardCommentLike = await api.functional.discussionboard.interactions.commentLikes.putById(connection, {
    id: like.id,
    body: {
      discussionboard_comment_id: updated_comment_id_by_owner
    } satisfies IDiscussionboardCommentLike.IUpdate
  });
  typia.assert(updatedLikeByOwner);
  TestValidator.equals("Comment like updated by owner")(
    updatedLikeByOwner.discussionboard_comment_id
  )(updated_comment_id_by_owner);

  // Step 5: Admin attempts to update the owner’s like (should succeed)
  const updated_comment_id_by_admin: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  // In a real system, you would switch auth context to admin; here, semantic only
  const updatedLikeByAdmin: IDiscussionboardCommentLike = await api.functional.discussionboard.interactions.commentLikes.putById(connection, {
    id: like.id,
    body: {
      discussionboard_comment_id: updated_comment_id_by_admin
    } satisfies IDiscussionboardCommentLike.IUpdate
  });
  typia.assert(updatedLikeByAdmin);
  TestValidator.equals("Comment like updated by admin")(
    updatedLikeByAdmin.discussionboard_comment_id
  )(updated_comment_id_by_admin);

  // Step 6: Stranger (non-owner) tries to update the like (should fail)
  await TestValidator.error("Only owner or admin can update like")(
    async () => {
      await api.functional.discussionboard.interactions.commentLikes.putById(connection, {
        id: like.id,
        body: {
          discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>() // Attempt arbitrary update
        } satisfies IDiscussionboardCommentLike.IUpdate
      });
    }
  );

  // Step 7: Update with non-existent like ID (should 404)
  await TestValidator.error("Updating with non-existent like ID returns 404")(
    async () => {
      await api.functional.discussionboard.interactions.commentLikes.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // Unused/random UUID
        body: {
          discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>()
        } satisfies IDiscussionboardCommentLike.IUpdate
      });
    }
  );

  // Step 8: Validate result is reflected (fetch updated resource)
  // Since there’s no GET-by-id for like in SDK, and full state is in PUT output
  TestValidator.equals("Like ID matches after owner/admin update")(
    updatedLikeByAdmin.id
  )(like.id);
  TestValidator.equals("Member ID of like remains unchanged")(
    updatedLikeByAdmin.discussionboard_member_id
  )(owner.id);
  TestValidator.equals("Last updated comment ref matches admin update")(
    updatedLikeByAdmin.discussionboard_comment_id
  )(updated_comment_id_by_admin);
}

