  const updateInput = {
    email_enabled: !initialSettings.email_enabled,
    reply_notification_enabled: !initialSettings.reply_notification_enabled,
    moderation_notification_enabled: !initialSettings.moderation_notification_enabled,
    announcement_notification_enabled: !initialSettings.announcement_notification_enabled,
