import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * Validate fetching admin assignment details by ID as an admin user.
 *
 * This test ensures that a discussion board admin can fetch details for a specific admin assignment (role elevation) using a valid assignment ID. It comprehensively checks that all fields are present in the response, with expected values for member linkage, privilege timestamps, and record ID, ensuring robust role-based access control and data integrity in admin assignment management.
 *
 * Test workflow:
 * 1. Create a new member (to be promoted to admin).
 * 2. Assign admin role to this member (create admin assignment).
 * 3. Fetch the admin assignment by its ID (as an admin user).
 * 4. Validate the response: ensure returned data is present, types match expectation, and content (linked member ID, elevation timestamp) matches what was created.
 */
export async function test_api_discussionboard_actors_admins_getById(
  connection: api.IConnection,
) {
  // 1. Create a new member (for promotion)
  const now: string = new Date().toISOString();
  const member = await api.functional.discussionboard.actors.members.post(
    connection,
    {
      body: {
        joined_at: now,
        status: "active",
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Assign admin role to created member
  const elevated_at: string = new Date().toISOString();
  const created = await api.functional.discussionboard.actors.admins.post(
    connection,
    {
      body: {
        discussionboard_member_id: member.id,
        elevated_at,
      } satisfies DiscussionBoardAdmins.ICreate,
    },
  );
  typia.assert(created);

  // 3. Fetch the admin assignment by its ID
  const detail = await api.functional.discussionboard.actors.admins.getById(
    connection,
    {
      id: created.id,
    },
  );
  typia.assert(detail);

  // 4. Validate data matches what was created
  TestValidator.equals("admin ID matches")(detail.id)(created.id);
  TestValidator.equals("linked member matches")(detail.discussionboard_member_id)(member.id);
  TestValidator.equals("elevation timestamp matches")(detail.elevated_at)(created.elevated_at);
}

