import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { DiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAdmins";

/**
 * Test updating an existing admin assignment (DiscussionBoardAdmins) by ID.
 *
 * Business context:
 * This test covers the workflow where privileged admin users update other admin assignments—such as changing elevation time (demotion/recertification). It validates correct privilege enforcement, property persistence, and ensures that changes (like new elevation timestamps) are stored and auditable. The setup ensures a member is created and promoted to admin, then that admin assignment is updated. We also validate that only admins are allowed and changes are persisted according to the schema. (Audit logging validation is acknowledged but not implemented due to API limitations.)
 *
 * Steps:
 * 1. Create a regular member (gained UUID).
 * 2. Promote this member to admin (creates an admin assignment with a unique ID).
 * 3. Update the admin assignment via PUT, changing the elevation timestamp.
 * 4. Verify the returned admin assignment reflects the new elevation timestamp and unchanged fields persist.
 * 5. (Negative Case): Confirm that if a non-admin tries to perform the PUT, access is denied. (Cannot implement: no login or session API in scope. Step acknowledged.)
 */
export async function test_api_discussionboard_admins_test_update_admin_assignment_with_valid_attributes(connection: api.IConnection) {
  // 1. Create a member (simulate registration with random join date and status)
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: typia.random<string & tags.Format<"date-time">>(),
      status: "active",
    },
  });
  typia.assert(member);

  // 2. Promote the member to admin (create DiscussionBoardAdmins record)
  const adminAssignment = await api.functional.discussionboard.actors.admins.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      elevated_at: typia.random<string & tags.Format<"date-time">>(),
    },
  });
  typia.assert(adminAssignment);

  // Capture old info for comparison
  const { id: adminId, discussionboard_member_id, elevated_at: oldElevation } = adminAssignment;

  // 3. Update the admin assignment with a new elevation timestamp
  const newElevation = typia.random<string & tags.Format<"date-time">>();
  const updated = await api.functional.discussionboard.actors.admins.putById(connection, {
    id: adminId,
    body: { elevated_at: newElevation },
  });
  typia.assert(updated);

  // 4. Verification checks
  TestValidator.equals("admin id")(updated.id)(adminAssignment.id);
  TestValidator.equals("admin member id")(updated.discussionboard_member_id)(discussionboard_member_id);
  TestValidator.equals("elevated_at updated")(updated.elevated_at)(newElevation);
  TestValidator.notEquals("elevated_at changed")(updated.elevated_at)(oldElevation);

  // 5. (Negative) If non-admin tries update, access should fail (not implemented).
}

