  // 2. Create 4 topics with varying codes/titles (simulate different keywords)
  const creatorIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const topicDefs = [
    { code: "alpha", title: "Announcement Alpha" },
    { code: "beta", title: "Beta Discussion" },
    { code: "gamma", title: "General Gamma News" },
    { code: "delta", title: "Delta Updates" },
  ];

  const topics = [];
  for (let i = 0; i < topicDefs.length; ++i) {
    const makerId = creatorIds[i % creatorIds.length];
    const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
      body: {
        discussionboard_board_id: board.id,
        code: topicDefs[i].code,
        title: topicDefs[i].title,
        created_by_member_id: makerId,
      } satisfies DiscussionBoardBoardTopic.ICreate,
