  // Validate response: topics listed belong to test board
  const topicIdsCreated = topics.map(t => t.id);
  for (const topic of listOutput.data) {
    TestValidator.predicate("topic belongs to created board")(topic.discussionboard_board_id === board.id);
  }
  // At least one topic must be among those created in this test
  TestValidator.predicate("at least one created topic in list")(listOutput.data.some(t => topicIdsCreated.includes(t.id)));
  // Pagination info should be present and have sensible values
  TestValidator.predicate("pagination.current >= 1")(listOutput.pagination.current >= 1);
  TestValidator.predicate("pagination.limit >0")(listOutput.pagination.limit > 0);
  TestValidator.predicate("pagination.records >= data length")(listOutput.pagination.records >= listOutput.data.length);
}

