 * 3. Prepare a topic creation request object with unique code, title, description, referencing the created board and member.
 * 4. Call the boardTopics creation endpoint with this data.
 * 5. Validate that the response contains correct code, title, description, links to the right board and member, and all required fields are present and valid.
 */
export async function test_api_discussionboard_test_create_board_topic_success(
  connection: api.IConnection,
) {
  // 1. Create a new board (requires a category UUID). Generate a random UUID to simulate a category association.
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const boardCode = RandomGenerator.alphaNumeric(8);
  const boardName = RandomGenerator.paragraph()(1);
  const boardDescription = RandomGenerator.paragraph()(2);

