    body: {
      discussionboard_category_id: categoryId,
      code: boardCode,
      name: boardName,
      description: boardDescription,
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // 2. Create a member who will be the topic creator
  const memberStatus = "active";
  const joinedAt = new Date().toISOString();
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: joinedAt,
      status: memberStatus,
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 3. Prepare topic creation data
  const topicCode = RandomGenerator.alphaNumeric(8);
  const topicTitle = RandomGenerator.paragraph()(1);
  const topicDescription = RandomGenerator.paragraph()(2);

  const topicInput = {
    discussionboard_board_id: board.id,
    code: topicCode,
    title: topicTitle,
    description: topicDescription,
    created_by_member_id: member.id,
