/**
 * Validate that unauthorized users (non-topic owners with no extra permissions) cannot delete board topics.
 *
 * This test ensures that only the creator or privileged users can perform topic deletion. It verifies:
 * - A topic owner can create a board topic.
 * - A different, unrelated member must NOT be able to delete the topic.
 * - Unauthenticated (no user context) deletion is forbidden.
 *
 * Process:
 * 1. Create a board (requires category ID, so use a random UUID for the category).
 * 2. Register a member as topic creator ("owner").
 * 3. Have the owner create a topic in the board.
 * 4. Register a second member who is not the topic owner.
 * 5. As the second member, attempt to delete the topic and check for a permissions error.
 * 6. As an unauthenticated user, attempt to delete the topic and confirm forbidden/permission error.
 *
 * Business rules:
 * - Board/topic creation should succeed for regular members, but deletion should be permission-guarded.
 * - API must reject topic deletion attempts from non-owner, non-privileged users (with error).
 * - API must reject deletion attempts when no member authentication is present (with error).
 *
 * This test does NOT depend on the presence of moderators/admins (only owner and generic member tested).
 */
export async function test_api_discussionboard_test_delete_board_topic_by_unauthorized_user(
  connection: api.IConnection,
) {
  // Step 1: Create a board
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.boards.post(connection, {
    body: {
      discussionboard_category_id: categoryId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
    } satisfies DiscussionboardBoard.ICreate,
  });
  typia.assert(board);

  // Step 2: Create topic owner member
  const ownerMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(ownerMember);

  // Step 3: Owner creates a topic
  const topic = await api.functional.discussionboard.boards.boardTopics.post(connection, {
    body: {
      discussionboard_board_id: board.id,
      code: RandomGenerator.alphaNumeric(8),
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      created_by_member_id: ownerMember.id,
    } satisfies DiscussionBoardBoardTopic.ICreate,
  });
  typia.assert(topic);

  // Step 4: Create non-owner member
  const nonOwnerMember = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active",
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(nonOwnerMember);

  // Step 5: As non-owner, attempt to delete the topic (should fail with permission error)
  TestValidator.error("Non-owner member should not delete the topic")(
    async () => {
      await api.functional.discussionboard.boards.boardTopics.eraseById(connection, {
        id: topic.id,
      });
    },
  );

  // Step 6: Attempt deleting as unauthenticated user (should fail with permission error)
  const unauthConnection = { ...connection, headers: {} };
  TestValidator.error("Unauthenticated user cannot delete the topic")(
    async () => {
      await api.functional.discussionboard.boards.boardTopics.eraseById(unauthConnection, {
        id: topic.id,
      });
    },
  );
}

