  // e) Missing recipient
  await TestValidator.error("missing recipient should fail")(async () => {
    const { discussionboard_member_id, ...body } = base;
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: body as IDiscussionboardNotification.ICreate,
    });
  });
  // f) Completely empty body
  await TestValidator.error("empty body should fail")(async () => {
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {} as IDiscussionboardNotification.ICreate,
    });
  });
  // g) Extra/malformed field
  await TestValidator.error("extra property should fail")(async () => {
    await api.functional.discussionboard.notifications.notifications.post(connection, {
      body: {
        ...base,
        extra_field: "not allowed",
      } as any,
    });
  });

  // 3. Unauthenticated attempt (if API enforces authentication, simulate logout and try)
  // (Omitted: no mechanism to change connection state without user/session API)

  // 4. Cannot confirm notification was not created since no list API exists (skip)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Validate that a discussion board member can mark their own notification as read by updating the read_at property.
 *
 * Business context:
 * Members receive notifications (such as replies, mentions, announcements). They must be able to independently mark their notifications as read, i.e., by setting 'read_at' to the current date/time. This action should only affect the member’s copy of the notification, meeting privacy and audit requirements.
 *
 * Steps:
 * 1. Create a new discussion board member (register a new user)
 * 2. Issue a notification to this member (create notification)
 * 3. Mark the notification as read by updating the read_at property (using PUT endpoint)
 * 4. Validate that the notification now has a non-null read_at field (confirm it is the time just set)
 * 5. Confirm that the change applies to this member’s notification only (not relevant for this single-member scenario, but business logic implies this should hold for multi-member in production)
 */
export async function test_api_discussionboard_notifications_test_update_notification_mark_as_read_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Create a new board member
  const now = new Date().toISOString();
  const member = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: now,
      status: "active",
    },
  });
  typia.assert(member);

  // Step 2: Issue a notification targeting this member
  const deliveredAt = new Date().toISOString();
  const notification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      type: "reply",
      title: "Test notification title",
      body: "You got a test notification!",
      delivered_at: deliveredAt,
    },
  });
  typia.assert(notification);
  TestValidator.equals("notification unread before mark")(notification.read_at)(null);

  // Step 3: Mark the notification as read by setting read_at
  const markReadAt = new Date().toISOString();
  const updatedNotification = await api.functional.discussionboard.notifications.notifications.putById(connection, {
    id: notification.id,
    body: {
      read_at: markReadAt,
    },
  });
  typia.assert(updatedNotification);

  // Step 4: Validate that read_at is set correctly
  TestValidator.equals("notification now marked as read")(updatedNotification.read_at)(markReadAt);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
