/**
 * Validate that non-owners cannot update notifications belonging to other members.
 *
 * This test ensures that a member (User B) cannot mark as read or alter the content
 * of a notification that was delivered to another member (User A). Attempting to do so
 * should result in a forbidden (403) error and should not modify the original notification.
 *
 * Testing Steps:
 * 1. Create Member A (intended notification owner)
 * 2. Create Member B (non-owner, attacker)
 * 3. As Member A, create a notification for himself
 * 4. Save Member A's notification id
 * 5. As Member B, attempt to update Member A's notification (e.g., mark as read)
 * 6. Confirm a 403 error or equivalent is returned
 * 7. Optionally, as Member A, fetch/read the notification again to ensure it is unmodified
 */
export async function test_api_discussionboard_notifications_notifications_test_update_notification_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Create Member A (Notification Owner)
  const memberA = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberA);

  // 2. Create Member B (Non-owner)
  const memberB = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: 'active',
    },
  });
  typia.assert(memberB);

  // 3. As Member A, create a notification for himself
  const notification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      type: 'reply',
      title: 'You have a new reply!',
      body: 'Check out your new reply in the discussion.',
      url: null,
      delivered_at: new Date().toISOString(),
    },
  });
  typia.assert(notification);

  // 4. As Member B, attempt to update the notification belonging to Member A
  await TestValidator.error('non-owner cannot update notification')(async () => {
    await api.functional.discussionboard.notifications.notifications.putById(
      connection,
      {
        id: notification.id,
        body: {
          read_at: new Date().toISOString(),
        },
      },
    );
  });
  // No re-read possible (no read endpoint exposed in scope)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
