import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Test that non-owners (member or moderator) are forbidden from deleting another member's notification.
 *
 * This test verifies that permissions are correctly enforced by the API when an actor attempts to delete a notification not belonging to them. The operation should return a forbidden (403) error and the notification must remain accessible to its owner.
 *
 * Steps:
 * 1. Register two members: owner and non-owner.
 * 2. As the owner, create a notification for themselves.
 * 3. Attempt to delete the notification as the non-owner, assert a 403 error (forbidden).
 * 4. Attempt to delete as the owner (should succeed), confirming the notification remained until proper deletion.
 */
export async function test_api_discussionboard_notifications_notifications_test_delete_notification_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Register two members: owner and non-owner
  const owner: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(owner);

  const nonOwner: IDiscussionboardMembers = await api.functional.discussionboard.actors.members.post(connection, {
    body: {
      joined_at: new Date().toISOString(),
      status: "active"
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(nonOwner);

  // 2. As the owner, create a notification for themselves
  const notification: IDiscussionboardNotification = await api.functional.discussionboard.notifications.notifications.post(connection, {
    body: {
      discussionboard_member_id: owner.id,
      type: "announcement",
      title: "Test Notification",
      body: "Non-owner should not be able to delete this.",
      url: null,
      delivered_at: new Date().toISOString()
    } satisfies IDiscussionboardNotification.ICreate
  });
  typia.assert(notification);

  // 3. Attempt to delete the notification as the non-owner
