import api from "@ORGANIZATION/PROJECT-api";
import type { IOperationStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOperationStatus";

/**
 * Test deleting a topic tag with an invalid UUID format.
 *
 * Validates that the API returns a validation failure when attempting
 * to delete a topic tag using a string value that does not conform
 * to the expected UUID format.
 *
 * Steps:
 * 1. Attempt to delete a topic tag using "not-a-uuid" as the id.
 * 2. Assert the operation reports success: false.
 * 3. If a message is present, optionally check it refers to a UUID or format error.
 */
export async function test_api_discussionboard_boards_topicTags_test_delete_topic_tag_invalid_id_format(
  connection: api.IConnection,
) {
  // 1. Attempt deletion with an invalid id format
  const invalidId = "not-a-uuid";
  const output = await api.functional.discussionboard.boards.topicTags.eraseById(
    connection,
    { id: invalidId as any } // as any: bypass TypeScript format constraint for test purpose only
  );
  typia.assert(output);

  // 2. Assert that API responds with success: false
  TestValidator.equals("should fail for invalid uuid")(
    output.success
  )(false);

  // 3. Optionally: Assert error message refers to format or uuid
  if (typeof output.message === "string" && output.message.length > 0) {
    const msg = output.message.toLowerCase();
